quests[25703] = { id = 25703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gräueltaten", description = "<Obwohl seine Lippen sich nicht bewegen, könnt Ihr spüren, dass der Murlochäuptling mit Euch spricht.>\n\nDie Naga der Blutbrandung und die Steinteichmurlocs haben miteinander gelebt, solange wir denken können. Wir hatten unsere Meinungsverschiedenheiten, aber wir haben uns nie gegenseitig provoziert. Warum haben sie sich dann nur gegen uns gewandt?\n\n<Neptool wirft einen Blick über seine Schulter auf seine früheren Dorfbewohner.>\n\nSeht Ihr, was sie jetzt tun? Sie versklaven uns, opfern uns und zwingen uns, gegeneinander zu kämpfen. Ich werde sie aufhalten, {race}... und Ihr werdet meine Waffe sein.", sourceObjective = "Tötet 10 Barbaren der Blutbrandung und 10 Verzauberinnen der Blutbrandung.", completion = "Ihr habt Eure Sache gut gemacht, tapferer {class}. Ich bin erfreut, aber noch nicht zufrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25704] = { id = 25704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verrückte Magus", description = "Es bleibt nur noch eine Sache, die zu tun ist. Ihr müsst in Tonys Anwesenheit jemand mit einem großen Mojo töten.\n\nNein, nicht mich!\n\nDer alte Magus Tirth is' verrückt geworden, als er versucht hat, das Wasser aufzuhalten, als der Kataklysmus hereinbrach. Jetzt sucht er die Gegend südlich vom Stützpunkt heim.\n\nNehmt diesen Seelenstab und benutzt ihn auf seinem Leichnam. Dann bringt Tony zurück, und wir verfrachten ihn zurück in seinen Körper.\n\nIhr könnt mein Geistportal für den Weg benutzen.", sourceObjective = "Extrahiert die Seele von Tirth, dem verrückten Magus.", completion = "Jetzt werden wir Tony Zweihauer zurück ins Leben bringen. Seid ihr dann beide soweit, Mann?", sourceObjectiveStatus = "unverified-source-field" }
quests[25705] = { id = 25705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsche Götzen", description = "Neptulon der Gezeitenjäger ist unser Gott. Er war auch der Gott der Blutbrandung, aber anscheinend haben sie ihm den Rücken gekehrt. Jetzt verehren sie nur noch Azshara, ihre Nagakönigin. Ihr werdet die Abbilder Azsharas überall in ihren Siedlungen sehen, die aus Seestein gemeißelt wurden.\n\n<Der Murlocgeist betrachtet Eure Waffe.>\n\nDie Waffe wird reichen. Durchbohrt damit die Götzen der Azsh'ir. Man muss sie daran erinnern, dass unser Vater Neptulon der einzige ist, der wirklich die Meere regiert.", sourceObjective = "Zerstört 8 Götzen der Azsh'ir auf den Roten Weiten.", completion = "Ihr macht einen alten Murloc stolz, {race}.\n\nDanke und mögen die Wellen immer an Euren Füßen plätschern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25706] = { id = 25706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neptools Rache", description = "Noch so viele Nagatode werden den Stamm des Steinteichs nicht wieder zurückbringen, aber die Menge der Rache wird den Geistern meines Volkes helfen, leichter ihre Ruhe zu finden.\n\nViele der mächtigeren Angehörigen der Blutbrandung haben eine Feste in den Höhlen im Nordwesten errichtet. Tötet sie im Namen Steinteichs. Die anderen Angehörigen der Blutbrandung haben hier auf unserem Strand Gladiatorenbecken und Azsh'ir Altare errichtet, wo sie mein Volk gegeneinander kämpfen lassen und ihren falschen Gott verehren. Tötet sie im Namen des Gezeitenjägers.", sourceObjective = "Tötet 8 Akolythen der Blutbrandung, 8 Zeloten der Blutbrandung, 4 Glücksspieler der Blutbrandung und 4 Götzendiener der Blutbrandung.", completion = "Das letzte Mitglied des Steinteichs kann heute als Geisel genommen und morgen getötet werden, Landwandler... aber sie werden die Unterwelt in dem Wissen durchqueren, dass ein tapferer {race} ihren Tod rächte. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[25707] = { id = 25707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft des Steinteichs", description = "Die Steinteichkaulquappen, die sich noch auf dieser Kiste befinden, scheinen müde, verängstigt und beinahe vertrocknet zu sein. Sie müssen zum Wasser gebracht werden und zwar schnell.\n\nWenn Ihr diese Kiste vielleicht über den Strand in das Verbotene Meer weit jenseits der Küste der Roten Weiten ziehen könntet, dann haben sie eine Chance zu entkommen und die Steinteichmurlocs können vielleicht weiterleben...", sourceObjective = "Zieht die Verlassene Kiste der Blutbrandung zum Verbotenen Meer vor der Küste der Roten Weiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25708] = { id = 25708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallene Freunde", description = "Laut Eurem Bericht klingt es nicht so, als gäbe es viele Überlebende… nur rastlose Geister. Wir müssen ihnen wenigstens zu ihrer letzten Ruhe verhelfen.\n\n<Enohar nimmt einen tiefen Schluck Schwarzbier aus ihrem Krug.>\n\nKehrt zurück zur Havarieküste und vernichtet die Geister der Worgen, die dort ihr Unwesen treiben. Dadurch befreit Ihr sie von dieser Welt, sodass sie in die nächste weiterziehen können.", sourceObjective = "Tötet 13 ertrunkene Gilneer an der Havarieküste, um ihre Geister zu befreien.", completion = "<Enohar nimmt einen Schluck aus ihrem frisch aufgefüllten Krug.>\n\nAye, das habt Ihr gut gemacht, Junge. Ihr erfüllt die Allianz mit Stolz.", sourceObjectiveStatus = "unverified-source-field" }
quests[25709] = { id = 25709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein paar Schwanzfedern ausreißen", description = "Die gestrandeten Schiffe bereiten mir jedoch noch weitere Sorgen. Sie locken unglaublich viele Geier an. Sie haben zwar die Knochen schon sauber gepickt, aber wir können nicht zulassen, dass sie die Leichen unserer Freunde noch weiter entehren.\n\nBevor ich Braumeister wurde, war ich Jäger. Hier, nehmt diesen Bogen und vor allem diese Pfeile. Ich habe sie mit einer Tinktur benetzt, die diesen Knochenpflückern eine unangenehme Überraschung bereiten sollte.", sourceObjective = "Benutzt Enohars explosive Pfeile, um 20 Schwanzfederknochenpflücker an der Havarieküste zu töten.", completion = "Es ist eine Tragödie, was sich da an der Havarieküste abgespielt hat. Und es waren nicht einmal Soldaten, sondern nur brave Bürger auf der Suche nach einem neuen Zuhause.\n\nIch glaube, wir haben alles getan, was wir konnten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25710] = { id = 25710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwichtige Ablenkungen", description = "Nethergarde hat seit Jahren unerschütterlich dem Ansturm der Dämonen, die dieses Land heimsuchen, standgehalten. Unsere Wache endet nie, unsere Wachsamkeit lässt nie nach und unsere Tapferkeit ist unermesslich.\n\nWir haben diese Lande verteidigt, seit das Portal sich öffnete, aber jetzt hat dieses Hordengeschmeiß die Frechheit, sich uns in den Weg zu stellen? Wir haben SIE genauso beschützt wie uns selbst!\n\n<Lungertz mustert Euch.>\n\nSchauen wir mal, ob Ihr für den Kampf taugt. Tötet einen der Hordenspäher der Okril'lon, die an unseren Grenzen nagen.", sourceObjective = "Tötet einen Späher der Okril'lon außerhalb von Burg Nethergarde in den Verwüsteten Landen.", progress = "Was ist los - zu viel Angst, zu kämpfen?\n\nIch hätte es besser wissen müssen, als einem außenstehenden {class} wie Euch zu vertrauen. Man überlässt die Verteidigung von Nethergarde lieber seinen eigenen Leuten.", completion = "Hmm... nicht schlecht. Ihr seid schneller als die meisten meiner Leute. Bleibt in der Nähe, {name}... Vielleicht habe ich doch noch Verwendung für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25711] = { id = 25711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaltet die Okril'lon aus.", description = "Die Horde ist eine Landplage, derer wir uns entledigen werden, aber es ist schwieriger als erwartet. Ihr müsst dem ein Ende setzen.\n\nWestlich von Nethergarde übt die Hauptstreitmacht der Okril'lon Druck auf unsere Verteidigung aus. Im Moment besetzen sie die Mine von Nethergarde, wollen in die Versorgungslager vordringen und zum Schluss die Burg einnehmen. Ihr müsst sie dezimieren und ihren Vormarsch aufhalten, {name}.", sourceObjective = "Tötet 9 Infanteristen der Okril'lon beim Versorgungslager von Nethergarde.", completion = "Ihr seid ein Gewinn für die Allianz und die Kirin Tor, {name}. Gut gemacht.\n\nMit der Zeit werden unsere Streitkräfte die Mine zurückerobern und diese Hunde der Horde aus den Verwüsteten Landen vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25712] = { id = 25712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Herrscher von Nethergarde", description = "Lungertz ist ein starker Anführer, aber er ist stolz. Er untertreibt den Druck, den die Horde wirklich auf uns ausübt. Ohne unsere Mine... Nethergarde ist mittellos.\n\nWir müssen die Streitkräfte der Horde JETZT aus dem Versorgungslager entfernen. Dazu müssen wir ihren Kommandanten, Hauptmann Metlek, töten. Er ist kein überragender Anführer und zieht es vor, Befehle aus den hinteren Linien heraus zu bellen, aber dennoch könnte sein Tod uns den Sieg verschaffen, den wir brauchen.", sourceObjective = "Tötet Hauptmann Metlek am Versorgungslager von Nethergarde.", completion = "Danke, {name}. Dank Eurer Bemühungen bin ich zuversichtlich, dass wir mit der Zeit die Mine von Nethergarde zurückerobern können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25713] = { id = 25713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht ihre Waffen zunichte", description = "Sagt einmal... {name}, nicht wahr? Ich habe einen Vorschlag für Euch, der Explosionen beinhaltet. Interessiert?\n\nIch konnte nicht anders, als Eure Unterhaltung mit dem Rüstmeister anzuhören. Wisst Ihr... Ich arbeite an einer Sprengvorrichtung. Sie ist anderen Lebewesen gegenüber nicht sehr wirksam, aber verheerend gegen Artillerie. Wenn Ihr wieder hinausgeht, um diesen Orcs einen Besuch abzustatten, findet ein paar Vorräte der Feinde und probiert dieses Ding einmal aus. Wer weiß... vielleicht mögen sie ja auch Explosionen.", sourceObjective = "Benutzt Butterblumes Handgranate gegen 8 Waffenkisten der Okril'lon im Versorgungslager von Nethergarde.\n\nHaltet einen Sicherheitsabstand, wenn Ihr die Granaten verwendet, damit Ihr Euch nicht selbst in die Luft sprengt.", completion = "Aaah, das Geräusch, wenn Dinge \"bumm\" machen erfreut mein Herz und lässt es schneller schlagen. Ihr habt diesem Gnom den Tag versüßt, {name}", sourceObjectiveStatus = "unverified-source-field" }
quests[25714] = { id = 25714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behüter Mahar Ba", description = "Es ist Zeit für Euch, den Behüter aufzusuchen. Er ist in letzter Zeit etwas übellaunig und ich weiß nicht genau, warum.\n\nGeht oben auf den Magierturm und meldet Euch bei ihm. Ich habe hier keine Arbeit für Euch, aber ich bin sicher, dass er welche hat.", sourceObjective = "Meldet Euch bei Behüter Mahar Ba im Magierturm von Burg Nethergarde.", completion = "Meine Mitarbeiter haben das Richtige getan, Euch zu mir zu schicken. Ich habe ein Problem, das eine Bedrohung für das Sanktum von Nethergarde darstellen könnte. Ich brauche jemanden, der fähiger ist als die meisten anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25715] = { id = 25715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein genauerer Blick", description = "Wir haben schon unzählige Schiffe an der Küste im Südosten vorbeiziehen sehen und nie ist etwas Auffälliges passiert. Doch vor einigen Tagen warf ein Sturm mehrere Schiffe an die Küste, wo sie nun gestrandet liegen.\n\nIch würde einen Krug Nethergarde Bitter wetten, dass es Schiffe der Horde sind, wenn ich Nethergarde Bitter nicht so sehr lieben würde. Ich kann Euch jedoch mit Gold bezahlen, wenn Ihr Euch diese Schiffe genauer anseht und mir davon berichtet.", sourceObjective = "Späht die gestrandeten Schiffe an der Havarieküste in den Verwüsteten Landen aus.", completion = "Ihr habt {race} gesehen? Das klingt nicht gut.\n\nWorgengeister? Das klingt sogar noch schlimmer.\n\nDas waren keine Schiffe der Horde… das waren gilnearische Schiffe! Und sie waren sicher auf dem Weg nach Surwich am Ende des Besudelten Walds. Das ergäbe zumindest Sinn.\n\nWir müssen ihnen helfen, {name}! Die {race} sind unsere Verbündeten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25716] = { id = 25716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kultisten an der Schwelle", description = "Möglicherweise seid Ihr schon einigen Kultisten der Schattenanbeter begegnet, die in Höhlen südwestlich von Nethergarde hausen. Sie stellen keine direkte Bedrohung für unsere Burg dar, aber ich fürchte, dass sie etwas Furchtbares planen, das Eure Vorstellungskraft übersteigt.\n\nDie rangniederen Mitglieder tragen Zauberfokusse, die eine Antwort enthalten könnten. Bringt mir einige intakte davon her, wenn Ihr sie den Kultisten aus den Händen reißen könnt.", sourceObjective = "Besorgt 6 intakte Zauberfokusse eines Schattenanbeters von Zauberklingen der Schattenanbeter und Okkultisten der Schattenanbeter in den Verwüsteten Landen.", progress = "Die Kultisten werden sich nicht so einfach von ihren Fokussen trennen. Tötet sie schnell, bevor sie Eure Absicht erahnen.", completion = "Geschickt gemacht, {name}. Jetzt werden wir sehen, ob mein Verdacht berechtigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25717] = { id = 25717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dämonen und der Druide", description = "Das archäologische Institut konzentriert sich auf das Auffinden und Bewahren magischer Artefakte. Diese Exkursion konzentriert sich auf die dämonischen Artefakte, die dort verborgen sind, wo sich einst die Faulende Narbe befand.\n\nEin Worgendruide hat sich dort angesiedelt und lässt einen Wald wachsen. Allerdings scheint es ihm nicht so recht zu gelingen, da die Gegend immer noch von Dämonen verseucht ist.\n\nNun wie auch immer, der Wald steht unserer Exkursion im Weg, genau wie die Dämonen. Tötet die besudelten und kehrt zurück zu mir, damit wir uns um den Druiden kümmern.", sourceObjective = "Tötet 5 Verdammniswachenzerstörer, 5 Schreckenslordschänder, 5 verderbte Dunkelwaldtreants und 3 Teufelssporensumpflords im Besudelten Wald.", completion = "Ich danke Euch, {name}.\n\nIch sollte etwas ehrlicher zu Euch sein. Die Dämonen waren ein Ärgernis, aber sie sind nicht das eigentliche Problem. Dieser Worgendruide ist unser Problem", sourceObjectiveStatus = "unverified-source-field" }
quests[25718] = { id = 25718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man am besten weitermacht", description = "Dadurch, dass Ihr dort unten Dämonen getötet habt, bekamen unsere Späher genug Zeit, sich den Druiden einmal genauer anzusehen. Meine Informanten berichten mir, dass er Marl Wurmdorn heißt - er ist ein abtrünniger Druide aus Gilneas mit beachtlichen Kräften. Er wohnt in Maldraz, dem großen, verdrehten Baum mitten im Wald und irgendeine seltsame Kraft bewahrt ihn vor Unheil. Ob diese Kraft dämonischen oder natürlichen Ursprungs ist, müssen wir noch herausfinden.\n\nSprecht mit Elijah. Vielleicht hat er neue Informationen für Euch.", sourceObjective = "Meldet Euch bei Elijah Dämmerflug bei Sonnenschleiers Exkursionstrupp in den Verwüsteten Landen.", completion = "Rohan schickt EUCH, um seinen Druiden zu töten? Na schön.\n\nIhr solltet wissen: Marl Wurmdorn ist gleichermaßen Dämon wie Druide. Sogar ein Druide mit seiner Macht hat keine Chance gegen die dämonischen Energien, die dieses Land vollkommen durchziehen. Aber das ändert nichts daran, dass er für uns ein Hindernis ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25719] = { id = 25719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonisches Gefäß", description = "Es muss einen Weg geben, Wurmdorns Aufmerksamkeit zu erregen. Etwas, das seine Trance durchbricht. Etwas, das mit Sicherheit funktioniert.\n\nDie wenigen Wildtierarten, die es geschafft haben, sich im Besudelten Wald anzusiedeln, sind zweifellos von den latenten Energien des Landes in Mitleidenschaft gezogen. Eure Aufgabe ist es, ihre Kadaverteile einzusammeln und eine Möglichkeit zu finden, sie in ein Gefäß umzuwandeln. Egal ob Wurmdorns Trance druidischer oder dämonischer Natur ist, ein Gefäß mit besudeltem Tierfleisch, das groß genug ist, sollte in der Lage sein, diese zu durchbrechen.", sourceObjective = "Tötet besudelte Schwarzbären, besudelte Nachtpirscher und besudelte Kreischer im Besudelten Wald und versucht, ihre Kadaverteile zu einem dämonischen Gefäß zusammenzusetzen.", progress = "Dämmerflugs Plan ist gut. Habt Ihr das Gefäß, {name}?", completion = "Ausgezeichnet gemacht, {name}. Wir haben, was wir brauchen, um die Trance des Worgen zu durchbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25720] = { id = 25720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall des Marl Wurmdorn", description = "Wurmdorns unnatürlicher Wald bedroht den Fortschritt unserer Exkursion. Unsere Spitzhacken zerbrechen an ihren Wurzeln, sein Moos überwuchert unsere Ausgrabungsstätten und seine Tiere greifen meine Leute an. Wenn es um Ausgrabungen geht, ist mir eine dämonenverseuchte Einöde allemal lieber als ein Wald.\n\nNehmt das dämonische Gefäß und benutzt es gegen Marl Wurmdorn, um ihn aus seiner Trance zu holen. Kehrt zu mir zurück, wenn er nicht mehr unter uns weilt.", sourceObjective = "Tötet Marl Wurmdorn bei Maldraz in den Verwüsteten Landen. Ihr könnt das dämonische Gefäß benutzen, um ihn aus seiner Trance zu holen.", completion = "Jetzt, da dieser Druide von der Bildfläche verschwunden ist, können wir uns wieder unseren Ausgrabungen zuwenden. Die Welt ist voller mächtiger Artefakte, {name}. Ihr müsst nur den Willen haben, das Notwendige zu tun, um sie zu bekommen.\n\nNehmt ruhig eins von diesen hier. Das Institut für Archäologie teilt immer gerne seine Schätze mit anderen Mitgliedern der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[25721] = { id = 25721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kämpft gegen die Flut", description = "Ich bin hier, weil Muradin selbst wusste, dass diese Messstation jemanden braucht, der diese Schwachköpfe auf Trab bringt. Sie haben alle zu viel Angst vor den Wildtieren, um überhaupt etwas zu tun. Wenn ich will, dass sie ihren Allerwertesten hochbekommen, dann muss hier ein wenig aufgeräumt werden.\n\nZunächst einmal haben wir ein Problem mit Elementaren. Die Flut hat hier so ein Durcheinander angerichtet, dass selbst das Wasser hysterisch geworden ist.\n\nIch wette, Ihr habt noch nie einem ganzen See Sinn und Verstand eingeprügelt, aber genau das verlange ich jetzt von Euch. Ihr müsst diesen Elementaren richtig eine von mir verpassen.", sourceObjective = "Tötet 10 Flutelementare.", completion = "Wer hätte das gedacht. Es gibt tatsächlich jemanden hier, der Magni keine Schande macht - sein armes Herz aus Kies sei gesegnet.\n\nAllein dafür bekommt Ihr den ersten Schluck von dem Bier, mein Junge. Aber lasst Euch das nicht zu Kopfe steigen! Wir haben noch viel mehr verfluchte Arbeit zu tun und ich werde nicht dulden, dass Ihr vorzeitig schlapp macht!", sourceObjectiveStatus = "unverified-source-field" }
quests[25722] = { id = 25722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablagerungen, mein Lieber", description = "Die Zerstörung des Steinwerkdamms war keine Kleinigkeit. Wir sind hier, um herauszufinden, wie schlimm der Schaden ist. Eine riesige Wassermenge ist hier durchgetobt und wenn diese die Erde zu sehr gestört hat, könnte uns noch Schlimmeres bevorstehen.\n\nWir können einiges aus den Sedimenten der überfluteten Gegend ablesen. Ich brauche so viele Erdproben wie möglich. Ich würde es wirklich sehr zu schätzen wissen, wenn Ihr dort hinausgehen und noch einige Proben für mich sammeln würdet.", sourceObjective = "Sammelt 8 Flutsedimentproben ein.", progress = "Dann lasst mal das Sediment sehen.", completion = "Ah ja. Die gute Nachricht ist, sie sind perfekt. Die schlechte Nachricht ist, dass ich - sogar betrunken, wie ich bin - erkenne, dass ihre Farbe nicht dem Mutterboden hier entspricht\n\nDas bedeutet, dass es nicht gut für diese Gegend aussieht, {name}. Aber wir müssen noch mehr Tests durchführen, bevor wir das Handtuch werfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25723] = { id = 25723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreschen bringt Glück", description = "Die hiesigen Wildtiere sind offenbar von der Flut vollkommen verstört. Dieses Moor war einmal voller Krokilisken, aber ich habe noch keinen einzigen gesehen.\n\nWas ich gesehen habe, sind Dreschadons. Die hat es hier noch nie gegeben, also muss die Flut sie direkt aus Loch Modan hergeschwemmt haben.\n\nZum Glück für uns sind sie viel leckerer als Krokilisken und mir gehen gerade die Vorräte aus. Bringt mir Dreschadonfleisch für das Lager und ich werde Euch gern dafür bezahlen.", sourceObjective = "Besorgt 8 Dreschadonbrocken von verirrten Dreschadons.", progress = "Sind sie fleischig? Schauen wir mal.", completion = "Herrlich. Die kann man bestimmt gut braten und dem Lager bleibt eine Woche Pilzkekse erspart.", sourceObjectiveStatus = "unverified-source-field" }
quests[25724] = { id = 25724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostmähnenaggression", description = "Der Kataklysmus hat das Gleichgewicht der Kräfte in Dun Morogh in Frage gestellt, {name}. Ohne Warnung tauchte eine Welle Troggs aus den Höhlen in der Nähe von Gnomeregan auf und hat die Trolle der Frostmähnen überrannt. Die Trolle sind seitdem immer weiter nach Osten gezogen.\n\nIm Nordwesten, oben am Schimmergrat, gab es immer eine gewisse Präsenz der Frostmähnen, aber seit der Abwanderung sind wir jetzt von Trollen umgeben. Wir können nicht zulassen, dass die Trolle diesen Umstand zu ihren Gunsten ausnutzen. Meine Leute werden im Osten die Stellung halten und Ihr führt einen Schlag gegen den Schimmergrat.", sourceObjective = "Tötet 5 Seher der Frostmähnen und 7 Schneeschreiter der Frostmähnen auf Schimmergrat.", completion = "Wir sollten in der Lage sein, unsere Bemühungen auf den Rest der Trolle im Osten zu konzentrieren, aber es gibt immer noch das Problem mit den Wendigos im Graufelsbau.", sourceObjectiveStatus = "unverified-source-field" }
quests[25725] = { id = 25725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moosbuschbeeren", description = "Wir haben genügend Vorräte, aber wir benötigen Arzneien. Das halbe Lager hat einen gewaltigen Kater und ein Heilmittel wäre jetzt angebracht.\n\nZum Glück kenne ich ein gutes Hausmittel, das mir von meiner lieben alten Mutter beigebracht wurde. Wir brauchen nur ein paar hiesige Zutaten.\n\nSeid so gut und sammelt für mich ein paar Beeren von Moosbüschen. Sie wachsen hauptsächlich am Wasser im Schatten, also schaut entlang der Küste und in der Nähe anderer Pflanzen.", sourceObjective = "Sammelt 15 Handvoll Moosbeeren.", progress = "Wie viele habt Ihr gefunden?", completion = "Die sind genau richtig. Die Jungs werden bald wieder auf den Füßen sein, sobald ich das hier in etwas Essbares verwandelt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[25726] = { id = 25726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nivellierarbeiten", description = "Also gut, Ihr müsst mir helfen, mein Nivelliergerät zu finden.\n\nWas guckt Ihr so komisch? Richtig! Ich sagte mein Nivelliergerät! Das ist ein wichtiges Vermessungsinstrument!\n\nIch hab mir den Namen nicht ausgedacht, ok? Geht und schaut es nach! Ich habe es nur kurz auf einem Felsen liegen lassen und einer dieser furchtbaren Schlammlinge hat es verschlungen. Die kriechen überall hier herum, aber einer von ihnen müsste es noch in sich haben.", sourceObjective = "Findet ein Nivelliergerät bei einem schmierigen Schlammling.", progress = "Habt Ihr das Nivelliergerät gefunden?", completion = "Oh gut, es ist unbeschädigt! Vielen Dank.\n\nIhr, äh, solltet Euch dort vielleicht ein bisschen säubern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25727] = { id = 25727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drungeld Finsterblick", description = "Der Dunkeleisenklan hier führt nichts Gutes im Schilde. Und wenn Euch das überrascht, seid Ihr noch dämlicher als die Papiertiger da in dem Zelt. Muradin kann ja diesen rußgeschwärzten Schwachköpfen in Eisenschmiede gegenüber Lippenbekenntnisse ablegen, aber hier draußen zählen die nichts.\n\nLetzte Nacht gab es einen Überfall auf das Lager und ein Überfall ist einer zu viel. Ihr Anführer ist ein stämmiger Kerl mit Namen Finsterblick und er versteckt sich in der Höhle am südlichen Ufer des Flusses.\n\nBringt mir Finsterblicks Bart als Beweis, dass er keine Bedrohung mehr für uns und Eisenschmiede darstellt.", sourceObjective = "Tötet Dungeld Finsterblick und nehmt seinen Bart an Euch.", progress = "Zeigt mal her!", completion = "Ein Glück, dass wir den los sind! Ich werde das fiese Ding später verbrennen, damit es uns nicht das Lager zustinkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25728] = { id = 25728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baunzers wilder Ritt", description = "Jetzt braucht Herr Baunzer nur noch einen Engel, der ihm als Navigator dient. Würdest du dieser Engel sein, <Onkel/Tante>? Mit deiner Hilfe können wir auf die Klippe hinaus und ganz ganz viele Hordies töten! Was sagst du? Ach bitte, <Onkel/Tante>! BITTE BITTE BITTE!\n\nWenn wir genug Hordies töten, kauft Lord Brachweiher uns allen ein Eis!", sourceObjective = "Tötet 20 Goblintechniker und 5 Goblinernter.", completion = "<Lord Brachweiher hustet.>\n\nDas ist merkwürdig.\n\nIhr habt da draußen mit dem Roboter gute Arbeit geleistet. Ihr habt mich ein wenig auf dem falschen Fuß erwischt. Ich wusste nicht, dass das kleine Mädchen so...\n\n<Lord Brachweiher zeigt auf seine Schläfe und macht kleine Kreise mit seinem Finger.>\n\nBesonders ist...\n\nNaja, ist ja egal, wie die Sache erledigt wird, nicht wahr? Habe ich recht?\n\nWahrscheinlich.\n\nWollt Ihr ein Eis?", sourceObjectiveStatus = "unverified-source-field" }
quests[25729] = { id = 25729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerenzo der Verräter", description = "<Der Gnomcorder springt mit lautem Surren an.>\n\nBitte kommen, {name}! Seid Ihr da? Isch 'abe gese'en auf die Karte, dass Ihr seid in die Nä' von die Felskesselsee Wasserrad, ist das rischtisch?\n\nOffenbar 'at die Venture. Co sisch einquartiert bei die Rad. Ihr müsst umschauen Eusch, wenn Ihr dort seid. Solltet Ihr se'en die verräterische Gnom mit die Name Gerenzo Pfeifzang, Ihr müsst ihn treten kräftisch in die 'intern für misch und Gnomeregan! Isch werde zahlen fürstlisch!", sourceObjective = "Tötet Gerenzo Pfeifzang.", completion = "<Der Gnomcorder summt laut.>\n\nWunderbar. Jetzt isch kann streischen noch eine Name von meine Liste.\n\nIsch werde misch melden wieder.\n\nXakxak Ende!", sourceObjectiveStatus = "unverified-source-field" }
quests[25730] = { id = 25730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "HÜTET EUCH VOR FELSKIEFER!", description = "Auf Befehl der Leute, die nicht an einem Stück von einem richtig großen Fisch verschlungen werden wollen, ist der Zutritt zum Felskesselsee VERBOTEN! Jemand hat beschlossen, einen riesigen, zwergenfressenden Fisch im See anzusiedeln.\n\nEs wird dringend empfohlen, dem See fernzubleiben. Solltet Ihr allerdings der heldenhafte Typ sein und noch ein paar Freunde haben, tut uns doch den Gefallen und tötet das verdammte Ding! Vielleicht kann ich dann hier angeln, nicht wahr?\n\nFalls es Euch wirklich gelingen sollte, sucht mich in der Scherwindfeste für eine Belohnung auf.\n\n-Der alte Eisenbock", sourceObjective = "Tötet Felskiefer und bringt Felskiefers riesigen Zahn an Euch.", progress = "Habt Ihr das Ungeheuer getötet?", completion = "Wer hätte das gedacht. Ihr habt das Ungeheuer tatsächlich erwischt? Nun, abgemacht ist abgemacht! Hier ist Eure Belohnung!", sourceObjectiveStatus = "unverified-source-field" }
quests[25731] = { id = 25731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Spatz in der Hand", description = "Es ist Zeit, dieser Sache auf den Grund zu gehen. Wir müssen die Matrone dieser Wilden befragen, Marion Wurmschwinge. Wir werden sie lebend fangen. Das ist der Plan:\n\nDie Harpyien kommunizieren mit Signalfeuern über den Gebirgskamm hinweg. Wenn wir eines davon löschen, wird Marion sicher kommen, um zu sehen, was damit los ist.\n\nKämpft mit ihr, um sie abzulenken, während ich mich von hinten anschleiche und sie mir schnappe. Die Fragen zu stellen überlasse ich dann Euch. Los, holen wir sie uns, {name}!", sourceObjective = "Löscht ein Harpyiensignalfeuer, um die Aufmerksamkeit Marion Wurmschwinges zu erregen. Kämpft mit ihr, bis Thisalee sie einfängt, und befragt die Harpyienmatrone dann.", progress = "Marion hat den Schrein hier früher oft besucht. Himmelsfürst Omnuron wollte den Harpyien eine Chance geben, aber ich habe ihr nie vertraut.", completion = "Also sind die Harpyien Werkzeuge einer Art von Drachen, \"Sethria\".\n\nAber was tun die Drachen mit diesen Eiern? Und was ist das für ein \"besonderes\" Ei, das Sethria so unbedingt will?\n\nIch verstehe es nicht, {name}. Ich habe einen Bericht an Himmelsfürst Omnuron weitergeleitet. Er wird wissen, was als Nächstes zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25732] = { id = 25732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Hühnchen rupfen", description = "Wir haben es geschafft!\n\nNager ist erledigt und ich habe unseren Glitzerkram gefunden!\n\nDas sind gute Nachrichten.\n\nDas Kleinod ist verflucht und verwandelt jeden, der es berührt, in ein Skelett.\n\nDas sind schlechte Nachrichten.\n\nLaut diesen verfluchten Piraten kennt der König der Gilblin jedoch das Geheimnis, wie man diesen Fluch brechen kann.\n\nDas sind gute Nachrichten.\n\nIch kann aber keinen Fuß aus diesem Riff setzen, sonst bleibe ich auf ewig verflucht.\n\nDas sind schlechte Nachrichten.", sourceObjective = "Budd möchte, dass Ihr den Zinnplätter von König Gurboggel auf Gurboggels Fels besorgt.", progress = "Also, {race}…\n\nBrecht Ihr jetzt diesen Fluch oder was?", completion = "Das ist er?\n\nWie soll das denn den… Moment mal…", sourceObjectiveStatus = "unverified-source-field" }
quests[25733] = { id = 25733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pirscht von dannen", description = "Thelgenfelsen ist hier ein wichtiger Ort. Wir brauchen ihn, um dort den felsigen Untergrund und so was zu untersuchen.\n\nDa einem nichts im Leben leicht gemacht wird, gibt es am Thelgenfelsen riesige Höhlenpirscher. Sie sind so groß wie ein Zwerg und zweimal so hungrig. Wie ich schon sagte, diese modischen Kerle sind Forscher und keine Krieger, also wenn ich möchte, dass sie überhaupt etwas geschafft bekommen, müsst Ihr mir helfen, diese Viecher zu beseitigen.\n\nTötet so viele dieser Quälgeister, wie Ihr könnt und es soll Euer Schaden nicht sein, {name}.", sourceObjective = "Tötet 7 Höhlenpirscher und 7 Egelpirscher.", completion = "Gute Arbeit! Es würde mich nicht überraschen, wenn diese schrecklichen Dinger irgendwo da drin Eier abgelegt hätten, aber für den Moment reicht es.", sourceObjectiveStatus = "unverified-source-field" }
quests[25734] = { id = 25734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unten im Thelgenfelsen", description = "Ich bin jetzt nicht mehr ganz so wackelig auf den Beinen, also werde ich anfangen, das Nivelliergerät für meine letzten Messungen aufzubauen. Eins benötige ich noch von Euch.\n\nTief im Thelgenfelsen steht ein Seismograph, um alle Bewegungen der Erde aufzuzeichnen. Wenn sich seit der Katastrophe noch etwas bewegt hat, wird er es uns zeigen.\n\nDer Seismograph ist ganz unten in der Höhle. Findet ihn und bringt den Bericht, den er aufgezeichnet hat, zu mir.", sourceObjective = "Holt den seismischen Bericht von Thelgen aus Thelgenfelsen.", progress = "Dann schauen wir mal, was wir da haben, nicht wahr?", completion = "Wunderbar, mein Freund. Das dürfte alles sein, was wir brauchen. Schauen wir mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25735] = { id = 25735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pyrophorerz", description = "Telgenfelsen dort drüben ist so eine Art Wunder der Natur. Dort liegt die weltweit einzige bekannte Quelle von Pyrophorerz.\n\nDas Zeug ist selten, heiß begehrt und einfach nur lächerlich explosiv. Wenn man mit einer Spitzhacke aus Stahl daraufschlägt, gibt es ein Feuerwerk, das einen Raum voller Goblins vor Neid erblassen ließe.\n\nZum Glück habe ich für solche Gelegenheiten eine funkenresistente Spitzhacke erschaffen. Ich werde sie Euch leihen, wenn Ihr mir ein bisschen Pyrophorerz bringt. Natürlich bekommt Ihr auch etwas vom Gewinn ab.", sourceObjective = "Findet 8 Stücke Pyrophorerz.", progress = "Nun, Ihr seht so aus, als ob Euch kein Haar gekrümmt wurde.", completion = "Großartig! Wunderschön, dieses Erz.\n\nGut, dass Ihr Eure Spitzhacke nicht verloren habt. Die letzte Person, die ich dort hinausgeschickt habe, hat das untere Ende auf dem Boden aufschlagen lassen - und der Teil ist nicht funkensicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[25736] = { id = 25736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flutwellenkern", description = "Das ist alles, was von dem riesigen Elementar, der Euch angegriffen hat, übrig geblieben ist: eine schäumende Kugel des Wassers, die sich weiter Eures Griffes zu entziehen versucht.\n\nForba wäre über einen weiteren Beweis, dass Ihr noch eine Bedrohung vom Lager abgewendet habt, sicherlich erbaut.", sourceObjective = "Bringt den Flutwellenkern zu Forba Fliesmeißel.", progress = "Häh? Was habt Ihr da?", completion = "Das Ding hat ja immer noch Kampfeswillen! Erstaunlich!\n\nIhr seid zäh, {name}. Ich weiß das zu schätzen. Ich würde sagen, dass eine Belohnung angebracht ist, bevor Ihr fortgeht.\n\nTut weiterhin Euer Bestes für Eisenschmiede, verstanden? Und solltet Ihr jemals meiner Schwester begegnen, grüßt sie von mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[25737] = { id = 25737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorsichtige Verhandlungen", description = "Nach dem, was ich über diese Wassergoblins weiß, sollte das funktionieren.\n\nIch habe aus den Gegenständen, die Ihr mir zusammengeplündert habt, eine Haizahnkette gebastelt. Es ist nicht nur ein hübsches Schmuckstück, sondern auch eine Erinnerung an Nagers Tod. Schwer zu sagen, wie viele Gilblins dieses Monster bei lebendigem Leib verschlungen hat.\n\nBietet dem Anführer der Gilblins die Halskette an. Als Tausch benötige ich ein Artefakt, das als Zinnplätter bekannt ist.\n\nUnd beeilt Euch, <Bursche/Mädel>. Ich beginne schon, mein Fleisch zu vermissen...", sourceObjective = "Sprecht mit König Gurboggel.", sourceObjectiveStatus = "unverified-source-field" }
quests[25739] = { id = 25739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn die Horde Euch nicht erwischt...", description = "<Hauptmann Kosak hustet schwach.>\n\nWar unterwegs zum Weberpass, kam vom Basislager der Nordwachtexpedition im Süden. Hinterhalt. Nicht von Horde. Spinnen. Große, hässliche, haarige, gemeine Spinnen.\n\nDutzende in die Flucht geschlagen, vielleicht Hunderte. Konnte nicht mehr zählen. Überwältigt von der Königin. Hat ein Stück aus mir herausgebissen. Bin nur um ein Haar lebend entkommen. Sterbe vielleicht.\n\nMehr meiner Leute sind unterwegs. Muss sicheren Durchgang gewährleisten. Tötet Spinnenkönigin.\n\n<Hauptmann Kosak wird bewusstlos.>", sourceObjective = "Tötet Königin Silith.", completion = "<Hauptmann Kosak zwingt sich zu einem Lächeln.>\n\nMacht Euch um mich keine Sorgen. Jetzt, da der große Held die Spinnenkönigin getötet hat, wird alles gut.\n\nVerstärkung kann hier jetzt sicher passieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[25740] = { id = 25740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Fakten", description = "Der Drache Sethria muss aufgehalten werden. Wir wissen, dass sich ihr Nest im Süden an den südlichen Klippen des Hyjal befindet, aber das ist leider fast schon alles.\n\nIch habe Thisalee auf der Suche nach Fakten zu Sethrias Nest geschickt. Sie hat speziell um Eure Hilfe gebeten. Ihr scheint die junge Druidin schwer beeindruckt zu haben.\n\nTrefft Euch mit Thisalee direkt hinter dem Tunnel, der zu Sethrias Nest führt. Und vergesst nicht, wir sind hier auf der Suche nach Fakten. Tut bloß nichts Verrücktes!", sourceObjective = "Meldet Euch bei Thisalee am Eingang zu Sethrias Nest auf dem Hyjal.", completion = "Ah, {name}! Ich hatte gehofft, Euch hier draußen wiederzusehen.\n\nWas, Omnuron nennt dies eine \"Suche nach Fakten\"? Pah! Fakten findet man am besten bei Leichen.\n\nLasst uns etwas Schaden anrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25741] = { id = 25741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf die Zukunft vorbereiten", description = "Vergiftete Reisende kommen um die Scherwindfeste immer häufiger vor. Gerade vor ein paar Tagen fiel ein Hauptmann der Nordwacht den Spinnen der Weberkuhle zum Opfer. Er wäre an dem Gift gestorben, wenn ich kein Gegengift gehabt hätte. Leider ist mein Vorrat an Gegengift beinahe erschöpft.\n\nWenn Ihr nach Süden in Richtung Weberkuhle unterwegs seid, würdet Ihr freundlicherweise einige Kluftmoosgiftbeutel für mich besorgen? Ihr solltet sie von Kluftmoosspinnen erhalten.", sourceObjective = "Besorgt 10 Kluftmoosgiftbeutel.", progress = "Habt Ihr die Giftbeutel, um die ich Euch gebeten hatte, bekommen?", completion = "Das dürfte uns auf absehbare Zeit mit Gegengift versorgen. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25743] = { id = 25743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entscheidungen, Entscheidungen", description = "Das ist keine magische Lösung für meinen Fluch! Das ist nur ein Hammer!\n\nIch bin vielleicht verrückt, aber ich bin nicht dumm.\n\nIch werde das hier AUF GAR KEINEN FALL benutzen, um meinen Glitzerkram kaputt zu machen! Nicht nach allem, was ich durchgemacht habe, um an ihn zu kommen!\n\n<Budd hält einen Moment inne, um nachzudenken.>\n\nAber das bedeutet, dass ich bis in alle Ewigkeit hier unten festsitze...\n\nUnd ich habe doch gerade erst gelernt, wie man segelt.\n\nOhhh... ich kann mich nicht entscheiden.\n\nHier, nehmt Ihr den Hammer. Ich stelle den Glitzerkram einfach auf den Boden und schaue weg.", sourceObjective = "Benutzt den Zinnplätter, um den Zinnpropheten zu zerstören.", completion = "Oh, wie schön hätte es sein können…", sourceObjectiveStatus = "unverified-source-field" }
quests[25744] = { id = 25744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhandlungen", description = "{name}, Ihr habt den Turbodampfer gut verteidigt! Ich habe noch eine andere Aufgabe, bei der Ihr mir helfen könnt.\n\nIch habe Crazzle Flinkspross und Kravel Kohlebart nach Nordosten geschickt, um mit den Überlebenden der Zentauren zu verhandeln, weil es in ihrer Heimat, den Spalthufanhöhen, ein Ölvorkommen gibt.\n\nIch glaube, dass diese stinkenden Halbpferde von diesem Vorkommen keine Ahnung haben, und wir werden versuchen, die Bohrrechte für das schwarze Gold so günstig wie möglich zu erhalten. Ich habe das Gefühl, dass Ihr Euch um die Verhandlungen kümmern solltet.\n\nWas haltet Ihr davon?", sourceObjective = "Sprecht mit Crazzle Flinkspross in Spalthufanhöhen in Tausend Nadeln.", completion = "<Crazzles Augen leuchten auf.>\n\nIch habe Kravel Kohlebart hochgeschickt, um mit den Häuptlingen zu verhandeln, aber jetzt da Ihr hier seid, werden wir die Bohrrechte in null Komma nichts erhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25745] = { id = 25745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhandlungen", description = "{name}, Ihr habt den Turbodampfer gut verteidigt! Ich habe noch eine andere Aufgabe, bei der Ihr mir helfen könnt.\n\nIch habe Riznek und Rennstreckenleiter Zherin nach Nordosten geschickt, um mit den Überlebenden der Zentauren zu verhandeln, weil es in ihrer Heimat, den Spalthufanhöhen, ein Ölvorkommen gibt.\n\nIch glaube, dass diese stinkenden Halbpferde von diesem Vorkommen keine Ahnung haben, und wir werden versuchen, die Bohrrechte für das schwarze Gold so günstig wie möglich zu erhalten. Ich habe das Gefühl, dass Ihr Euch um die Verhandlungen kümmern solltet.\n\nWas haltet Ihr davon?", sourceObjective = "Sprecht mit Riznek in Spalthufanhöhen in Tausend Nadeln.", completion = "<Rizneks Augen leuchten auf.>\n\nIch habe Rennstreckenleiter Zherin hochgeschickt, um mit den Häuptlingen zu verhandeln, aber jetzt da Ihr hier seid, werden wir die Bohrrechte in null Komma nichts erhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25746] = { id = 25746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethrias Brut", description = "Unsere erste Aufgabe besteht darin, die Herde hier auszudünnen. An diesem Ort wimmelt es nur so von ihnen.\n\nTötet zunächst diese Drachkin und macht Euch erst später Gedanken darüber, warum wir hier sind.", sourceObjective = "Tötet 12 von Sethrias Dienern: Eine beliebige Kombination aus Zwielichtdrachkin oder Rüstungsschmieden der Zwielichtdrachkin.", completion = "Das scheint Euch zu liegen.\n\nIch mag Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25747] = { id = 25747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick nach vorne", description = "Der Admiral hat die Informationen, die Ihr für ihn gesammelt habt, genutzt, um einen Vorposten unter der Terrasse im Westen einzurichten. Er bereitet sich dort auf eine Art Angriff auf die Naga vor.\n\nIhr solltet sofort zu ihm gehen und ihm von den Massen berichten, die Ihr beobachtet habt. Unsere Streitmacht ist klein. Ich mache mir Sorgen um unsere Soldaten, wenn wir uns in einen waghalsigen Angriff stürzen.\n\nNehmt mein Seepferd. Es kennt den Weg.", sourceObjective = "Sprecht mit Admiral Dvorek unter der südlichen Terrasse in den Ruinen von Vashj'ir.\n\nBenutzt Wellensprecherin Valorens Seepferd, um den Vorposten schnell zu erreichen.", completion = "Schön Euch wiederzusehen, {class}. Ich dachte schon fast, wir hätten Euch bei dem törichten Botengang für die Wellensprecherin verloren.\n\nIst dabei wenigstens etwas herausgekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25748] = { id = 25748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deutliche Ziele", description = "Ich verstehe. Eure Nachrichten sind düster, aber ich bin nicht ganz unvorbereitet auf eine solche Lage. Ich wusste, dass unser Plan riskant ist, solange wir die genauen Zahlen der Naga nicht kennen, aber zu diesem Zweck haben wir ja diesen Vorposten eingerichtet.\n\nIch will Euch nicht belügen, {class}. Wenn wir die Naga nicht beschäftigt halten, werden sie uns angreifen. Wir haben weder die Anlagen noch die Männer, um eine geeignete Verteidigung zu errichten, daher kommt das für uns nicht in Frage.\n\nWir brauchen mehr Zeit. Könnt Ihr ihre Reihen im Süden ein wenig ausdünnen?", sourceObjective = "Tötet 10 Naga der Streitmächte, die sich unter der südlichen Terrasse auf der Grundebene zusammenziehen.", completion = "Auch im Süden scheinen sich mehr Naga zusammenzuziehen, als unsere Berichte angenommen haben. Wir müssen uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25749] = { id = 25749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ganz unvorbereitet", description = "Ich habe Euer Gespräch mit dem Admiral gehört. Ich weiß, dass das, was wir tun, wahnsinnig klingt, aber wir haben einfach keine andere Wahl. Dort in der Höhle sind Leute, die sich auf uns verlassen.\n\nIch habe Aufklärer auf den verschiedenen Klippen in der Gegend aufstellen lassen. Bei den ganzen verstreuten Nagaspähern in der Gegend geht ihnen die Munition rasend schnell aus. Könntet Ihr ihnen mehr Armbrustbolzen bringen, um uns etwas Zeit zu verschaffen?", sourceObjective = "Bringt 8 Schachteln mit Armbrustbolzen zu den Aufklärern der Allianz, die sich auf den Vorsprüngen unter der südlichen Terrasse befinden.", completion = "Ihr seid wahrscheinlich das zuverlässigste Wesen, das ich je getroffen habe. Ich wünschte, meine Männer wären nur halb so gründlich wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[25751] = { id = 25751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausreichende Inspiration", description = "Hallo! Ich reiße mir hier alle Beine aus, um den Angriff des Admirals vorzubereiten. Er hat große Hoffnungen und hochtrabende Pläne, um alle möglichen Dinge hoch in die Luft zu jagen! … Oder eher hoch ins Wasser? Ja, wohl eher das.\n\nAber um Dinge in die Luft zu jagen, braucht man SPRENGSTOFF! Ich habe keinen Sprengstoff. Es ist traurig. Sehr traurig.\n\nAber ich wurde ausreichend inspiriert, um eine Lösung zu finden. Die Tangblasen, die von den Ruinen hängen, enthalten ein überraschend explosives Gas. Könntet Ihr etwas davon für mich sammeln? Oh bitte, bitte!", sourceObjective = "Sammelt 8 aufgedunsene Tangblasen, die unterhalb der südlichen Terrasse hängen.", progress = "Tick, tack, tick, tack. Immer in Eile. Keine Zeit für neue Errungenschaften. Was würde ich nur dafür geben, wieder ein Labor zu haben!", completion = "Ihr seid wirklich mutig! Ich habe gesehen, wie Ihr alle möglichen Arten von Murlocs, Naga und spitzzähnigen Fischen bekämpft habt, aber das war nichts im Vergleich hierzu! Wie Ihr Euch diese Tangblasen einfach so unter den Arm klemmt ist eine ganz neue Ebene der Furchtlosigkeit. BUMM! Ihr könntet jede Sekunde in die Luft gehen.\n\nIhr seid ein {race} nach meinem Geschmack.", sourceObjectiveStatus = "unverified-source-field" }
quests[25752] = { id = 25752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzangriff", description = "Wir haben alles, was wir für den Angriff brauchen.\n\nWenn das, was Ihr sagt, wahr ist, solltet Ihr Euch während des Angriffs lieber fest an Euer Reittier klammern. Es ist sehr unwahrscheinlich, dass jemand von uns, der auf das offene Meer gerät, den Naga davonschwimmen kann.\n\nTötet so viele wie möglich. Wir werden den Angriff führen und treffen uns dann oben auf der zerbrochenen Terrasse, sobald wir die Sprengsätze aufgebraucht haben. Hoffentlich sind dann nur noch so wenige übrig, dass wir sie auf die altmodische Art erledigen können.", sourceObjective = "Sprecht mit Ingenieur Hexasept außerhalb des Gebäudes, um Euch dem Überfall anzuschließen. Benutzt dann Euren improvisierten Sprengstoff, um 100 Soldaten der Azsh'ir, 20 Wellenkreischer der Azsh'ir und 12 Archaeen der Azsh'ir zu töten.", completion = "Ihr habt Euch da oben großartig geschlagen! Ihr habt ihre Reihen zerschmettert, aber es waren viel mehr als geplant und die meisten unserer Truppen sind da draußen in den Massen der Naga untergegangen.\n\nWir müssen diese Position so lange wie möglich halten, um ihnen Zeit zu erkaufen. Hoffentlich schaffen es einige von ihnen noch zum Treffpunkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25753] = { id = 25753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallen, aber nicht vergessen", description = "Das war ein Desaster! Die meisten unserer Männer sind Speeren zum Opfer gefallen, noch bevor sie überhaupt in der Nähe des Treffpunkts waren!\n\nWir werden diese Position sicher nicht mehr lange halten können, bevor die Naga uns überrennen. Wir müssen uns in den Südwesten begeben und so viele der Männer retten, wie wir nur können. Geht und tut alles, was in Eurer Macht steht.\n\nLange halten sie nicht mehr durch. Bitte, beeilt Euch!", sourceObjective = "Rettet 6 verletzte freiwillige Angreifer.", completion = "Danke. Wirklich.\n\nWir müssen diese Männer so schnell wie möglich von hier wegbringen. Ich bin mir sicher, wir begegnen uns schon bald am Vorposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25754] = { id = 25754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einschätzung des Erfolgs", description = "Boshafte Rüpel… Sie haben mit diesen Speeren einen ganz schönen Schaden angerichtet.\n\n<Der Admiral zuckt ein bisschen, als er sich die Wunde an der Seite hält.>\n\nWir werden hier so lange wie möglich durchhalten, damit alle Männer es schaffen. Ich brauche jemanden, der ausspioniert, wie viele es noch sind. Ich möchte wissen, wie viel Schaden wir ihnen zugefügt haben. Eine ihrer größten Gruppen war um die Ecke im nordwestlichen Teil dieser runden Terrasse, die andere war etwas weiter im Norden, in einem kleinen Tunnel, der auch Teil der mittleren Ebene der Ruinen ist.\n\nSeid Ihr bereit?", sourceObjective = "Späht den nordwestlichen Teil der runden Terrasse und den Tunnel unter der Haupttreppe im Norden aus. Beide Orte befinden sich auf der Terrasse von Nar'shola, der mittleren Ebene der Ruinen.", completion = "Immer noch so viele? Sie müssen hier etwas sehr Wichtiges vorhaben, wenn sie so zahlreich auftauchen.\n\nIch will ehrlich zu Euch sein, {name}, denn das bin ich Euch schuldig: Ich weiß nicht, wie viel Hoffnung besteht. Wir werden uns in Kürze zurückziehen, aber wir werden uns nicht verteidigen können, falls sie zurückschlagen. Wir haben keinen Ort, an den wir flüchten können... Und uns gehen die Optionen aus.\n\nEs tut mir leid, ich sollte meine Gedanken für mich behalten. Tut mir einen Gefallen und erwähnt den Truppen gegenüber nichts davon. Ich werde mir etwas einfallen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25755] = { id = 25755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Das Massaker von Biel'aran", description = "Ja, ich weiß, es ist in Zeiten wie diesen viel verlangt, aber Ihr müsst Euch einen Moment lang von dieser Niederlage losreißen.\n\nIch werde mich um diese Soldaten kümmern. Ihr müsst jedoch den Ort im Westen finden, an dem die Schlacht mit dem General der Kvaldir ausgetragen wurde, von der Ihr mir erzählt habt. Von dort aus solltet Ihr mehr über die Erlebnisse der Kriegsmaid erfahren können. Ich habe das untrügliche Gefühl, dass der Schlüssel zum Sieg über die Naga in dieser Kriegsmaid liegt.\n\nBitte, beeilt Euch. Ich tue alles, was ich kann, um Euch Zeit zu verschaffen.", sourceObjective = "Werdet Zeuge des weiteren Verlaufs der Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge am Sterbeort des Generals der Kvaldir benutzt.", completion = "Ihr seid fertig! Gerade rechtzeitig. Ich glaube nicht, dass wir ihnen noch lange hätten standhalten können.\n\nEin Artefakt? Ist das vielleicht etwas, was wir gegen die Naga einsetzen können? Ich schätze, dann müssten wir es erstmal finden.\n\nDoch möglicherweise müssen wir uns erst dringenderen Angelegenheiten widmen, bis wir die Gelegenheit haben, dies weiter zu verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25756] = { id = 25756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehrt an Zherin!", description = "Wenn wir die Bohrrechte erhalten wollen, müssen wir wissen, was für ein Angebot die Horde unterbreiten wird. Wir können die Bohrrechte nur bekommen, wenn unser Angebot besser ist!\n\nDer Vermittler der Horde, Rennstreckenleiter Zherin, ist gerade vor Ort in Gesprächen mit den Khans. Ich schlage vor, Ihr begebt Euch auch dorthin, und überzeugt Zherin davon, das Angebot der Horde auszuhändigen.\n\nIhr müsst ihn nicht töten ... wir sind ja keine Wilden! Es reicht, wenn Ihr etwas arg an seinen Nerven zehrt.", sourceObjective = "Erhaltet das Angebot der Horde.", progress = "Habt Ihr das Angebot der Horde erhalten? Was bieten sie für die Bohrrechte an?", completion = "Was?! Woher hat die Horde so viel Gold für ein Angebot?\n\nSo viel Gold haben wir nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[25757] = { id = 25757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas hart zu Kohlebart!", description = "Wenn wir die Bohrrechte erhalten wollen, müssen wir wissen, was für ein Angebot die Allianz unterbreiten wird. Wir können die Bohrrechte nur bekommen, wenn unser Angebot besser ist!\n\nDer Vermittler der Allianz, Kravel Kohlebart, ist gerade vor Ort in Gesprächen mit den Khans. Ich schlage vor, Ihr begebt Euch auch dorthin, und überzeugt Kohlebart davon, das Angebot der Allianz auszuhändigen.\n\nIhr müsst ihn nicht töten ... wir sind ja keine Wilden! Es reicht, wenn Ihr ihn ein bisschen hart rannehmt.", sourceObjective = "Erhaltet das Angebot der Allianz.", progress = "Habt Ihr das Angebot der Allianz erhalten? Was bieten sie für die Bohrrechte an?", completion = "Was?! Woher hat die Allianz so viel Gold für ein Angebot?\n\nSo viel Gold haben wir nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[25758] = { id = 25758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Lücke in ihrer Rüstung", description = "Seht Ihr, was sie da tun? Sie statten ihre Drachkin mit Panzerplatten aus! Das muss Todesschwinges Idee gewesen sein.\n\nDiese Zwielichtmoloche sehen aus, als wären sie unbesiegbar, sobald sie fertig sind. Es muss doch einen Weg um diesen Panzer herum geben!\n\nGeht dorthin und holt Euch einige der Panzerplatten des Schattenhammers, die noch nicht angebracht wurden. Wir müssen herausfinden, wie wir das verhindern können!", sourceObjective = "Sammelt 8 Panzerplatten des Schattenhammers.", progress = "Habt Ihr ein paar Panzerplatten bekommen können? Musstet Ihr jemanden töten, um sie zu bekommen?\n\nIch hoffe doch sehr!", completion = "Schaut Euch diese Dinger an. Uff, die Runen schmerzen mir in den Augen. Diese hier soll Fleisch versengen? Im Ernst? Autsch! Moment mal…\n\nDiese Platten müssen direkt im Fleisch festgenietet werden. Die Schmerzen müssen unerträglich sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[25760] = { id = 25760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Die Invasion von Vashj'ir", description = "Das Bruchstück, das Ihr gefunden habt, scheint von Nagahand geschaffen zu sein. Ich hatte gehofft, ein starkes Fokusobjekt wie dieses für einen Zauber zu finden, an dem ich gerade arbeite. Mit diesem Zauber könnten wir einen Blick in die kürzliche Vergangenheit werfen.\n\nIch habe die Klinge verzaubert, aber Ihr müsst sie an einen Ort bringen, von dem wir wissen, dass ihr Besitzer sich dort aufgehalten hat. Ich möchte, dass Ihr zurück an die Stelle reist, wo Ihr die Klinge gefunden habt und sie dort benutzt.\n\nVielleicht können wir so mehr über die Pläne der Naga hier erfahren. Oder noch besser: Vielleicht finden wir einen ihrer Schwachpunkte, sodass wir eine bessere Chance haben, sie zu besiegen.", sourceObjective = "Benutzt die Klinge der Kriegsmaid der Naz'jar auf dem Schlachtfeld am südöstlichen Ende der Ruinen.", completion = "Eine Kriegsmaid? Davon habe ich noch nie gehört.\n\nSo wie Ihr mir die Sache schildert, scheinen die Truppen der Naga weitaus zahlreicher zu sein, als der Admiral es sich in seinen kühnsten Träumen vorstellt. Vielleicht können wir mehr von der Klinge erfahren, wenn wir andere Orte finden, an denen diese Kriegsmaid zugegen war. Ich habe nur Angst um den Admiral und seine Soldaten. Wir müssen sie warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25761] = { id = 25761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demontage", description = "Wir müssen diese Moloche aufhalten, bevor sie komplett in Rüstung gehüllt sind. Im Augenblick sind sie noch verwundbar, aber auch nur, wenn wir an den Platten vorbei in das kranke Fleisch darunter stoßen können.\n\nNehmt mein Messer und rammt es zwischen die Platten der bewehrten Moloche, um ihnen die Rüstung zu rauben.\n\nSobald sie aus ihrer Trance erwachen, solltet Ihr Euch auf einen harten Kampf gefasst machen. Löst einfach weiter ihre Rüstung und haltet diese Moloche auf!", sourceObjective = "Benutzt Thisalees Messer, um 3 Zwielichtmoloche zu wecken und zu töten. Das Messer kann mehrfach verwendet werden, um die Rüstung eines Molochs herunterzureißen.", progress = "Oh, gut.\n\nIhr seid noch am Leben.", completion = "Das nenne ich atemberaubende Klingenkunst, {name}!\n\nUnd wieder eine Bedrohung weniger auf dem Hyjal, um die wir uns sorgen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25762] = { id = 25762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die uralte Kohlenpfanne", description = "Was haben wir denn hier? <Einen/Eine:r> {race}? Ihr seid wohl hier, um unser Land mit Süßholzraspelei und Versprechen zu stehlen?\n\nIhr könnt mich nicht täuschen. Ich habe schon viele Winter gesehen und weiß, wie man mit jemandem wie Euch umgehen muss. Die Khans hören jedoch nicht mehr auf die Ältesten wie sie es einst taten.\n\nDa Ihr schon einmal hier seid, werde ich dafür sorgen, dass Ihr Euch nützlich macht. Als das Wasser über uns hereinbrach, hat der große Wassergeist Aquarian die uralte Kohlenpfanne in der Spalthufhöhle gelöscht.\n\nEntfacht die Kohlenpfanne wieder. Aquarian wird erscheinen. Bringt mir die heilige Flamme.", sourceObjective = "Entfacht die uralte Kohlenpfanne wieder und erhaltet die heilige Flamme.", progress = "Habt Ihr die heilige Flamme? Wagt es nicht, sonst mit mir zu sprechen, {race}!", completion = "Ihr habt mir diesen Gefallen getan, um Euch bei mir einzuschmeicheln. So leicht ist das aber nicht.\n\nIch weiß genau, was Ihr vorhabt. Das Meer hat es zwar nicht geschafft, aber der große Luftgeist wird Euch und Euer Volk für all die Vergehen bestrafen, die den Elementen gegenüber begangen wurden.\n\nVerschwindet aus meinen Augen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25763] = { id = 25763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kodex der Schatten", description = "<Dieses kunstvolle Buch besteht aus Hunderten von Seiten feinsten Pergaments und ist in Schiefer gebunden. Es ist in vielen Sprachen geschrieben, wovon Euch die meisten unbekannt sind. Aufwändig gezeichnete Bilder zeigen Zauberer oder gar ganze Gebäude, die hinter Schleiern aus Schatten verschwinden.>\n\n<Viele der Bilder zeigen magische Artefakte wie jene, die Ihr um das Lager herum seht. Ihr vermutet, dass die Drachendame Sethria etwas versteckt halten möchte. Thisalee will sicher davon erfahren!>", sourceObjective = "Meldet Thisalee Krähe bei Sethrias Nest auf dem Hyjal Eure Entdeckungen.", completion = "Sie tun was?\n\nSie verhüllen etwas? Aber natürlich! Damit unsere Späher in den Lüften es nicht mit ihren Adleraugen entdecken können!", sourceObjectiveStatus = "unverified-source-field" }
quests[25764] = { id = 25764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eierjagd", description = "Himmelsfürst Omnuron möchte, dass wir Avianas Ei finden. Ich kann Euch fast schon garantieren, dass es von einem von Sethrias Schattengeräten getarnt wird.\n\nSucht um das Lager herum nach Schattentarnungsgeneratoren und schaltet diese Dinger aus, bis Ihr das Ei gefunden habt.\n\nSobald Ihr es enttarnt habt, ruft die anderen Druiden herbei. Verteidigt das Ei, bis wir es in Sicherheit gebracht haben.\n\nLos, holt Euch das Ei, {name}!", sourceObjective = "Deaktiviert die Schattentarnungsgeneratoren, bis Ihr Avianas Ei gefunden habt. Sobald das Ei enttarnt wurde, verteidigt es, bis die Druiden der Klaue es in Sicherheit bringen können.", completion = "Wir haben es geschafft, {name}! Avianas Ei sollte bald schon sicher in den Zweigen ihres Schreins liegen.\n\nMeint Ihr, dass sie dann wirklich zu uns zurückkehren wird?", sourceObjectiveStatus = "unverified-source-field" }
quests[25765] = { id = 25765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sagt ihnen, Koko schickt Euch", description = "Nordwacht könnte wirklich <einen mächtigen/eine mächtige:r> {race} wie Euch gebrauchen. Wir haben eine Niederlage im Südlichen Brachland einstecken müssen und benötigen Eure Hilfe! Hättet Ihr Interesse daran, der Allianz behilflich zu sein?\n\nDie Bombe? Ja, sie ist ein Problem, aber das Steinkrallengebirge zeichnet sich nicht gerade durch seinen Grundstückspreis aus. Diese Gegend war schon ein Drecksloch bevor die Horde ihre Klauen danach ausgestreckt hat!\n\nIch überlasse die Entscheidung Euch. Wenn Ihr uns im Brachland aushelfen wollt, nehmt mein Pferd Blaustahl. Er grast an der Kreuzung südlich von hier. Er wird Euch an der ersten Orcsperre vorbeitragen.", sourceObjective = "Meldet Euch bei Truppenkommandant Valen am Basislager der Nordwachtexpedition im Steinkrallengebirge.", completion = "Kosak hat Euch geschickt, ja? Erstaunlich. Ich hatte mit Sicherheit angenommen, dass er bereits tot ist.\n\nNun, wenn Ihr es an der Blockade vorbei geschafft habt, dann habt Ihr auf jeden Fall etwas, das wir brauchen können.\n\nHabt Ihr irgendwelche Neuigkeiten von der Horde? Was machen sie? Wohin gehen sie? Erzählt mir alles.", sourceObjectiveStatus = "unverified-source-field" }
quests[25766] = { id = 25766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkanes Vermächtnis", description = "Der Zorn der Elementare hat im Herzen des Steinkrallengebirges eine Stadt der Hochgeborenen ans Licht gebracht.\n\nDirekt im Südwesten vor hier, hinter dem Sishircanyon, findet Ihr die Ruinen von Eldre'thar. In den Ruinen liegen Schätze, die seit zehntausenden Jahren nicht von Sterblichen angerührt wurden!\n\nNehmt dieses Gerät und benutzt es gegen die Geister der Hochgeborenen, die die Ruinen bewohnen. Es wird... ihre Seelen zur letzten Ruhe betten und außerdem wertvolle Daten sammeln, die ich später auswerten kann.", sourceObjective = "Benutzt das Gefängnis der Hochgeborenen, um 5 Geister der Hochgeborenen zu binden.", completion = "Ich versichere Euch, Ihr Einfaltspinsel, die Geister, die Ihr gefangen habt, finden jetzt ihre Ruhe. Lasst Euch nicht von ihren Protesten aus der Ruhe bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25767] = { id = 25767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen einfangen", description = "Der große Kataklysmus hat im Herzen des Steinkrallengebirges eine Stadt der Hochgeborenen ans Licht gebracht. Ihr müsst Euch nach Südwesten zu den Ruinen von Eldre'thar begeben. Wenn Ihr dort seid, durchsucht die Gegend nach uralten Relikten. Bringt die Relikte zu mir, damit ich sie untersuchen kann, {name}.\n\nLos! Wir dürfen den Arkanisten nicht warten lassen!", sourceObjective = "Besorgt 8 Relikte von Eldre'thar.", progress = "Habt Ihr die uralten Relikte gefunden?", completion = "Wunderbar! Arkanist Valdurian wird außerordentlich zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25768] = { id = 25768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer frei: Mirkfallonposten!", description = "Späherkommandant Barus ist am Mirkfallonposten im Nordwesten stationiert und hat die Bombe der Horde entdeckt. Der Heißluftballon von Krom'gar, an dem die Bombe angebracht ist, befindet sich momentan bei der neuen Goblintankstelle am Mirkfallonsee. Das könnte die Gelegenheit sein, die wir brauchen, um das Ding ein für alle Male zu beseitigen.\n\nNehmt Eure Siebensachen, {name}, und macht Euch auf den Weg! Späherkommandant Barus erwartet Eure Ankunft am Mirkfallonposten.\n\nUnd {name}, Eure Hartnäckigkeit macht der Stärke und Tapferkeit der Allianz alle Ehre!\n\nMöge der Ruhm mit Euch sein!", sourceObjective = "Meldet Euch bei Späherkommandant Barus am Mirkfallonposten im Steinkrallengebirge.", completion = "Ich nehme einmal an, dass Ihr den Heißluftballon von Krom'gar auf Eurem Weg hierher gesehen habt? Wenn nicht, lasst Eure Augen untersuchen. Er schwebt direkt über der Ölplattform.", sourceObjectiveStatus = "unverified-source-field" }
quests[25769] = { id = 25769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brachweiher ruft", description = "Ihr seid hier? Worauf wartet Ihr - eine persönliche, gravierte Einladung? Lord Brachweiher ruft, Narr! Geht zu ihm - jetzt!", sourceObjective = "Sprecht mit Lord Brachweiher an der Scherwindfeste im Steinkrallengebirge.", completion = "Schön, Euch wiederzusehen, {name}. Ich habe Neuigkeiten vom Mirkfallonsee.", sourceObjectiveStatus = "unverified-source-field" }
quests[25770] = { id = 25770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fasslieferung", description = "Also gut. Wir müssen dieses Bier sofort an seinen Bestimmungsort bringen!\n\nEisenschmiede hat eine Gruppe Feldmesser ausgeschickt, um den Schaden im Sumpfland zu überprüfen, der bei dem Dammbruch entstanden ist. Forba Fliesmeißel leitet die Expedition... und glaubt mir, Ihr wollt Euch nicht mit ihr anlegen!\n\nMit einer Ladung Bier bei ihr aufzutauchen, kann nicht schaden. Geht und bringt ihr das hier und sie wird Euch vielleicht bitten, die ein oder andere Arbeit für sie zu verrichten.", sourceObjective = "Bringt das Gebirgsjägerbier zu Forba Fliesmeißel an Fliesmeißels Messstation.", progress = "Ja? Was habt Ihr da für mich?", completion = "Ha! Schön, dass die hohlköpfigen Gebirgsjäger genug Grips haben, um das Bier einem richtigen Mann zu überlassen, damit die Arbeit auch erledigt wird.\n\nWillkommen in meiner Messstation. Wenn Euch der Sinn danach steht, Eisenschmiede zu helfen, indem Ihr die Jobs einiger nutzloser, fauler Säcke, die sich Zwerge nennen, übernehmt, dann seid Ihr an der richtigen Adresse!", sourceObjectiveStatus = "unverified-source-field" }
quests[25771] = { id = 25771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des einen Draeneis Plunder...", description = "Ein Bruchstück glitzernden Steins liegt vor Euch. Ihr spürt, dass dieser Gegenstand für jemand in den Verwüsteten Landen von großem Wert sein könnte.", sourceObjective = "Bringt das unvollständige Draenethystfragment zu Kum'isha dem Sammler in den Verwüsteten Landen.", progress = "Und? Draenethyst?", completion = "Nur ein Splitter? Pah! Das nützt mir gar nichts! Nehmt Eure Belohnung und geht mir aus den Augen.\n\nKlingt bekannt? Sollte es auch, weil ich es tausend Mal am Tag sage.\n\nOh, wie ich diese Welt hasse.", sourceObjectiveStatus = "unverified-source-field" }
quests[25772] = { id = 25772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kum'ishas Bemühungen", description = "Vor Euch liegt eine schimmernde Kugel. Ihr spürt, dass dieser Gegenstand für jemand in den Verwüsteten Landen von großem Wert sein könnte.", sourceObjective = "Bringt die fehlerlose Draenethystsphäre zu Kum'isha dem Sammler in den Verwüsteten Landen.", progress = "Habt Ihr eine fehlerlose Draenethystsphäre gefunden?", completion = "Einfach erstaunlich. Ich hatte so meine Zweifel, dass irgendwer noch eine Sphäre finden würde, aber hier ist sie und pulsiert in meinen Händen.\n\nGut gemacht, {name}!\n\nSolltet Ihr noch weitere finden - wobei ich glaube, dass das unmöglich ist -, dann bringt sie mir und ich werde Euch erneut belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25774] = { id = 25774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katzengold", description = "Von so viel Gold, wie die Horde anbietet, können wir NUR TRÄUMEN. {name}, wir müssen etwas unternehmen, oder wir laufen in Gefahr, die Bohrrechte nicht erhalten zu können!\n\nOh, Moment! Eine der Unterwasseruntersuchungen, die wir nach dem Kataklysmus angestellt haben, hat von einer Art Erz berichtet, das wie Gold aussieht und vom Untergrund nach oben befördert wurde. Das ist die Idee!\n\nReist zum alten Revier der Zentauren, Spalthufklippe und Spalthufhöhle westlich von hier, und grabt etwas von diesem Material aus.", sourceObjective = "Sammelt 8 Pyriterzbrocken.", progress = "Wenn Ihr genug von dem Pyrit bringt, können wir es mit schnell mit ein wenig Farbe aufarbeiten, schön stapeln, und diese Palette könnt Ihr dann dem Häuptling bringen.", completion = "Genial! Jetzt müssen wir nur die Goldfarbe finden - ich weiß, dass sie hier irgendwo ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25775] = { id = 25775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Katzengold", description = "Von so viel Gold, wie die Allianz anbietet, können wir NUR TRÄUMEN. {name}, wir müssen etwas unternehmen, oder wir laufen in Gefahr, die Bohrrechte nicht erhalten zu können!\n\nOh, Moment! Eine der Unterwasseruntersuchungen, die wir nach dem Kataklysmus angestellt haben, hat von einer Art Erz berichtet, das wie Gold aussieht und vom Untergrund nach oben befördert wurde. Das ist die Idee!\n\nReist zum alten Revier der Zentauren, Spalthufklippe und Spalthufhöhle westlich von hier, und grabt etwas von diesem Material aus.", sourceObjective = "Sammelt 8 Pyriterzbrocken.", progress = "Wenn Ihr genug von dem Pyrit bringt, können wir es mit schnell mit ein wenig Farbe aufarbeiten, schön stapeln, und diese Palette könnt Ihr dann dem Häuptling bringen.", completion = "Genial! Jetzt müssen wir nur die Goldfarbe finden - ich weiß, dass sie hier irgendwo ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25776] = { id = 25776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethrias Untergang", description = "Während Ihr Sethrias Nest überfallen habt, gab es einen regen Austausch von Botschaften zwischen uns und dem Schrein. Himmelsfürst Omnuron hat sich zunächst geziert, aber schließlich konnte ich meine Druidenfreunde überreden, einen direkten Angriff auf Sethria selbst zu wagen.\n\nAlle haben meinem Plan zugestimmt... unter einer Voraussetzung. IHR sollt den Angriff anführen.\n\nNehmt diese Signalrakete und stellt Euch Sethria auf dem hinteren Sims. Wenn sie ihr wahres Ich zeigt und in ihre Drachenform wechselt, schießt die Rakete ab und fordert Verstärkung an!", sourceObjective = "Tötet den Drachen Sethria. Sobald sie ihre wahre Form offenbart, benutzt die Signalrakete, um Verstärkung zu rufen.", progress = "Wenn ein geringerer Drache wie Sethria uns schon so viele Probleme bereiten kann, möchte ich gar nicht wissen, was der Schattenhammer sonst noch auf Lager hat…", completion = "Sethria ist nicht mehr! Ich wusste, dass es das Risiko wert ist.\n\nIch bleibe hier, um nach Überlebenden zu suchen, aber ich schätze, Eure Anwesenheit wird am Schrein gewünscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25777] = { id = 25777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorwärts nach Menethil", description = "Diese Neuigkeiten müssen so schnell wie möglich nach Menethil gelangen. Ich werde Euch mit meinem schnellsten Widder auf den Weg schicken, {name}.\n\nEr kennt den Weg - Ihr müsst nur darauf achten, dass Ihr fest im Sattel sitzt und Euch gut festhaltet.\n\nTrödelt nicht im Lager herum. Wir müssen die Nachricht schnell überbringen!", sourceObjective = "Liefert Fliesmeißels Bericht bei Hauptmann Starkfaust im Hafen von Menethil ab.", progress = "Willkommen in Menethil, Fremder. Ich hoffe, Ihr habt gute Neuigkeiten oder etwas Hochprozentiges bei Euch.", completion = "Lasst mich mal sehen.\n\nNa großartig... \"Schwerwiegende geologische Instabilität\"? \"Gefahr einer plötzlichen, massiven topologischen Destabilisierung\"?\n\nSchön zu hören, dass hier etwas Schlimmes passieren könnte. Dann sollten wir vielleicht besser unsere überflutete Stadt zusammenpacken und mit ihr irgendwo hinfliegen, wo es sicher ist!\n\nBah!", sourceObjectiveStatus = "unverified-source-field" }
quests[25778] = { id = 25778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsches Gold für schwarzes Gold", description = "Jetzt, da das \"Gold\" fertig ist, möchte ich, dass Ihr es zu Khan Ablinh bringt. Er wird davon so überwältigt sein, dass ich fast davon ausgehe, dass er uns dabei helfen wird, die Bohrtürme aufzustellen. Die Pferdestärke könnten wir gut gebrauchen.\n\nHaha, guter Witz, was? Pferdestärke?", sourceObjective = "Bringt die Palette voller \"Gold\" zu Khan Ablinh in den Spalthufanhöhen in Tausend Nadeln.", progress = "Was ist das? Wirklich viel Gold habt Ihr da.", completion = "Stellt die Palette einfach auf den Boden, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25779] = { id = 25779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falsches Gold für schwarzes Gold", description = "Jetzt, da das \"Gold\" fertig ist, möchte ich, dass Ihr es zu Khan Blizh bringt. Er wird davon so überwältigt sein, dass ich fast davon ausgehe, dass er uns dabei helfen wird, die Bohrtürme aufzustellen. Die Pferdestärke könnten wird gut gebrauchen.\n\nHaha, guter Witz, was? Pferdestärke?", sourceObjective = "Bringt die Palette voller \"Gold\" zu Khan Blizh in den Spalthufanhöhen in Tausend Nadeln.", progress = "Was ist das? Wirklich viel Gold habt Ihr da.", completion = "Stellt die Palette einfach auf den Boden, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25780] = { id = 25780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf Burg Menethil", description = "Wir hatten uns kaum nach der Flut wieder zusammengerauft, als die Dunkeleisenzwerge die Stadt angriffen. Meine Männer und ich sind der Stadtbevölkerung zu Hilfe geeilt, aber die irren Dunkeleisenzwerge haben sich in die Burg zurückgezogen.\n\nSie haben sich da richtig eingegraben und wir können die Burg nicht zerstören. Nicht jetzt, da die halbe Stadt schon in Trümmern liegt.\n\nNehmt meinen Platz ein, {name}. Ich würde mir den Anführer ja vorknöpfen, aber er hat mir einen schweren Schlag versetzt. Verschafft Euch Zugang zur Burg, tötet Horghast und bereitet allem ein Ende!", sourceObjective = "Tötet Horghast Loderwahn.", completion = "Er ist tot! Den Schöpfern sei Dank...\n\nMir gefällt gar nicht, wie die aussehen. Die Dunkeleisenzwerge, mit denen ich bisher zu tun hatte, waren niemals so verrückt. Irgendwas ist mit diesen Schwachköpfen geschehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[25790] = { id = 25790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Crazzle", description = "Ich bin NICHT dumm!\n\nGeht zu Eurem Meister zurück und sagt ihm, dass es mit der Sache NICHTS wird! Falls Ihr überhaupt lebend bei ihm ankommen solltet.", sourceObjective = "Sprecht mit Crazzle Flinkspross in Spalthufanhöhen in Tausend Nadeln.", completion = "Sie haben WAS?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25791] = { id = 25791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Riznek", description = "Ich bin NICHT dumm!\n\nGeht zu Eurem Meister zurück und sagt ihm, dass es mit der Sache NICHTS wird! Falls Ihr überhaupt lebend bei ihm ankommen solltet.", sourceObjective = "Sprecht mit Riznek in Spalthufanhöhen in Tausend Nadeln.", completion = "Sie haben WAS?!", sourceObjectiveStatus = "unverified-source-field" }
quests[25792] = { id = 25792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorwärts drängen", description = "Die meisten der Gebirgsjäger und Dampfpanzer in Dun Morogh kämpfen an der Frontlinie der Frostmähnen, die sich uns aus Südosten nähert. Wir können kaum die Trolle zurückhalten, geschweige denn, in ihr Dorf vorrücken und ihren Anführer angreifen.\n\nSie haben unseren Zugangspfad mit mysteriösen Totems blockiert, die allen sich nähernden Gebirgsjägern die Luft nehmen und ihre Opfer dadurch hilflos ihren Feinden überlassen. Auf diesem Stein ist eine Rune des Feuers eingraviert. Er sollte in der Lage sein, die Totems zu zerstören und unsere Gebirgsjäger zu befreien.", sourceObjective = "Benutzt die Rune des Feuers, um 4 Totems der Konstriktion an der Frontlinie der Frostmähnen zu zerstören.", completion = "Endlich gibt es mal gute Nachrichten von der Frontlinie der Frostmähnen. Ich werde dafür sorgen, dass die Gebirgsjäger sofort vorrücken und angreifen. Jetzt müssen wir unseren Gnomverbündeten am Depot signalisieren, dass sie ihren Vormarsch beginnen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25793] = { id = 25793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausufernden Tiefen", description = "Sinn und Zweck dieser Basis war es, im Steinkrallengebirge für Theramore Fuß zu fassen und eine Nachschublinie für die Nachtelfen zu eröffnen. Leider hat die Horde erbitterte Gegenwehr geleistet. Höllschreis Armeen sind mächtig und unnachgiebig. Ich habe so eine Heftigkeit von der Horde seit dem zweiten Krieg nicht erlebt.\n\nJetzt scheint es so, dass die Mine, die die Forscherliga ausgehoben hat, von der Horde dazu benutzt wird, uns zu umgehen. Wir müssen die Mine versiegeln!", sourceObjective = "Sprecht mit Stahlzeh McGee an den Ausufernden Tiefen im Steinkrallengebirge.", completion = "Versiegeln? Das ist ganz schön viel Arbeit, mein Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[25794] = { id = 25794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuflucht unter dem Meer", description = "Ich glaube, ich habe den Verfasser Eurer Notiz gefunden, Freund.\n\nWie es aussieht, braucht er dringend Hilfe, um zu überleben.\n\nIch werde eine meiner Seherkugeln vorbereiten, damit Ihr ihn selbst sehen könnt.", sourceObjective = "Benutzt Erunaks Seherkugel, um die Position der Tiefennebelgrotte zu sehen.", progress = "Habt Ihr Euch die Position der Höhle eingeprägt, {name}?", completion = "Wir müssen uns beeilen!\n\nWie Ihr seht, hat er nicht mehr viel Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25795] = { id = 25795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zum Schrein", description = "Avianas Ei sollte sicher am Schrein angekommen sein. Geht ruhig und seht es Euch an! Choluna weiß sicher, was zu tun ist.\n\nIch werde unsere Aufgabe hier noch abschließen und stoße dann später zu Euch.", sourceObjective = "Kehrt zu Choluna am Schrein von Aviana auf dem Hyjal zurück.", completion = "{name}! Ist es wahr, dass Ihr einen Angriff gegen einen Zwielichtdrachen geführt habt?\n\nIhr seid wirklich der Herold der Ahnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25796] = { id = 25796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enteignung", description = "Es ist Schicksal, das wir dieses Öl erhalten haben. Dass die Zentauren diesen Ort gewählt haben, als das Meer über uns hereingebrochen ist, ist Pech.\n\nPech für sie, sollte ich sagen.\n\nSie haben uns ins Gesicht gespuckt, {name}. Wir haben ihnen ein großzügiges Angebot unterbreitet, und es war ein Fehler, es nicht anzunehmen. Jetzt werden... werdet Ihr ihnen zeigen, worin dieser Fehler lag.\n\nVertreibt die Zentauren von den Spalthufanhöhen. Das Öl muss fließen!", sourceObjective = "Tötet 15 Zentauren der Spalthufanhöhen.", completion = "Das wird ihnen eine Lektion erteilen. Ihr habt die Zentauren so sehr eingeschüchtert, dass wir nur sehr wenig Wachen des Turbodampfers brauchen werden, um das Gebiet zu sichern.\n\nZumindest wird es so sein, nachdem wir mit ihrem angeblichen Anführer, dem Luftelementar, fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25797] = { id = 25797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enteignung", description = "Es ist Schicksal, das wir dieses Öl erhalten haben. Dass die Zentauren diesen Ort gewählt haben, als das Meer über uns hereingebrochen ist, ist Pech.\n\nPech für sie, sollte ich sagen.\n\nSie haben uns ins Gesicht gespuckt, {name}. Wir haben ihnen ein großzügiges Angebot unterbreitet, und es war ein Fehler, es nicht anzunehmen. Jetzt werden... werdet Ihr ihnen zeigen, worin dieser Fehler lag.\n\nVertreibt die Zentauren von den Spalthufanhöhen. Das Öl muss fließen!", sourceObjective = "Tötet 15 Zentauren der Spalthufanhöhen.", completion = "Das wird ihnen eine Lektion erteilen. Ihr habt die Zentauren so sehr eingeschüchtert, dass wir nur sehr wenig Wachen des Turbodampfers brauchen werden, um das Gebiet zu sichern.\n\nZumindest wird es so sein, nachdem wir mit ihrem angeblichen Anführer, dem Luftelementar, fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25798] = { id = 25798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt den Turm!", description = "Ich werde diesen Ort nicht mit leeren Händen verlassen! Ihr etwa?\n\nIch bin mir sicher, dass Ihr Euch gefragt habt, was wohl in der riesigen Kiste ist. Nun, Ihr müsst nicht länger warten. Bringt einen unserer Bohrtürme zu den Öltümpeln, und bohrt nach Öl für uns.\n\nIhr müsst natürlich damit rechnen, dass die Zentauren angreifen werden. Verteidigt den Turm lange genug, um ein oder zwei Fässer füllen zu können.", sourceObjective = "Verteidigt den Ölbohrturm.", completion = "Öl! Schwarzes Gold! Tanaristee!\n\nWir sind reich! Jetzt müssen wir uns nur den übrigen lästigen Zentauren annehmen. Mit dem ganzen Gold, das wir verdienen werden, können wir uns sicher leisten, sie auf irgendeine andere Klippe umzusiedeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[25799] = { id = 25799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigt den Turm!", description = "Ich werde diesen Ort nicht mit leeren Händen verlassen! Ihr etwa?\n\nIch bin mir sicher, dass Ihr Euch gefragt habt, was wohl in der riesigen Kiste ist. Nun, Ihr müsst nicht länger warten. Bringt einen unserer Bohrtürme zu den Öltümpeln, und bohrt nach Öl für uns.\n\nIhr müsst natürlich damit rechnen, dass die Zentauren angreifen werden. Verteidigt den Turm lange genug, um ein oder zwei Fässer füllen zu können.", sourceObjective = "Verteidigt den Ölbohrturm.", completion = "Öl! Schwarzes Gold! Tanaristee!\n\nWir sind reich! Jetzt müssen wir uns nur den übrigen lästigen Zentauren annehmen. Mit dem ganzen Gold, das wir verdienen werden, können wir uns sicher leisten, sie auf irgendeine andere Klippe umzusiedeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[25800] = { id = 25800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn das Leben dir Krabben schenkt...", description = "Es gibt hier viel zu tun, {class}, aber wir dürfen die Augen nicht vor den Geschenken des Schicksals verschließen.\n\nAls die Flut über unsere Häuser hereinbrach, schwemmte sie viele Meeresbewohner an. Die Bucht von Menethil ist jetzt voller großer Krabben, die genau richtig sind, um sie einzusammeln.\n\nWenn das Leben dir Krabben schenkt, geh Krabbenfischen, sag ich immer. Bringt mir die größten und fleischigsten Scheren, die Ihr finden könnt und ich bezahle Euch.", sourceObjective = "Findet 5 fleischige Kriecherklauen von Hafenkriechern.", progress = "Vergesst die kleineren Scheren - das Fleisch ist die viele Arbeit, es aus den Scheren zu holen, nicht wert.", completion = "Ein herzhaftes Meeresfrüchtedinner wird die Stimmung bei allen heben und uns dabei helfen, die Stadt wieder aufzubauen. Danke für die Hilfe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25801] = { id = 25801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klauen aus der Tiefe", description = "Murlocs kriechen aus den tiefen Wassern und bauen ihre Dörfer entlang der Küste. Sie überfallen unsere Fischer und Händler und müssen aufgehalten werden.\n\nEiner dieser Murlocs, Gobbler, streift mit den anderen Murlocs der Blaukiemen umher und plündert die Händler entlang der Straße aus, wobei sie sich danach immer in die Sicherheit der nahegelegenen Hütten zurückziehen. Unsere Händler sind in Gefahr und wir sind bereit, für ihre Sicherheit zu zahlen.\n\nGobbler strolcht in der kleinen Bucht nördlich von hier herum. Findet ihn, erschlagt seine Artgenossen und bringt mir seinen Kopf.", sourceObjective = "Holt Euch Gobblers Kopf von Gobbler und tötet 12 beliebige Murlocs der Blaukiemen.", progress = "Unsere Händler werden nicht sicher sein, bis wir Gobbler und diese Murlocs losgeworden sind.", completion = "Ah, gut gemacht, {name}.\n\nBitte nehmt dies als Bezahlung für die Erfüllung Eures Vertrages mit der Handelsmarine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25802] = { id = 25802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waren-Wiederbeschaffung", description = "Vor nicht allzu langer Zeit wurde ein Handelsschiff, die 'Blinde Prinzessin', von Murlocs überfallen. Obwohl das Schiff unversehrt entkam, wurde ein Großteil seiner Fracht von den Kreaturen über Bord gezogen, darunter eine äußerst wertvolle Statuette von Terenas Menethil. Wir möchten, dass die Statuette geborgen wird.\n\nDurchsucht die Hütten der Murlocs an der Küste nach Kisten, Fässern und anderen Spuren von verlorener Fracht. Findet die Statuette von Menethil und bringt sie mir wieder.", sourceObjective = "Durchsucht die Kisten und Fässer in den Murloclagern an der Küste.", completion = "Diese Kiste ist mit klauenartigen Kratzern übersät und zeigt Spuren eines Wasserschadens. Das Aufbrechen enthüllt durchnässtes und verfaultes Stroh, als wäre etwas Wertvolles in dieser Kiste aufbewahrt worden. Ihr durchwühlt das Stroh...\n\n... und findet eine Handvoll rot gefärbter Flaschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25803] = { id = 25803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche geht weiter", description = "Ihr durchsucht gründlich diese Ansammlung von Murlochütten, findet aber keine Spur der Statuette von Menethil.\n\nVielleicht gibt es in einer der beiden nahe gelegenen Hütten im Norden und Nordosten mehr Hinweise.", sourceObjective = "Sucht nach der Statuette von Menethil.", completion = "Dieses Fass ist weitgehend unberührt. Als Ihr es öffnet...\n\n... schlägt Euch der stechende Geruch von Käse entgegen. Er ist etwas feucht, aber immer noch schmackhaft!", sourceObjectiveStatus = "unverified-source-field" }
quests[25804] = { id = 25804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche in weiteren Hütten", description = "Dieses Grüppchen Murlochütten offenbart auch nach einer gründlichen Überprüfung nichts.\n\n... Aber Ihr seid Euch sicher, dass der nächste Anhaltspunkt, den Ihr findet, nützlich sein wird.\n\nEine der Hütten nördlich von hier muss die Statuette von Menethil enthalten!", sourceObjective = "Sucht weiter in den Hütten der Murlocs nach der Statuette von Menethil.", completion = "Dieses Fass ist unter Schlamm und Gras halb begraben...", sourceObjectiveStatus = "unverified-source-field" }
quests[25805] = { id = 25805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückgabe der Statuette", description = "Nachdem Ihr das Fass aus dem Dreck gezogen und geöffnet habt, findet Ihr eine in dünnes Stroh eingepackte, silbrige Figur. Sie stellt einen jungen, langhaarigen Paladin mit erhobenem Hammer dar.\n\nDies kann nur die Statuette von Menethil sein! Ihr müsst sie nun zu Karl Boran in den Hafen von Menethil zurückbringen.", sourceObjective = "Bringt Karl Boran im Hafen von Menethil im Sumpfland die Statuette von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[25806] = { id = 25806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben die Assass in... ach, egal", description = "Ah, die Forscherliga - welche glanzvolle Gruppe von Schwachköpfen. Wir haben nicht nur die Geister der Tauren am Hals, die Forscherliga hat es ebenfalls geschafft, eine Hintertür für die Hauptbasis der Horde im Steinkrallengebirge - der Feste Krom'gar - zu öffnen.\n\nJetzt bringen Auftragsmörder von Krom'gar alle in der Mine um, ohne dass man auch nur einen Mucks hört.\n\nIhr müsst da hineingehen und aufräumen.\n\nBeinahe hätte ich vergessen, Euch diese Brille zu geben. Setzt sie sofort auf. Damit werden alle getarnten Assassinen in der Mine sichtbar.", sourceObjective = "Tötet 12 Auftragsmörder von Krom'gar.", sourceObjectiveStatus = "unverified-source-field" }
quests[25807] = { id = 25807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wiedergeburt eines Ahnen", description = "Ich bin davon überzeugt, dass IHR der Herold Avianas seid, {name}. Ihr wart es, der sie zuerst gesehen hat und ihre Essenz aus den Klauen eines Drachen errettete.\n\nJa, ich glaube, dass Aviana in diese Welt wiedergeboren wird. Und Ihr habt die Ehre, sie über die Schwelle zu führen.\n\nNehmt dieses Rauchwerk und verbrennt es vor Avianas Ei im Raum direkt über mir.\n\nDie Ahnin ist nah, {name}. Unsere Errettung steht kurz bevor!", sourceObjective = "Benutzt das Rauchwerk des Herolds vor Avianas Ei im Schrein von Aviana.", completion = "Ich… lebe.\n\nDiejenigen, die versucht haben, mich zu verderben und meine Kinder zu stehlen, werden bald den Hieb meiner Klauen spüren, {class}. Glaubt mir.\n\nDringt weiter auf den Hyjal vor. Ich werde mich sammeln und die anderen Ahnen um mich rufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25808] = { id = 25808, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist das Ding an?", description = "<Der Gnomcorder summt energiegeladen. Man hört Leutnant Paulson am anderen Ende.>\n\nDämlicher Gnomschrott... Ist da IRGENDWER? {name}, seid Ihr da?\n\nVielleicht ist <er/sie> tot.\n\nFalls Ihr mich hören könnt - wir haben gerade die Nachricht erhalten, dass eine Meisterassassine der Horde sich in den Minen befindet und die anderen Auftragsmörder befehligt. Findet sie, tötet sie und meldet Euch bei mir.\n\nPaulson Ende.", sourceObjective = "Tötet Meisterassassine Kel'istra.", completion = "Gut gemacht, {name}! Eure Arbeit in den Minen war die eines Profis. Wie wäre es, wenn Ihr mir jetzt meine Brille zurückgebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25809] = { id = 25809, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst niemanden zurück!", description = "Hordenmonster!\n\n<Korporal Wocard spuckt aus.>\n\nSchaut Euch das hier an! Sie haben Unschuldige getötet! Zivilisten!\n\nHört zu, {name}, Ihr müsst uns helfen. Geht in die Ausufernden Tiefen und sucht nach überlebenden Minenarbeitern. Wenn einige überlebt haben, werden sie wohl vollkommen verängstigt sein! Sucht in allen Nischen und Winkeln der Mine. Vielleicht sogar in den Minenwagen! Es gibt ganz bestimmt Überlebende, die sich irgendwo versteckt haben.", sourceObjective = "Rettet 8 Verängstigte Minenarbeiter.", completion = "Dem Licht sei Dank! Ihr seid wahrlich ein rechtschaffendes Instrument der Macht! Die Allianz kann sich glücklich schätzen, Euch zu haben, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25810] = { id = 25810, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brutstätte muss brennen", description = "{name}! Choluna hat die Wahrheit gesprochen: Die Göttin ist zurückgekehrt! Ein Wunder ist geschehen.\n\nIhr habt zwar den Zwielichtdrachen Sethria töten können, wir haben jedoch noch nicht alle Eier ausfindig gemacht, die die Harpyien ihr gebracht hatten. Thisalee und ich haben ihnen nachgespürt und sind dabei auf eine große Brutstätte in den Feuerlanden gestoßen. Sie ist nicht von dieser Welt, also kann Aviana Euch nicht begleiten.\n\nFliegt nach Süden und tretet durch das Flammentor in der Mitte des Tals. Farden Klauenwürger ist vorausgesandt worden und wird im Inneren auf Euch warten.", sourceObjective = "Reist durch das Flammentor in der Mitte der Flammenschneise auf dem Hyjal. Sprecht mit Farden Klauenwürger, sobald Ihr hindurchgegangen seid.", completion = "Also ist es wahr. Aviana ist mit Euch als Herold zurückgekehrt.\n\nEs gibt hier viel zu tun. Wir sind tief im Herzen der Feuerlande. Sethria hat gestohlene Eier vom Hyjal hierher geschmuggelt, um ihre eigenen abstoßenden Kreaturen zu züchten: Raubvögel, die für den Krieg ausgebildet sind.\n\nIch hoffe, dass Ihr bereit seid, zurückzuschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25811] = { id = 25811, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stilllegung", description = "Um diese Mine stillzulegen, müsst Ihr die tragenden Pfeiler in die Luft jagen. Ich kann Euch den benötigten Sprengstoff zur Verfügung stellen, aber Ihr müsst Euch an den Auftragsmördern von Krom'gar vorbeischleichen, um alle Träger zu erreichen.\n\nDie gute Nachricht - wenn man das so nennen kann - ist, dass wir die tragenden Pfeiler immer mit einem großen X markiert haben. Schaut nach diesen Markierungen und befestigt das Dynamit in ihrer Nähe. Sobald ihr das Dynamit angebracht habt, kommt wieder hier hoch und ich werde die Sprengung auslösen.\n\nKabumm!", sourceObjective = "Verankert jeweils ein Dynamitbündel am ersten, zweiten, dritten und vierten Träger.", completion = "Wird schon schiefgehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25812] = { id = 25812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlenforscher", description = "Schnell, {name}!\n\nBegebt Euch sofort zu dieser Höhle.\n\nWir werden Euch folgen und sicherstellen, dass Euch sonst niemand folgt.", sourceObjective = "Sprecht mit dem Gefreiten Pollard in der Tiefennebelgrotte.", completion = "Ein… ein {race}? Hier?\n\nIch muss wahnsinnig sein…", sourceObjectiveStatus = "unverified-source-field" }
quests[25813] = { id = 25813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn erklingen lassen", description = "Dieser alte, verbitterte Zentaur Himmelsrufer Vrakthris hat den großen Luftgeist erwähnt, ein von den Zentauren verehrtes Wesen. Uns diesem Wesen anzunehmen ist der letzte Schritt in der Sicherung der Anhöhen.\n\nIch habe gesehen, wie sie das große Horn oben auf dem Hügel erklingen haben lassen, um den Luftelementar zu rufen. Er gab ihnen Befehle und verschwand gleich darauf wieder.\n\nLasst das Horn erklingen, {name}.", sourceObjective = "Tötet Whrrrl.", completion = "Nun wird ihnen wohl kein magischer Luftzauber zu Hilfe eilen, wenn wir das Gebiet an uns nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25814] = { id = 25814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn erklingen lassen", description = "Dieser alte, verbitterte Zentaur Himmelsrufer Vrakthris hat den großen Luftgeist erwähnt, ein von den Zentauren verehrtes Wesen. Uns diesem Wesen anzunehmen ist der letzte Schritt in der Sicherung der Anhöhen.\n\nIch habe gesehen, wie sie das große Horn oben auf dem Hügel erklingen haben lassen, um den Luftelementar zu rufen. Er gab ihnen Befehle und verschwand gleich darauf wieder.\n\nLasst das Horn erklingen, {name}.", sourceObjective = "Tötet Whrrrl.", completion = "Nun wird ihnen wohl kein magischer Luftzauber zu Hilfe eilen, wenn wir das Gebiet an uns nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25815] = { id = 25815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dritte Flotte", description = "Ich war einst Erster Maat auf der 'Herrin der Meere', einem Linienschiff der Dritten Flotte von Kul Tiras, der Verlorenen Flotte. Verloren deshalb, weil die Flotte auf ihrer letzten Reise von roten Großdrachen angegriffen wurde. Großdrachen, die von Orcs geritten wurden!\n\nWir hatten keine Chance gegen das Drachenfeuer... und unsere Flotte ging just vor dieser Küste hier brennend unter. Ich bin der einzige Überlebende von diesen armen Schiffen.\n\n... Bringt mir meinen Met, {class}. Er ist unten im Keller des Gasthauses. Auch wenn ich ihn so weit von mir entfernt verstaut habe, ich komme doch nicht ohne aus.", sourceObjective = "Erhaltet Fitzsimmons' Met aus dem Keller des Gasthauses im Hafen von Menethil.", progress = "Oh, ich bin so furchtbar durstig! Wollt Ihr diesem armen, mitleiderregenden Trottel nicht einen Drink spendieren?", completion = "Ah! Das ist genau das richtige und lockert die Zunge. Danke, Kumpel!", sourceObjectiveStatus = "unverified-source-field" }
quests[25816] = { id = 25816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Umherwandeln verdammt", description = "<Gestärkt fährt Fitzsimmons mit seiner Geschichte fort...>\n\nIch bin der einzige Überlebende der unglückseligen Dritten Flotte von Kul Tiras, die vor der Küste im Norden untergegangen ist. Auf einem unserer Schiffe war ein großer und furchtbarer Schatz versteckt und seine gespenstische Macht hält die Seelen meiner Brüder gefangen in den verrottenden Schiffsrümpfen.\n\nIch werde Tag und Nacht von ihnen verfolgt. Der Erste Maat Snellig ruft mich! Er sollte eigentlich tot sein! Bitte, {name} sucht ihn bei den Schiffswracks und... sagt ihm einfach, er soll mich in Ruhe lassen!", sourceObjective = "Sprecht mit dem Geist des Ersten Maats Snellig.", completion = "Fitzsimmons hat Euch geschickt, nicht wahr? Es ist so lange her...", sourceObjectiveStatus = "unverified-source-field" }
quests[25817] = { id = 25817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verfluchte Crew", description = "Die Seeleute der Dritten Flotte sind durch einen Fluch für immer dazu verdammt, an diesen Ufern voller Qualen entlangzuwandeln. Fitzsimmons Seelenqual hängt mit uns zusammen - solange wir leiden, kann auch er nicht ruhen.\n\nIhr müsst das Leiden der Geister meiner Mannschaftskameraden beenden. Löscht ihre Geister auf dieser Ebene aus und kehrt zu mir zurück.", sourceObjective = "Tötet 5 verfluchte Seemänner und 5 verfluchte Marinesoldaten in der Verlorenen Flotte.", completion = "Die gequälten Schreie sind erstickt worden... doch die Ursache des Fluchs noch nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25818] = { id = 25818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brechen des Fluchs", description = "Um den Fluch zu brechen, muss abgerechnet werden. Kapitän Halyndor hat uns alle dazu verdammt, ein verbotenes Artefakt zu begehren, das Auge von Paleth. Sein Geist will es noch immer und wacht über die Schließtruhe seines alten Schiffes, der 'Kühnheit'.\n\nVernichtet die Seele dessen, der uns einst so verfluchte, {class}. Besiegt den Kapitän, nehmt seinen Schlüssel und bringt das Auge von Paleth weit weg von diesem Ort.", sourceObjective = "Besorgt den Geldkassettenschlüssel der 'Kühnheit' von Kapitän Halyndor.", progress = "Diese Truhe ist sicher verschlossen.", completion = "Der Schlüssel ist verrostet, passt aber einwandfrei ins Schloss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25819] = { id = 25819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Paleth", description = "In der offenen Truhe erblickt Ihr eine geschwärzte Kugel, die in einem gruseligen Licht pulsiert. Dies muss das schändliche Auge von Paleth sein, das die Seelen dieser Seefahrer verdammt hat.\n\nSolch eine Verderbnis muss ausgemerzt werden. Vielleicht kann Euch ein Priester im Hafen von Menethil helfen.", sourceObjective = "Bringt das verfluchte Auge von Paleth zu Glorin Stahlbraue im Hafen von Menethil im Sumpfland.", progress = "Wie kann ich Euch helfen, Junge?", completion = "Das Auge von Paleth? Ihr sagt, Fitzsimmons hat Euch geschickt?\n\nBeim Lichte... nicht schon wieder. Fitzsimmons ist tot, Mädchen. Ihr seid auch nicht der erste, der so zu mir kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25820] = { id = 25820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sorgen einer Mutter", description = "Mein Sohn Gimlok ist das Licht meines Lebens. Mein Herz geht auf, wenn ich ihn mit den anderen Kindern spielen sehe.\n\nTrotzdem mache ich mir Sorgen. Nur wenige Meter entfernt, in der Bucht, gibt es Haie. Was, wenn das Wasser so tief ist, dass einer hierher schwimmt...\n\nDer Gedanke ist unerträglich! Ihr habt sicher schon Schlimmeres bewältigt als wir Stadtbewohner, {race}. Würdet Ihr diese schrecklichen Haie für mich beseitigen? Wenigstens ein paar?", sourceObjective = "Tötet 10 Hafenschredderflossen.", completion = "Wie wundervoll, dass Ihr so etwas für eine verheiratete Frau wie mich getan habt. Ihr seid zu freundlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[25821] = { id = 25821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ganz besonderer Auftrag", description = "Ihr habt hier unten Bemerkenswertes geleistet, {name}. Truppenkommandant Valen ist das nicht entgangen. Er möchte Euch sofort sprechen. Er hat Euch für eine besondere Mission ausgewählt - eine, mit der wir die Übergriffe der Horde im Steinkrallengebirge hoffentlich endgültig stoppen werden.", sourceObjective = "Meldet Euch bei Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.", completion = "Schon bei unserer ersten Begegnung wusste ich, dass Ihr eine besondere Schneeflocke seid, {name}. So besonders, dass ich niemandem außer Euch diese Aufgabe anvertrauen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[25822] = { id = 25822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegswerkzeug", description = "Ich muss Euch noch einmal einer Gefahr aussetzen, {name}. Im Osten gibt es eine von der Horde erbeutete Ausgrabungsstelle, die reich an Mineralien ist. Kisten mit unseren Waffen befinden sich dort. Sie sind überall verstreut. Die Horde ist erst vor kurzem dort eingefallen. Es ist unwahrscheinlich, dass sie bereits all unsere Ausrüstung gefunden haben.\n\nGeht dorthin und besorgt unseren Grimmtotemfreunden ein paar Waffen!", sourceObjective = "Sammelt 10 Waffenkisten der Allianz.", progress = "Habt Ihr das Kriegswerkzeug gefunden?", completion = "Das sollte reichen, um hundert Grimmtotem auszurüsten! Jetzt müssen wir die Waffen ihrem Häuptling übergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25823] = { id = 25823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die unerbittliche Horde", description = "Es ist zwar äußerst wichtig, dass Ihr die Waffenkisten unverzüglich sichert, aber wir müssen die Grabstätte im Osten auch von der Horde säubern. Wir müssen vollen Zugang zur Ausgrabungsstätte erhalten, sonst können wir keine Nachschublinie für die Grimmtotemverbündeten schaffen.\n\nTötet alle Angehörigen der Horde, denen Ihr an der Grabstätte begegnet, {name}. Für den Ruhm der Allianz!", sourceObjective = "Tötet 12 Angehörige der Horde an der Grabstätte.", completion = "Ich werde der Infanterie befehlen, nachzurücken und die Zurückgebliebenen zu beseitigen. Hätten wir doch zehntausend wie Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25824] = { id = 25824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragung", description = "Dieser Soldat stand an der Schwelle zum Tod, aber ich fürchte, wir können nicht warten, bis er wieder ganz genesen ist. Er hat Informationen, die wir dringend brauchen.\n\nSeid geduldig mit ihm, aber sorgt dafür, dass er weiterredet, bis er uns alles gesagt hat.\n\nMit ein bisschen Glück erfahren wir, womit wir es hier zu tun haben.", sourceObjective = "Sprecht mit Gefreiter Pollard und erfahrt etwas über seine Tortur.", completion = "Nun, es ist nicht gerade ermutigend, aber es ist immerhin etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[25825] = { id = 25825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohstofflieferung", description = "Also, {name}, ich will, dass Ihr das Öl zu Fizzel auf dem Turbodampfer bringt und ihm von den guten Neuigkeiten erzählt!", sourceObjective = "Bringt das Fass mit Öl zu Fizzel Kupferbolz auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", progress = "Was ist das? Ist das Öl?!", completion = "Es ist Öl! Ihr seid ja wirklich von unschätzbarem Wert, {name}!\n\nZu schade, dass ich Euch jetzt schon wieder weiterschicken muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25826] = { id = 25826, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohstofflieferung", description = "Also, {name}, ich will, dass Ihr das Öl zu Pozzik auf dem Turbodampfer bringt und ihm von den guten Neuigkeiten erzählt!", sourceObjective = "Bringt das Fass mit Öl zu Pozzik auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", progress = "Hallo noch mal. Ist das Öl?!", completion = "Es ist Öl! Ihr seid wirklich richtig gut, {name}!\n\nZu schade, dass ich Euch jetzt schon wieder weiterschicken muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[25830] = { id = 25830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte lebende Wissenshüter", description = "Ihr habt die Ahnen erweckt, {name}, aber Aessina, der Geist der Wildnis, schweigt noch immer. Mit ihrer Hilfe können wir diesen Kampf zu unseren Gunsten wenden und den Schaden, den der Schattenhammer angerichtet hat, rückgängig machen.\n\nEs mag jemanden geben, der uns dabei helfen kann. Der älteste der Bäume, Nordu, stand seit Tausenden von Jahren in der Mitte dessen, was heute die Flammenschneise ist. Seine Weisheit ist so alt wie dieser Berg. Wenn dieser alte Baum noch am Leben ist, kann er uns vielleicht dabei helfen, Aessina zu erwecken. Sucht nach ihm!", sourceObjective = "Findet Nordu, das Urtum der Lehren, in der Flammenschneise auf dem Hyjal.", completion = "Ich… bin noch nicht… entschwunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25832] = { id = 25832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Aviana", description = "{name}, Ihr habt hier alles getan, was Ihr tun könnt. Die ganze Höhle wird bald in sich zusammenbrechen!\n\nIch treibe die letzten schwingenbewehrten Hengste zusammen und stelle sicher, dass das Flammentor hinter mir versiegelt wird.\n\nIhr solltet losgehen und Aviana berichten, dass diese abscheuliche Brutstätte der Vergangenheit angehört!", sourceObjective = "Kehrt zu Aviana am Schrein von Aviana auf dem Hyjal zurück.", completion = "<Avianas Gesicht ist wie versteinert, als Ihr ihr erzählt, was in der Brutstätte passiert ist.>\n\nSie haben meine Eier gestohlen, {class}. Sie haben sie an diesen widerlichen Ort gebracht. Sie verderbt.\n\nMeine Kinder gestohlen, gequält, in einem Flammenmeer getötet... Ja, wir werden den Schattenhammer dafür bezahlen lassen.\n\nAber ich muss zugeben, dass ein Teil von mir sich einfach in die Lüfte erheben und diese ganze... Welt... in Flammen sehen möchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[25834] = { id = 25834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellvertreterkrieg", description = "Hört Ihr sie dort unten kämpfen, {name}? Anscheinend haben sich die Tauren der Grimmtotem mit der Horde überworfen. Ich weiß nicht, wie das geschehen ist, aber wir könnten es zu unserem Vorteil nutzen.\n\nIch werde ein Treffen mit dem Botschafter der Grimmtotem arrangieren. Ich möchte, dass Ihr eine Friedensgabe zusammenstellt.\n\n<Truppenkommandant Valen zeigt auf Kräcka.>\n\nRedet mit \"Kräcka\", {name}. Er weiß bereits, was zu tun ist.", sourceObjective = "Sprecht mit \"Kräcka\" Aschebäscha im Basislager der Nordwachtexpedition im Steinkrallengebirge.", completion = "Man nennt mich \"Kräcka\", Junge: den besten Koch von Azeroth. Der Kommandant hat mir schon gesagt, was los ist. Wir müssen ein erstklassiges Taurenmenü zusammenstellen, damit wir eine Audienz beim Häuptling der Grimmtotem bekommen.\n\nBesorgt mir die Zutaten, dann koche ich etwas, dem kein Tauren widerstehen kann. Noch nicht mal ein grimmiger Tauren, oder was immer die auch sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[25835] = { id = 25835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiwindposten befreien", description = "Es ist an der Zeit, dass Ihr geht. Wie schnell die Küken aus dem Nest fallen - oder so ähnlich.\n\nWie dem auch sei, Ihr habt hier gute Arbeit geleistet, aber Quentin und die Nachtelfen haben einen Hilferuf ausgestoßen und benötigen dringend Unterstützung mit den Grimmtotem in Freiwindposten nordwestlich von hier.\n\nWenn Ihr mich fragt, da ist alle Hoffnung verloren, aber wer weiß ... vielleicht können sie es mit Eurer Hilfe wirklich schaffen?", sourceObjective = "Sprecht mit Quentin in Freiwindposten in Tausend Nadeln.", completion = "Ich bin froh, dass Fizzel Euch endlich hergeschickt hat. Wir helfen den Tauren dabei, Freiwindposten zurückzuerobern und die Grimmtotem zu verdrängen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25836] = { id = 25836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiwindposten befreien", description = "Es sieht so aus, als sei es an der Zeit, dass sich unsere Wege trennen - zumindest vorübergehend. Nordwestlich von hier benötigen die Tauren in Freiwindposten dringend Hilfe, um den Grimmtotemklan zurückzudrängen.\n\nDa Ihr hier so großartig helfen konntet, gehe ich davon aus, dass Ihr auch dort äußerst schnell als <Held/Heldin> gefeiert sein werdet!", sourceObjective = "Sprecht mit Thalia Bernhaut in Freiwindposten in Tausend Nadeln.", completion = "Ich fühle mich geehrt, dass Ihr zu Hilfe gekommen seid, {class}. Es war sehr freundlich von Pozzik, Euch zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25837] = { id = 25837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das perfekte Dinner", description = "Für eine ordentliche Friedensgabe brauche ich folgende Zutaten:\n\nEier eines Kalimdoradlers. Ihr findet sie in den Nestern der Kalimdoradler. Sucht in dem Wald im Westen danach. Widderkeulen! Und zwar die Keulen des Steinkrallenwidders.\n\nDie letzte Zutat ist zwar schwer zu bekommen, aber wir brauchen sie für unser Widderlett. Reist nach Südwesten zur Steinschlagklamm und macht die Koboldhöhlen ausfindig. Tötet die Kobolde und stehlt ihren besonderen Käse.\n\nBringt alle Zutaten zu mir, dann werde ich ein Meisterwerk kochen!", sourceObjective = "Sammelt 6 Eier von Kalimdoradlern, 8 Widderkeulen und 10 Stücke Steinschlagkäse.", progress = "Das Widderlett macht sich nicht von allein!", completion = "Bleibt zurück, {name}, gleich gibt's 'ne Geschmacksexplosion und ich will nicht, dass Ihr verletzt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25838] = { id = 25838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe aus Stahlrosts Depot", description = "Dank Eurer Hilfe sind wir näher an die Zuflucht der Frostmähnen herangerückt. Unsere Streitkräfte werden bald in Position gehen und die Reserve der Frostmähnentrolle angreifen. Dann ist ihr Dorf ungeschützt.\n\nDas ist ein Fall für das Geheimteam Gnomeregan. Seine Techniker haben eine Möglichkeit gefunden, Kämpfer hinter die feindliche Linien zu bringen, ohne dass die Frostmähnen das bemerken. Begebt Euch zu Stahlrosts Depot nordöstlich der Stadt und sprecht mit Delber Kurbeldreh. Er wird Euch mehr darüber berichten.", sourceObjective = "Sprecht mit Delber Kurbeldreh in Stahlrosts Depot.", completion = "Ah, Ihr müsst der {class} sein, den Hauptmann Tharran schicken wollte. Ich habe einen Großteil des Geheimteams bereits mit einem Entfalt-O-Tron in Position nahe an die Zuflucht der Frostmähnen gebracht. Sie warten nur noch auf Euer Eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25839] = { id = 25839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ultrasichere Personalabschussgerät!", description = "Der Kataklysmus hat unsere Feinde näher gebracht, deshalb hat mich der Chef des Geheimdienstes von Gnomeregan gebeten, ein Gerät zu konstruieren, mit dem man Personal rasch und leise in jeden Teil Dun Moroghs transportieren kann.\n\nTataa, das ultrasichere Personalabschussgerät!\n\nMit nur einem Schuss Elektrizität und dank des SPE-Fallschirmsystems, äh, sehr späte Entfaltung für Laien, bringt Euch dieses Baby direkt zur Front. Steigt ein und bereitet Euch auf den Flug vor! Slamp Wackelrad erwartet Euch in der Landezone.", sourceObjective = "Fliegt mit dem ultrasicheren Personalabschussgerät zur Zuflucht der Frostmähnen.", completion = "Keine Sorge, das Gefühl, einen Stromschlag erhalten zu haben, vergeht nach ein paar Minuten. Es gibt wirklich schlimmere Fortbewegungsmittel. An dem Fallschirmsystem muss jedoch noch gearbeitet werden. Sehr späte Entfaltung ist ernst gemeint. Manchmal zu spät. Na ja, wir haben eine Mission zu erfüllen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25840] = { id = 25840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminiert den Widerstand", description = "Der Häuptling der Frostmähnen starb beim ersten Angriff der Troggs. Seitdem werden sie von einem sehr respektierten Krieger angeführt. Battok der Berserker war derjenige, der den Rückzug der Frostmähnen organisierte, das neue Dorf errichten ließ und die Angriffe gegen Kharanos und die Gebirgsjäger führte.\n\nWenn wir Battok beseitigen, sollte Chaos unter den Frostmähnen ausbrechen. Dann können sich die Gebirgsjäger um die Überlebenden kümmern. Battok hält sich östlich von hier im Dorf auf.", sourceObjective = "Tötet Battok den Berserker und 5 Krieger der Frostmähnen in der Zuflucht der Frostmähnen.", completion = "Sehr gute Arbeit, {name}. Ich gebe Hauptmann Tharran das Signal, dass Battok tot ist. Das sollte das Ende der Frostmähnenbedrohung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[25841] = { id = 25841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff von oben", description = "Delbers Techniker haben Tag und Nacht gearbeitet, um uns bei den Vorbereitungen auf den Angriff zu helfen. Seine Leute haben nicht nur das Personalabschussgerät konstruiert und eingestellt, sondern auch das geheime Fliegergeschwader für den Angriff auf die Zuflucht der Frostmähnen vorbereitet. Sie warten auf das Signal zum Beginn ihrer Angriffe.\n\nNehmt dieses Leuchtfeuer und zündet es nahe der Gebäudegruppe am Nordrand des Dorfs und neben den Gebäuden am Südrand des Dorfs. Die Flugmaschinen werden an beiden Stellen zuschlagen.", sourceObjective = "Benutzt das Signalleuchtfeuer, um Luftangriffe am nördlichen und südlichen Rand der Zuflucht der Frostmähnen anzufordern.", completion = "Ihr und die Luftstaffel habt Euch vorbildlich verhalten. Die Frostmähnen werden jetzt sicherlich nicht mehr hier bleiben. Wir müssen nur noch die Überlebenden beseitigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25842] = { id = 25842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuergefecht", description = "Es ist… zu spät für mich. Bis auf den Kern ist alles verbrannt. Ich habe Äonen erlebt… und doch scheint mein Ende so plötzlich zu kommen.\n\nAus altem kann neues Leben entstehen. Ich habe immer noch meine Weisheit, die ich weitergeben kann. Bitte… Lasst nicht zu, dass sie mich wegbringen, bevor meine Arbeit getan ist.\n\nHaltet meine Peiniger zurück... nur noch eine Weile, {class}.\n\nGebt mir ein paar Minuten und ich werde es mit tausenden Jahren vergelten.", sourceObjective = "Tötet 5 feurige Peiniger, um sie von Nordu fernzuhalten.", progress = "Seid Ihr da, {class}? Mein Augenlicht hat mich verlassen… Ich höre Kämpfe…", completion = "Danke, {race}.\n\nIch bin jetzt bereit.\n\nAlles, was ich bin, und alles, was dieser Wald je war… gehört jetzt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25843] = { id = 25843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollas Rache", description = "Der Berg erblüht wieder! Wenn wir schnell handeln, können wir unseren Vorteil ausnutzen.\n\nUnser alter Freund Tortolla, der Schildkrötenahn, ist bereits auf dem Weg. In seinem eigenen Tempo natürlich…\n\nFindet Tortolla östlich von hier, am Kopf des Pfades in die Verbrannte Ebene. Unsere Festungen dort sind schon ganz zu Anfang unseres Schlachtzugs gefallen, aber vielleicht können wir sie jetzt zurückfordern.", sourceObjective = "Sprecht mit Tortolla in der Verbrannten Ebene auf dem Hyjal.", completion = "{race}.\n\nIch erinnere mich an Euch. Retter meiner Kinder.\n\nDie Zeit ist gekommen. Für Rache.", sourceObjectiveStatus = "unverified-source-field" }
quests[25844] = { id = 25844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sättigt die wilde Bestie", description = "Ihr habt den Kommandanten gehört, {name}. Bringt mir das perfekte Geschenk für den Botschafter der Grimmtotem! Er wartet mit seinem Trupp am unteren Ende des südöstlichen Pfads.\n\nDas sollte unser Ansehen bei ihrem Häuptling steigern!", sourceObjective = "Bringt Ton Windbogen am Posten der Grimmtotem die fleischige Gabe.", progress = "<Ton Windbogen schnüffelt und hebt die linke Hand.>\n\nIhr habt etwas für uns dabei?", completion = "<Ton und seine Leibwächter verschlingen die fleischige Gabe.>\n\nEtwas... etwas so gutes habe ich noch nie gegessen. Vielleicht erweist Ihr Euch doch noch als wertvoller Verbündeter, aber bevor die Grimmtotem sich auf eine Zusammenarbeit mit der Allianz einlassen, müsst Ihr unseren Bedingungen zustimmen. Hier sind sie, so wie mein Anführer sie mir gesagt hat. Bringt sie Eurem Kommandanten. Mal sehen, ob er zustimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25845] = { id = 25845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forderungen", description = "Grimmtotem brauchen Waffen! Die Horde hat dank ihres Kriegshäuptlings und der Hilfe ihrer neuen Goblinverbündeten mächtige Waffen angehäuft. Unsere Kriegswerkzeuge haben dieser Feuerkraft nichts entgegenzusetzen. Stattet die Grimmtotem mit starken Waffen aus, dann werden wir gemeinsam die Horde vernichten!\n\nDies sind unsere Forderungen! Versorgt die Grimmtotem, dann kämpfen wir für die Allianz!", sourceObjective = "Bringt die Forderungen der Grimmtotem zu Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.", progress = "Und???", completion = "Waffen, hm?\n\n<Truppenkommandant Valen seufzt.>\n\nIch werde jetzt eine spontane Entscheidung fällen, {name}. Ich hoffe, es ist die richtige, sonst wird mich König Wrynn einen Kopf kürzer machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25846] = { id = 25846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundig Finsterwolke, Häuptling der Grimmtotem", description = "Der Häuptling der Grimmtotem erwartet Euch, {name}. Nehmt die Waffenkisten und brecht zum Posten der Grimmtotem südlich von hier auf.\n\nViel Glück, {name}. Sollte Euch etwas zustoßen, werde ich persönlich Eure Angehörigen informieren und König Wrynn wissen lassen, was Ihr für die Allianz getan habt.", sourceObjective = "Bringt die Waffenkisten der Allianz zu Grundig Finsterwolke am Posten der Grimmtotem im Steinkrallengebirge.", progress = "Habt Ihr die Waffen?", completion = "Das sind gute Waffen! Mächtiger Stahl! Mit solchen Waffen werden meine Krieger unbesiegbar sein. Magatha lächelt auf Euch herab, {name}.\n\nIch möchte Euch um einen, vielleicht auch zwei Gefallen bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25847] = { id = 25847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Überlegenheit der Grimmtotem", description = "Überall im Hochwipfeltal werden Grimmtotem von der Horde angegriffen. Höllschreis Armeen kennen weder Gnade noch Mitgefühl. Sie töten jeden, der ihnen im Weg steht.\n\nDas muss ein Ende haben! Nehmt das Kriegswerkzeug, das Ihr uns gebracht habt und sucht nach Grimmtotem, die gegen die Horde kämpfen. Gebt ihnen die Waffen der Allianz und seht zu, wie sie die Angreifer der Horde vernichten! Geht. Es gibt viel zu tun, <Verbündeter/Verbündete>.", sourceObjective = "Bewaffnet 12 Grimmtotem mit der Waffenkiste der Allianz.", completion = "Der Kampf ist noch längst nicht vorbei, {name}. Die Hordengeneräle leben noch...", sourceObjectiveStatus = "unverified-source-field" }
quests[25848] = { id = 25848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untergang", description = "Als wir erfuhren, dass Höllschrei einen weiteren Orc der Mag'har ausgesandt hatte, um die Hordentruppen im südlichen Steinkrallengebirge anzuführen, war es bereits zu spät. Camp Aparaje war niedergebrannt worden, alle Grimmtotem in dem Gebiet waren in den Flammen vergangen.\n\nVier der gefürchtetsten Hordengeneräle führen die Schlacht um das Hochwipfeltal an, unter ihnen auch der Mag'hargeneral Glubgok.\n\nReist nach Süden, zu den Ruinen von Camp Aparaje und tötet die Generäle. Wir halten die Horde JETZT auf! Kehrt zu mir mit ihrem Zeichen zurück!", sourceObjective = "Tötet die Hordengeneräle in Camp Aparaje und erbeutet das Insigne des Hordengenerals.", progress = "Sind die Generäle tot?", completion = "<Grundig zerquetscht das Insigne in seiner riesigen Faust.>\n\nIhr habt es geschafft, Verbündeter! Höllschrei wird Wochen brauchen, um sich von diesem Schlag zu erholen. Das südliche Steinkrallengebirge gehört den Grimmtotem... und der Allianz natürlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[25849] = { id = 25849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Archäologie", description = "Hört zu, <mein Freund/meine Liebe>, jeder gute Archäologe kennt die Risiken seines Berufs. Wenn man nicht wenigstens einmal in seiner Karriere einen uralten Dämon ausgräbt oder von einem boshaften Geist verflucht wird, dann sucht man nur nach Plunder!\n\nWahre Archäologen wissen, dass Kleinigkeiten wie versteinerte Knochen, die zu Skelettkriegern reanimiert werden, kein Grund sind, die Arbeit einzustellen.\n\nDiese versteinerten Knochen brauche ich. Erbeutet sie von den Fossilienmonstern, die in der Gegend umherstreunen und bringt sie mir. Ich werde Euch belohnen.", sourceObjective = "Erbeutet 20 versteinerte Knochen von lebenden Fossilien.", progress = "Ihr müsst Euch nicht zurückhalten! Bringt mir, soviel Ihr tragen könnt!", completion = "Seht Ihr? Nicht schlecht, oder? Ich wünschte fast, all meine Funde würden sich selbst ausgraben. Würde mir die Arbeit erleichtern!\n\nIhr habt sie natürlich auch erleichtert, {name}. Besten Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[25850] = { id = 25850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlagt die Erde!", description = "Falls es Euch entgangen sein sollte, das Land hier im Sumpfland ist ziemlich chaotisch. Überflutungen, Erdbeben... und jetzt wird auch noch der Boden wild.\n\nIch hätte nie geglaubt, dass wir einmal von unserer Grabungsstelle angegriffen werden würden, aber seit kurzem laufen Erdschollen Amok und versuchen, jeden Zwerg zu zerquetschen, den sie finden können.\n\nIhr seht jung und kräftig aus, {race}... würdet Ihr dort hinunter gehen und diesen Klumpen etwas Verstand einprügeln?", sourceObjective = "Tötet 7 paläolithische Elementare.", completion = "Ihr habt es ihnen gezeigt! Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25851] = { id = 25851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mit den Grimmtotem tanzt", description = "Kehrt zu Eurem Anführer zurück und berichtet ihm, was Ihr für die Grimmtotem getan habt. Sagt ihm, dass unsere Grenzen von nun an für die Allianz geöffnet sind.", sourceObjective = "Meldet Euch bei Truppenkommandant Valen im Basislager der Nordwachtexpedition im Steinkrallengebirge.", completion = "Hervorragende Arbeit, {name}! Nun müssen sich unsere Streitkräfte nur noch beim Betreten des Steinkrallengebirges Sorgen wegen der Horde machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25852] = { id = 25852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles frei", description = "Packt Eure Sachen, {name}, wir werden uns jetzt den restlichen Streitkräften der Nordwacht im Südlichen Brachland anschließen. Eure erste Mission im Südlichen Brachland sollte recht unkompliziert sein.\n\nVor zwei Tagen erreichte uns ein Notruf von Kommandant Walpole. Man hat ihn und sein Bataillon auf dem Steinkrallenpass außerhalb von Ehrenwacht eingekesselt. Die Horde ist überall! Geht dorthin und helft ihm. Ich werde das Nordwachenkommando von unserer Allianz mit den Grimmtotem in Kenntnis setzen.", sourceObjective = "Meldet Euch bei Kommandant Thomas Walpole auf dem Steinkrallenpass im Südlichen Brachland.", completion = "Die Grimmtotem sind also keine Bedrohung mehr? Das ist gut, aber uns tritt hier gerade die Horde in den Hintern!", sourceObjectiveStatus = "unverified-source-field" }
quests[25853] = { id = 25853, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Hut und Peitsche", description = "Ich bin für die Ausrüstung dieser Ausgrabungsstätte verantwortlich. Das läuft ganz gut, aber die schnelle Abreise hat uns nicht gut getan!\n\nArchäologen brauchen schließlich Werkzeuge. Man kann unbezahlbare Antiquitäten nicht mit den Händen ausgraben. Wenn Ihr zur Ausgrabungsstätte reist, könntet Ihr uns das Werkzeug, das zurückgelassen wurde, mitbringen?", sourceObjective = "Beschafft 6 Archäologenwerkzeuge.", progress = "Sind sie vollständig? Wir haben einiges zurückgelassen.", completion = "Das erleichtert mich! Vielleicht können wir uns jetzt aus dem Mist graben, in dem wir bis zum Hals stecken.\n\nVergesst es, nur ein schlechter Scherz.", sourceObjectiveStatus = "unverified-source-field" }
quests[25854] = { id = 25854, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich nenne ihn Bisschen", description = "Wusstet Ihr, dass manche Raptoren so intelligent sind, dass man sie zähmen kann? Das stimmt! Ich habe Jäger gesehen, die das getan haben.\n\nEs ist hier draußen ziemlich einsam, auch wenn Wenna mir Gesellschaft leistet... ein Haustier würde vielleicht meine Stimmung heben. Ein kleines Raptorbaby wäre toll!\n\nWenn Ihr ohnehin gerade dort draußen die Erwachsenen abschlachtet, könntet Ihr mir einige ausgebrütete Eier mitbringen? Die Eier wackeln, wenn die Babys schlüpfbereit sind.", sourceObjective = "Beschafft sechs wackelnde Raptoreneier.", progress = "Habt Ihr genug Eier? Das Risiko bei nur einem Ei ist zu hoch. Das ist statistisch erwiesen.", completion = "Wunderbar! Sie sollten noch heute schlüpfen...\n\nIch baue besser schon mal ein Gehege, bevor sie alle gleichzeitig schlüpfen. Eigentlich kann nichts schiefgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25855] = { id = 25855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dingsdabumse", description = "In letzter Zeit fehlen mir ständig Teile für meine Ingenieurskunstprojekte, und nun habe ich den Grund dafür entdeckt. Die Moosfellgnolle stehlen sie!\n\nIch weiß nicht, was sie damit wollen, aber ich muss diese Dingsdas wiederhaben. Wahrscheinlich liegen sie überall in den Sümpfen herum. Würdet Ihr sie mir mitbringen, wenn Ihr welche seht?", sourceObjective = "Findet 7 Dingsdas der Schnellschalts.", progress = "Habt Ihr sie gefunden?", completion = "Das ist wundervoll! Ich fange direkt mit dem Zusammenbau an. Habt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[25856] = { id = 25856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokiliskenbälge", description = "Seit Jahren häute ich Krokis im Sumpfland, {class}. Es hat sich jedoch viel verändert.\n\nIch will nicht auf die Tränendrüse drücken, aber als der Kataklysmus den Hafen von Menethil überflutete, riss er auch unser Haus mit sich. Meine Frau und meine Kinder wissen nicht, wo sie bleiben sollen und ich muss soviel Geld wie möglich verdienen, damit wir bald wieder ein Dach über dem Kopf haben.\n\nIch habe Krokis gehäutet, bis ich vor Müdigkeit umgefallen bin, aber ich brauche noch mehr Häute für den Verkauf. Bringt mir ein paar Krokibälge. Ich zahle Euch auch ein wenig dafür.", sourceObjective = "Erbeutet 10 Marschenkrokiliskenbälge von Sumpflandkrokilisken.", progress = "Habt Ihr Krokbälge für mich?", completion = "Ich bin Euch dankbar, {class}. Die werden meiner Familie helfen, wieder auf die Beine zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25857] = { id = 25857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagt Horrorkiefer", description = "Es juckt mir in den Fingern, eine große Beute zu jagen... Horrorkiefer, den größten Krokilisken dort draußen. Mit seinem Balg könnte ich meine Familie aus diesem Loch holen.\n\nAber ich bin kein Narr. Ein Fehler reicht, um ein Bein oder gar mein Leben zu verlieren. Was würden meine Frau und Kinder dann tun? Sie wären immer noch obdachlos und die Kinder hätten keinen Vater mehr, der sich um sie kümmert.\n\nIch bin nicht stolz darauf, aber für die Sicherheit meiner Familie schlucke ich meinen Stolz hinunter. Bitte, {class}... jagt Horrorkiefer für mich. Er lauert im Norden, in seinem schattigen Tümpel.", sourceObjective = "Tötet Horrorkiefer und erbeutet Horrorkiefers Haut.", progress = "Habt Ihr sie? Habt Ihr Horrorkiefers Haut?", completion = "Unglaublich! Ihr seid ein wahrer Held, {name}. Ich werde nie vergessen, was Ihr für mich und meine Familie getan habt.\n\nIch weiß, dass es nicht viel ist, aber nehmt es mit meinem Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25858] = { id = 25858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Namen der Lady", description = "Lady Sira'kess hat mit den Vorbereitungen für das Beschwörungsritual begonnen, aber der Schmelztiegel von Nazsharin wurde uns gestohlen. Sicher haben die Kvaldir ihn mit sich genommen, als sie sich in flachere Gewässer zurückgezogen haben.\n\nSprecht mit den Anführern der Kasten, um einen Kriegstrupp zusammenzustellen. Führt sie dann zum Biel'arangrat im Osten, um das Artefakt wiederzuholen.\n\nIch vertraue Euch, meine Kriegsmaid, denn Ihr habt mich noch nie enttäuscht, ganz gleich, welche Aufgabe ich Euch gab. So sehr die Königin mich schätzt, so sehr schätze ich Euch. Geht mit meinem Segen.", sourceObjective = "Sprecht mit Tiefenlord Zin'jatar, Lady Sira'kess und Aufseher Idra'kess.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Verstärkung zieht sich in den Gewässern um das Riff zusammen und macht sich für einen Angriff bereit. Sie warten nur noch auf Euren Befehl.", sourceObjectiveStatus = "unverified-source-field" }
quests[25859] = { id = 25859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Vergebung", description = "Ich weiß, dass Ihr genau wie unsere ehrwürdige Lady gelegentlich leider Anflügen von Mitleid unterliegt. Am heutigen Tage möchte ich Euch jedoch raten, diese Freundlichkeiten zu unterlassen. Die Kvaldir sind stolz. Wenn wir sie nicht komplett vernichten, werden sie ganz sicher Rache nehmen. Tötet alle, die Ihr finden könnt.\n\nLeider habe ich die ruhmlose Aufgabe sicherzustellen, dass keiner in die Stadt zurückkehrt, sodass ich Euch den ganzen Spaß überlassen muss. Ich werde Euch aber natürlich anfeuern.", sourceObjective = "Tötet 20 Kvaldir auf der Vrykulklippe.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Keiner ist zur Brücke entwischt. Nicht einer.\n\nWie langweilig. Nächstes Mal wäre ich Euch dankbar, wenn Ihr ein bisschen mit mir teilen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25860] = { id = 25860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koste es, was es wolle", description = "Wir beginnen sofort mit dem Ritual. Ihr werdet Euch darum kümmern, dass niemand uns unterbricht.\n\nErschlagt alle Kvaldir, die den Tempel betreten. Achtet darauf, dass meine Priesterinnen überleben, um ihre Aufgabe zu Ende zu bringen. Koste es, was es wolle.", sourceObjective = "Tötet 20 Angreifer der Kvaldir im Tempel von Quel'Dormir.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Ich vertraue darauf, dass Ihr uns beschützt, Kriegsmaid.", completion = "Wenn Azjentus etwas verspricht, dann hält er es auch. Lady Naz'jars Ehrenwache sollte ausreichen, um den Rest des Rituals zu überwachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25861] = { id = 25861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Exempel statuieren", description = "Die Hochschamanen befinden sich in den Gebäuden in der Nähe und singen und spotten, trauen sich aber nicht, näher zu kommen. Diese Kvaldir sind nur mutig, wenn sie sich im Nebel verstecken können. Ein erbärmliches Ärgernis unter den Wellen.\n\nIch bringe eine Nachricht. Wenn Ihr die Zeit fändet, gnädige Frau, dann bringt mir einen Hochschamanen und werft ihn mir zu Füßen, auf dass ich ihm und seinem Volk meine Nachricht überbringen kann.", sourceObjective = "Bringt einen Hochschamanen der Kvaldir zu Henker Verathress' Füßen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Wenn Ihr die Zeit fändet, gnädige Frau, dann bringt mir einen Hochschamanen und werft ihn mir zu Füßen, auf dass ich ihm und seinem Volk meine Nachricht überbringen kann.", completion = "Meine Sense ist gesättigt. Vielen Dank, gnädige Frau.", sourceObjectiveStatus = "unverified-source-field" }
quests[25862] = { id = 25862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlenes Eigentum", description = "Unsere ehrwürdige Lady hat mich geschickt, um Euch bei Eurer Aufgabe zu helfen. Sie möchte, dass Ihr den gestohlenen Schmelztiegel von Nazsharin wiederbeschafft und so schnell wie möglich hierher bringt.\n\nSie kann es kaum erwarten, das Beschwörungsritual durchzuführen, damit wir endlich voll und ganz mit unseren Kriegsvorbereitungen beginnen können.", sourceObjective = "Besorgt den Schmelztiegel von Nazsharin.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "<Der Schmelztiegel sieht viel zu schwer aus, als dass Ihr ihn alleine tragen könntet, aber es sind mehr als genug Streitmächte der Naga übrig, um ihn für den Transport vorzubereiten.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25863] = { id = 25863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiwillige Last", description = "Jetzt, da Ihr den Schmelztiegel von Nazsharin an Euch gebracht habt, müsst Ihr nur noch Lady Naz'jar von Eurem Erfolg berichten.", sourceObjective = "Kehrt mit Euren Nachrichten vom Schmelztiegel von Nazsharin zum westlichen Ende des Biel'arangrats zurück.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", completion = "Gut gemacht, meine Kriegsmaid.\n\nDieser Schmelztiegel wird uns als Quell der Macht für unser Beschwörungsritual dienen. Damit wird Sira'kess unsere Verbündeten aus den Tiefen rufen, um unsere ohnehin schon starke Armee zu unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25864] = { id = 25864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dinosaurierkrise", description = "Ständig erreichen uns Berichte über Raptorangriffe in der Gegend. Ich muss hier für Sicherheit sorgen, damit mehr Siedler kommen. Aus diesem Grund habe ich ein Kopfgeld auf diese Viecher ausgesetzt.\n\nViele wurden bereits beseitigt, aber die Hochlandraptoren im Norden vermehren sich stark. Aber das wird sich bald ändern, nicht wahr?\n\nErledigt ein paar Hochlandraptoren, dann gebe ich Euch eine hübsche Belohnung.", sourceObjective = "Tötet 8 beliebige Hochlandraptoren.", completion = "Gute Arbeit. Betrachtet das nicht als Belohnung von mir, sondern von Eisenschmiede. Der Erhalt von Khaz Modan geht jeden Zwerg etwas an.", sourceObjectiveStatus = "unverified-source-field" }
quests[25865] = { id = 25865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Moosfellmission", description = "Ihr wirkt vertrauenswürdig. Würdet Ihr mir bei meinem wahren Problem helfen, {name}? Eisenschmiede hat mich hierher geschickt, um eine Lieferung Goldbarren wiederzubeschaffen.\n\nDie Barren gehören zum Thronschatz von Eisenschmiede und tragen das königliche Siegel. Nur ein Narr würde sie aus Profitgier stehlen. Sie sind viel zu leicht nachzuverfolgen. Wie es der Zufall will, gibt es jede Menge Narren hier: Moosfellgnolle.\n\nIch weiß nicht, wie oft Ihr schon gegen Gnolle gekämpft habt, aber das sind üble und brutale Bestien. Sie sind gefährlich. Tötet sie und bergt die verschwundenen Barren.", sourceObjective = "Beschafft 8 Barren von Eisenschmiede von den Gnollen der Moosfelle.", progress = "Es wurden schätzungsweise acht Barren gestohlen.", completion = "Gut gemacht! Die Wache von Eisenschmiede dankt Euch, {name}. Ihr habt unserer Stadt einen großen Gefallen erwiesen.\n\nDoch es gibt neue Probleme...", sourceObjectiveStatus = "unverified-source-field" }
quests[25866] = { id = 25866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fallensteller der Dunkeleisenzwerge", description = "Der Klan der Dunkeleisenzwerge ist in diesem Gebiet gesehen worden. Vielleicht sind sie Euch schon über den Weg gelaufen. Sie führen nie Gutes im Schilde, und dieses Mal scheinen sie aus irgendeinem Grund Moosfellgnolle zu entführen.\n\nIch weiß nicht, was das soll, aber wir müssen sie aufhalten, bevor noch üblere Dinge geschehen. Haltet sie auf.\n\nWenn Ihr Euch Sorgen macht, weil das unfair ist, könnt Ihr sie ja zuerst höflich fragen. Mal sehen, wie weit Ihr damit kommt.", sourceObjective = "Tötet 10 Fallensteller der Dunkeleisenzwerge.", completion = "Ich nehme an, sie sind nicht freiwillig mitgekommen? Dachte ich mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[25867] = { id = 25867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Flucht der Gnolle", description = "Ich weiß, dass wir selbst gerade die Gnolle angegriffen haben, aber ich werde nicht zulassen, dass die Dunkeleisenzwerge sie als Sklaven halten. Zum einen haben wir die Diebe gefunden und unseren Besitz zurückerhalten, also wurde der Gerechtigkeit Genüge getan. Zum anderen werden die Dunkeleisenzwerge sie bestimmt nicht für gemeinnützige Arbeiten einsetzen... \n\nAlso müssen die Gnolle befreit werden. Die Fallensteller sollten die Schlüssel, mit denen man die Käfige öffnen kann, bei sich tragen.", sourceObjective = "Erbeutet den Schlüssel des Fallenstellers von Fallenstellern der Dunkeleisenzwerge und befreit damit 6 Gnolle aus den Gnollkäfigen.", completion = "Das sollte reichen! Je mehr Gnolle diese Narren jagen müssen, desto leichter wird es, sie in Schach zu halten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25868] = { id = 25868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yorla Dunkelschlinge", description = "Ich habe herausgefunden, wer bei dieser Operation im Hintergrund die Fäden zieht. Yorla Dunkelschlinge führt die Dunkeleisenzwerge von einem Lager im Osten an. Wahrscheinlich hat sie den Gnollen befohlen, das Gold aus Eisenschmiede zu stehlen.\n\nAußerdem ist sie eine gesuchte Kriminelle... Schon als Magni noch lebte, schürte sie Rebellionen und Angriffe gegen Eisenschmiede.\n\nDieses Mal wird sie uns nicht durch die Lappen gehen, {name}. Schnappt sie Euch!", sourceObjective = "Tötet Yorla Dunkelschlinge.", completion = "Gute Arbeit! Ihr habt eine der größten Verbrecherinnen Eisenschmiedes der Gerechtigkeit zugeführt, {name}. Ihr habt Euch eine ziemlich große Belohnung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[25869] = { id = 25869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmtotem in Freiwindposten", description = "Die Reise, die vor uns liegt, beginnt damit, dass Ihr alle Eindringlinge der Grimmtotem in Freiwindposten tötet. Wenn Ihr sie hier nicht aufhalten könnt, werden wir nicht in der Lage sein, bis zu ihrem Territorium vorzudringen.", sourceObjective = "Tötet 10 Eindringlinge der Grimmtotem.", completion = "Bei dieser Aufgabe kann man wirklich nur grimmig dreinschauen.<Quentin hustet.>\n\nNein, das war nicht witzig gemeint.", sourceObjectiveStatus = "unverified-source-field" }
quests[25870] = { id = 25870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmtotem in Freiwindposten", description = "Ihr müsst die Eindringlinge der Grimmtotem in Freiwindposten loswerden. Das haben sie sich aber selbst zuzuschreiben, diese Feiglinge!\n\nWir können nicht zulassen, dass die Schlacht in ihre eigenen Gebiete verlagert wird, und wir sprichwörtlich mit dem Rücken zu ihnen stehen. Bitte helft uns, unsere Heimat zurückzuerlangen, {class}.", sourceObjective = "Tötet 10 Eindringlinge der Grimmtotem.", completion = "Das ist schon mal ein guter Anfang! Normalerweise würde ich keiner Kreatur der Erdenmutter irgendein Leid wünschen.\n\nAber da sie uns zu einem Zeitpunkt extremer Verletzlichkeit angegriffen haben, verdienen sie den Tod!", sourceObjectiveStatus = "unverified-source-field" }
quests[25871] = { id = 25871, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Schildwache", description = "<Brienna wedelt mit einer Notiz, die Markierungen in Taurahe aufweist.>\n\nDiese Monster haben eine unserer Schildwachen gefangen! Sie drohen damit, sie zu töten, wenn wir uns nicht zurückziehen!\n\nWir verhandeln nicht mit feigen Bestien! Bitte {class}, könnt Ihr versuchen, die Schildwache zu retten, bevor es zu spät ist?", sourceObjective = "Rettet die Schildwache von Feralas.", completion = "Danke, dass Ihr die sie befreit habt, {name}. Die Monster der Grimmtotem hätten sie sicherlich kaltblütig getötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25872] = { id = 25872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kriegerheld und die Wagemütigen", description = "<Rau wedelt verärgert mit einer Notiz, die Markierungen in Taurahe aufweist.>\n\nDiese Monster haben einen unserer Kriegerhelden gefangen! Sie drohen damit, ihn zu töten, wenn wir uns nicht zurückziehen!\n\nWir werden diesen feigen Grimmtotem nie gestatten, Freiwindposten zu behalten! Bitte {class}, rettet ihn, bevor es zu spät ist.", sourceObjective = "Retten den Kriegerheld des Freiwindpostens.", completion = "Vielen Dank {name}, dass Ihr den Kriegerhelden befreit habt. Diese Grimmtotem hätten ihn kaltblütig getötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25873] = { id = 25873, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn des Verräters", description = "Hier liegt der gebrochene Leichnam von Montarr, dem Bewahrer der Lehren des Freiwindpostens. Der Körper des alten Tauren ist gebrochen und in einer Pfütze seines eigenen Blutes.\n\nBlutspuren führen zurück zum Gasthaus...", sourceObjective = "Erhaltet Langhorns Horn.", progress = "Was ist das, {class}?", completion = "Ein Verräter unter den Tauren?\n\nVon so etwas habe ich noch nie etwas gehört. Rivalitäten und Kriege zwischen den Klans sind eine Sache, aber das kaltblütige Töten eines Verbündeten ist etwas anderes.\n\n<Quentin schüttelt ungläubig seinen Kopf.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25874] = { id = 25874, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn des Verräters", description = "Hier liegt der gebrochene Leichnam von Montarr, dem Bewahrer der Lehren des Freiwindpostens. Der Körper des alten Tauren ist gebrochen und in einer Pfütze seines eigenen Blutes.\n\nBlutspuren führen zurück zum Gasthaus...", sourceObjective = "Erhaltet Langhorns Horn.", progress = "{name}? Habt Ihr Neuigkeiten?", completion = "Der Klippenbehüter war ein Spion der Grimmtotem?! Kein Wunder, dass wir nicht gewarnt wurden!\n\n<Thalia schäumt beinahe über vor Wut.>\n\nDieses verdammte Horn will ich nicht. Lasst es in den Tiefen des Wassers untergehen, und sorgt dafür, dass der Name Langhorn nie wieder erwähnt wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[25875] = { id = 25875, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der eingeschleuste Gnom", description = "Am Mirkfallonsee wimmelt es von der Horde. Die Goblins haben sich dort eingenistet, und sie werden erst wieder abziehen, wenn sie das gesamte Öl unter dem Steinkrallengebirge ausgesaugt haben.\n\nZum Glück konnte ich einen Gnom einschleusen, der Informationen für uns sammelt. Wenn irgendjemand weiß, was es mit dieser Bombe auf sich hat, dann mein eingeschleuster Gnom.\n\nGeht zu den Schlickwerken im Norden und findet Minx. Sie hat sich als \"Goblin\" Pumpenkontrolleur getarnt.", sourceObjective = "Sucht in den Schlickwerken im Steinkrallengebirge nach Minx. Sie hat sich als \"Goblin\" Pumpenkontrolleur getarnt.", completion = "Kommt rein und bleibt an der Wand! Meine Tarnung darf nicht auffliegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25876] = { id = 25876, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie ist da oben!", description = "Ich folge dieser Bombe, seit Ihr mich in Eschental gerettet habt. Was auch immer sie damit vorhaben, wird bald geschehen.\n\nGanz oben auf der großen Ölplattform gibt es einen Kontrollraum. Im Kontrollraum werdet Ihr das Logbuch von Krom'gar finden. Dieses Logbuch ist der Schlüssel zum Ziel der Bombe. Geht nach oben und holt das Logbuch! Bringt es hierher. Ich werde es für Euch dechiffrieren.", sourceObjective = "Stehlt das Logbuch von Krom'gar.", progress = "Habt Ihr das Logbuch bekommen?", completion = "OH NEIN! Sie wollen die Bombe im Hain von Thal'darah \"testen\"! Das ist eine Schule für junge Druiden mitten im Kriegsnarbental. Ihr müsst zu Barus zurückkehren und ihn davon unterrichten! Meister Thal'darah muss gewarnt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[25877] = { id = 25877, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Zeit für Verabschiedungen!", description = "LAUFT! Verschwindet hier, {name}. Sucht Barus auf und sagt ihm, was Ihr herausgefunden habt. Er wird dafür sorgen, dass Ihr sicher durch das Kriegsnarbental zur Aussicht von Thal'darah gelangt.\n\nFür diese jungen Druiden ist es noch nicht zu spät!", sourceObjective = "Kehrt zu Späherkommandant Barus am Mirkfallonposten im Steinkrallengebirge zurück", completion = "Verdammte Horde! Ich habe Freunde in diesem Hain. Ich hoffe, Ihr könnt auf einem Hippogryph reiten. Ihr müsst sofort zu Meister Thal'darah an der Aussicht aufbrechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25878] = { id = 25878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anleitung zur Sabotage", description = "Goblins... Was wäre die Welt ohne Goblins? Das kann ich Euch sagen: SAUBER!\n\nDiese schmutzigen kleinen Unholde haben überall auf dem See Ölpumpen errichtet, mit denen sie das Öl im Streinkrallengebirge bis auf den letzten Tropfen abzapfen wollen. An jeder Ölpumpe steht ein Ölpumpenkontrolleur, der darauf achtet, dass die Pumpe läuft und nichts schief geht.\n\nAber etwas wird schiefgehen.\n\nBeseitigt die Goblinpumpenkontrolleure und nehmt ihre Pumpensteuerung. Überlastet damit die Pumpen!", sourceObjective = "Zerstört 4 Goblinölpumpen mit der Goblinpumpensteuerung.", completion = "Ich konnte die Explosionen von hier sehen, {name}! Dank Euch wird die Horde keinen Treibstoff mehr vom Mirkfallonsee bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25879] = { id = 25879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger mit den Trampeln", description = "Schon mal einen Hobgoblin gesehen? Das ist wieder so eine eklige Schöpfung der Goblins. Nehmt einen Goblin, macht ihn noch hässlicher, fetter, größer und dümmer, und heraus kommt ein Hobgoblin. Fügt dem noch einen miesen Charakter hinzu, dann versteht Ihr das Problem.\n\nDiese Trampel lungern an den Schlickwerken und am Mirkfallonsee herum. Die Goblins setzen sie als Wächter ein.\n\nGeht dorthin und dünnt sie etwas aus. Unwiderruflich.", sourceObjective = "Tötet 10 Trampel.", completion = "Langsam, aber sicher führen wir der Horde Verluste zu. Sie werden kein Bein auf den Boden kriegen, wenn es in diesem Krieg richtig zur Sache geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[25880] = { id = 25880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warnt Meister Thal'darah", description = "Im Hain von Thal'darah leben Dutzende Schüler. Die meisten können sich nicht wehren. Man wird sie abschlachten.\n\nInformiert Meister Thal'darah über die Pläne der Horde. Er wird Euch erklären, was als nächstes zu tun ist.\n\nFiora Mondsegler hat Euch ihren schnellsten Hippogryph gegeben. Fliegt damit zur Aussicht von Thal'darah! Seht nicht zurück, {name}! Die Horde muss aufgehalten werden!", sourceObjective = "Meldet Euch bei Meister Thal'darah an der Aussicht von Thal'darah im Steinkrallengebirge.", completion = "Wir leben in wirklich schlimmen Zeiten, {name}. Unser Außenposten auf dem Steinkrallengipfel wurde von grausamen Kreaturen aus der Tiefe überrannt, und die Horde will uns vernichten. Wir brauchen einen Helden, {name}; einen Soldaten der Allianz, der uns sicher durch diese schweren Zeiten führt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25881] = { id = 25881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschollene Wächter", description = "Wir haben so lange durchgehalten wie es ging, {class}. Aber die Flammen… die Hitze… Wir haben die Stadt ganz verloren.\n\nHauptmann Eisenstamm hat sich geweigert, zum Rückzug zu blasen, als die Flammen uns eingeschlossen haben. Unsere Truppen sind überall verstreut. Vielleicht haben ein paar der anderen überlebt? Wir könnten einen Gegenangriff starten!\n\nReist in die Verbrannte Ebene und rettet alle verschollenen Wächter, die von ihrer Gruppe getrennt wurden. Dann sucht nach Hauptmann Eisenstamm. Er befindet sich wahrscheinlich mitten im Kampfgetümmel.", sourceObjective = "Findet und rettet 8 verschollene Wächter.", completion = "Ihr habt die Überlebenden versammelt? Gut, gut. Und der Rest des Berges… ist geheilt?\n\nHa, da brat mir einer einen Storch! Wir sind wieder an der Front!", sourceObjectiveStatus = "unverified-source-field" }
quests[25882] = { id = 25882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für das Gehöft", description = "Hauptmann Tharran hat mich gebeten, Euch seinen Dank für Eure Hilfe und seine Glückwünsche zur erfolgreichen Mission auszurichten. Er kümmert sich mit seinen Männern um die letzten Trolle und versorgt die Verwundeten.\n\nEr hat mich auch gebeten, Euch zu fragen, ob Ihr Berichten über Trollüberfälle auf dem Gehöft Bernruh im Norden nachgehen könntet. Fragt nach Unteroffizier Flinthammer, wenn Ihr dort eintrefft.", sourceObjective = "Sprecht mit Unteroffizier Flinthammer auf dem Gehöft Bernruh.", completion = "Ihr habt also Hauptmann Tharran dabei geholfen, die Frostmähnentrolle zurückzuschlagen? Ich habe Euren Namen in den Berichten gesehen. Freut mich, Euch endlich kennenzulernen. So einen {class} wie Euch können wir zur Sicherung des Gehöfts gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25883] = { id = 25883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entwaffnend", description = "Nagawaffen…\n\nAls Ihr Euren Blick über die Pferche streifen lasst, seht Ihr Dutzende ähnlicher Dreizackstapel, die strategisch positioniert zu sein scheinen.\n\nIhre Waffen zu zerstören behindert sicher die bösen Pläne, die sie in dieser Gegend verfolgen...", sourceObjective = "Zerstört 6 Dreizackstapel der Naga.", progress = "Habt Ihr das Waffenlager der Naga zerstört?", completion = "Ihr seid Euch sicher, dass Eure Zerstörung der Waffen die Naga sicher stark einschränken wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[25884] = { id = 25884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Biegen und Brechen", description = "Himmeldonnerwetter nochmal...\n\nIch weiß, dass unser Schiffbrüchiger hier es gut meint, aber der Junge ist doch schwerst traumatisiert.\n\nEs gibt nur eine Methode, wie man mit diesen verflixten Biestern fertig wird, und zwar indem man ihnen eine anständige Zwergenaxt bis zum Anschlag in den Schädel rammt.\n\nJe mehr Leichen ihrer Kameraden man vor ihnen aufstapelt, desto genauer werden sie es sich überleg'n, einem ans Leder zu geh'n.\n\nDas könnt Ihr mir glaub'n, <Kumpel/Mädel>, die Burschen mög'n den Anblick ihres eigenen Blutes genausowenig wie Ihr oder ich.\n\nUnd jetzt ab mit Euch und zeigt denen, was 'ne Harke ist!", sourceObjective = "Tötet 12 Naga des Zin'jatar in der Umklammerung im Tang'tharwald.", completion = "Die Gewässer in der Umgebung der Pferche färben sich rot vom Blut der Naga.\n\nRendel wäre stolz!", sourceObjectiveStatus = "unverified-source-field" }
quests[25885] = { id = 25885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Macht den Algen", description = "Wa… was IST das?!\n\nIch habe so starke Schmerzen… tief in meinem Bauch.\n\nIch glaube… uff… Sie müssen mich vergiftet haben!\n\nSie haben uns merkwürdig leuchtende Algen zu essen gegeben, die sie um ihre Festung herum anbauen…\n\nIch glaube, diese Krämpfe werden immer schlimmer, wenn ich nicht bald mehr davon bekomme...\n\nBitte, {race}. Bringt mir etwas davon!", sourceObjective = "Sammelt 7 Schlängelgrassprösslinge von Erntern der Schimmerrücken in der Umklammerung.", progress = "Konntet Ihr welche von diesen Algen für mich finden, {class}?", completion = "Ja, ja. Genau das sind sie.\n\nVielleicht kann ich mich davon entwöhnen und die Nebenwirkungen so umgehen.\n\nDanke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25886] = { id = 25886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Vorteil nutzen", description = "Wie es scheint, hat ein Großteil des Schattenhammers sich zurückfallen lassen, um sich für einen weiteren Angriff neu zu formieren. Nur ihre besten Kämpfer halten noch die Front. Dies ist unsere Gelegenheit, um ihren Anführern den Garaus zu machen.\n\nSchwärmt aus über die Verbrannte Ebene und vernichtet die Zwielichtfeldhauptmänner. Wir werden sie von dieser Welt tilgen!", sourceObjective = "Tötet 4 Zwielichtfeldhauptmänner.", completion = "Ausgezeichnet! Der Schattenhammer wird zweifellos versuchen, den Berg zurückzuerobern, aber dafür müssen sie jetzt auf die Führerschaft dieser hirnlosen Muskelpakete verzichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25887] = { id = 25887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welle der Zerstörung", description = "Unsere Zeit hier neigt sich dem Ende zu. Ich muss diesen Nagaflüchtlingen irgendwie folgen, wenn wir herausfinden wollen, was sie in dieser Gegend vorhaben.\n\nAber bevor ich weiterziehe will ich sehen, wie dieser Ort hier vernichtet wird!\n\nEgal, wie viele es sind, ich habe einen Plan, der für Chancengleichheit sorgen wird.\n\nAußerhalb der Höhle suchen ausgemergelte große Haie, die von den Naga vertrieben wurden, nach Nahrung.\n\nIn ihrem geschwächten Zustand sind sie für Anregungen sehr empfänglich. Benutzt diese Kugel, um sie zu unterwerfen und hetzt sie dann direkt auf unseren Feind.", sourceObjective = "Benutzt die Kugel der Anregung, um einen ausgemergelten großen Hai zu unterwerfen und benutzt ihn dann, um 12 Gefolgsleute des Zin'jatar in der Umklammerung zu töten.", completion = "Genau so soll es sein.\n\nJetzt ist der Weg frei, um diesen Naga einen letzten vernichtenden Schlag zu versetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25888] = { id = 25888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druckabbau", description = "Ich kann den Gedanken einfach nicht ertragen, dass so viele andere wie dieser Soldat inmitten von Naga eingesperrt sind.\n\nWir müssen etwas unternehmen, um sie zu retten!\n\nNehmt dies, {name}. Wendet es an den Gefängniszellen an, um ihnen Auftrieb zu verleihen.\n\nWenn wir sie an die Oberfläche bringen können, haben sie wenigstens eine Hoffnung auf Rettung.", sourceObjective = "Benutzt Moanahs Atemstein an 10 eingekerkerten Soldaten in der Umklammerung.", progress = "Konntet Ihr einige der eingekerkerten Soldaten retten, {name}?", completion = "Hoffen wir einfach, dass die freigelassenen Gefangenen jetzt in Sicherheit sind.\n\nBitte nehmt dies als Gegenleistung für Eure edle Tat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25889] = { id = 25889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Kinder!", description = "Meine armen, hilflosen Schüler sitzen im Hain von Thal'darah fest. Wegen der Schlacht, die im Kriegsnarbental tobt, können sie nicht entkommen. Wir müssen die Kinder retten, bevor die Horde ihre Bombe abwirft!\n\nNehmt meinen Hippogryph und rettet damit die jungen Druiden im Hain von Thal'darah. Setzt sie am Hippogryphenposten hier in der Stadt ab.\n\nRettet sie alle, {name}! Ihr seid wahrlich unsere einzige Hoffnung.", sourceObjective = "Rettet mit Meister Thal'darahs Hippogryph 5 hilflose junge Druiden aus dem Hain von Thal'darah.", completion = "Habt Dank, {name}. Der Held, auf den wir gewartet haben, ist endlich gekommen - und keinen Augenblick zu früh.", sourceObjectiveStatus = "unverified-source-field" }
quests[25890] = { id = 25890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nespirah", description = "Jetzt ist mir klar, was wir tun müssen, {name}.\n\nDie Naga können diese Perlen nur von einem Ort haben: Nespirah, das uralte Schalenwesen, das außerhalb dieser Höhle ruht. Warum Nespirah sich den Naga unterwirft, ist mir allerdings schleierhaft.\n\nWir können durch eine kleine Röhre in der Nähe des Ausgangs dieser Höhle in Nespirahs Körper eindringen. Ich muss zuerst noch meinen Meister holen, danach können wir uns im Inneren treffen. Wir werden Nespirah durch den nordwestlichen Eingang betreten.", sourceObjective = "Betretet Nespirahs nordwestlichen Eingang und findet dann einen Weg, um mit ihr zu sprechen.", completion = "Erunak vertraut diese Aufgabe mir an? Nun gut. Mal sehen, was wir von der Ahnin lernen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25891] = { id = 25891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Letzte Anstrengung", description = "Die Horde signalisiert den Rückzug. Seht, wie sie das Schlachtfeld verlassen - das ist der Vorbote einer Katastrophe.\n\nWir müssen ein letztes Mal im Hain von Thal'darah landen. Ich würde es nicht ertragen, wenn auch nur ein junger Druide zurückbleiben müsste.\n\nHelft mir, <Held/Heldin>. Ich nehme die Zügel. Sucht Ihr nach Druiden, die vielleicht zurückgelassen wurden.\n\nWir brechen auf, wenn Ihr bereit seid.", sourceObjective = "Helft Meister Thal'darah bei der Suche nach Druiden, die im Hain von Thal'darah zurückgelassen wurden.", completion = "Wisst Ihr, weshalb die Horde zerstört? Die Horde zerstört, weil sie Schönheit nicht begreifen kann. Sie fürchtet sie, und was sie fürchtet, muss sie zerstören. Warum sonst zerstört sie den Hain von Thal'darah?\n\nGemeinsam werden wir dafür sorgen, dass sie etwas verstehen. Sie werden verstehen, dass ihre Taten einen hohen Preis fordern.", sourceObjectiveStatus = "unverified-source-field" }
quests[25892] = { id = 25892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltlos", description = "Ihr müsst mich später auf den neusten Stand bringen. Im Augenblick müssen wir hier verschwinden, bevor weitere Naga vorrücken. Begebt Euch zum Vorposten auf der Ebene unter uns.\n\nNehmt mein Seepferdchen. Wir treffen uns dort in Kürze.", sourceObjective = "Benutzt Wellensprecherin Valorens Seepferd, um zu Admiral Dvorek unter der südlichen Terrasse in den Ruinen von Vashj'ir zurückzukehren.", completion = "Ihr habt es geschafft! Nach dem Angriff auf den Vorposten dachte ich, wir wären die einzigen Überlebenden. Freut mich sehr, Euch zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25893] = { id = 25893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verzweifelter Plan", description = "Jorlan und Hexasept sind aufgebrochen, um Hilfe zu holen. Die Handelsrouten sind nicht weit entfernt, daher besteht die Chance, dass sie Erfolg haben. Ich wage es jedoch nicht, den anderen zu viel Hoffnung zu machen.\n\nOffen gestanden haben wir keine andere Wahl. Früher oder später werden die Naga uns finden und... nun... Ihr habt selbst gesehen, wie viele es sind.\n\nIhr solltet die beiden auf dem Biel'arangrat im Südosten suchen. Ich kümmere mich solange so gut es geht um die Sicherheit der anderen hier.", sourceObjective = "Trefft Euch mit Ingenieur Hexasept auf dem Biel'arangrat.", completion = "Pünktlich wie ein Uhrwerk! Der Ärger kommt. Ihr kommt. Und rettet den Tag. Uhrwerk!\n\nWir haben einen brillanten Plan. Er ist herrlich einfach, abgesehen von den Bewohnern in der Gegend hier. Und jetzt, da Ihr hier seid, wird er noch einfacher!", sourceObjectiveStatus = "unverified-source-field" }
quests[25894] = { id = 25894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliche Gewässer", description = "Hexasept kam mit einer Art Ballon hierher, den er von einem unserer Schiffe gerettet hat. Er hat versucht, damit nach oben zu schweben, aber diese Schlickhautschnorrer kamen aus dem Nichts und haben das Ding umschwärmt.\n\nJetzt hat er eine Idee für einen weiteren Ballon, aber wir müssen sicherstellen, dass es nicht wieder genauso abläuft. Ihr müsst diese Kiemengoblins töten. Oder zumindest so viele, dass sie etwas mehr Angst vor uns haben.", sourceObjective = "Tötet 10 Schlickhautschnorrer.", completion = "Je weniger Kiemengoblins, desto besser.\n\nIch bin froh, dass sie so primitiv sind. Ich hätte keine Lust, mich mit einem Volk von schwimmenden Technikliebhabern auseinanderzusetzten. Überhaupt keine Lust.", sourceObjectiveStatus = "unverified-source-field" }
quests[25895] = { id = 25895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer vorbereitet", description = "Wir müssen immer vorbereitet sein. Wir müssen Ausrüstung haben. Wir müssen Pläne haben!\n\nAlle Schiffe in der Flotte der Allianz sind mit einer Überlebensausrüstung ausgestattet. Viele unserer Werkzeuge stammen aus so einer Überlebensausrüstung. Mein Ballon war auch in so einer Überlebensausrüstung enthalten! Aber jetzt ist sie aufgebraucht. Ich brauche noch eine Überlebensausrüstung!\n\nSüdöstlich von hier liegt ein Schiff. Wollen wir hoffen, dass die Überlebenden dumm genug waren und die Überlebensausrüstung nicht mitgenommen haben. Mehr zum Überleben für uns!", sourceObjective = "Besorgt eine Überlebensausrüstung der Allianz.", progress = "Eine ganze Kiste voller aufregender Dinge! Genau das brauche ich. Mehr Aufregung in meinem Leben.\n\nKeine Sorge, ich teile mit Euch.", completion = "Mal sehen, mal sehen… Leuchtpistole… Ballon… kein Seil. Nie ist ein Seil dabei. Furchtbar unpraktisch, wenn Ihr mich fragt. Seil sollte zum Pflichtinhalt gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[25896] = { id = 25896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andächtige Versammlung", description = "Ah, Kriegsmaid. Das Wort und der Wille unserer Lady sind mit Euch. Ich möchte Euch um einen Gefallen bitten…\n\nTiefenrufer Azrajar und meine Gezeitenpriesterinnen müssen zurückkehren, damit wir mit dem Ritual beginnen können. Könnt Ihr ihnen meinen Wunsch überbringen? Ihr solltet sie auf der Tempelterrasse und den Treppen unten finden. Azrajar hält sich an der Treppe im Norden auf.", sourceObjective = "Sucht Tiefenrufer Azrajar in der Mitte der nördlichen Treppe sowie 6 Gezeitenpriesterinnen der Sira'kess auf der oberen Ebene der Ruinen und tragt ihnen auf, zum Tempel zurückzukehren.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Die Bedrohung ist vielleicht nicht gewiss, aber die Kvaldir sind keine Narren. Sie würden nicht zurückkehren, wenn sie nicht zumindest ein wenig an ihren Sieg glauben würden.\n\nJe schneller unsere Verbündeten gerufen werden können, umso besser. Sucht nach meinen Gezeitenpriesterinnen.", completion = "Die Kvaldir haben sich als größere Bedrohung herausgestellt, als wir dachten. Aber unsere Pläne konnten sie nicht im Geringsten vereiteln. Wenn unsere Verbündeten eintreffen, werden wir mehr als genug Streitkräfte haben, um den Gezeitenjäger zu stürzen.\n\nWir müssen nur sicherstellen, dass das Beschwörungsritual abgeschlossen werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[25897] = { id = 25897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seilakrobatik", description = "In Überlebensausrüstungen sind nie Seile enthalten. Das ergibt doch keinen Sinn! Überhaupt keinen!\n\nIch wette, diese Kvaldir haben Seile. Sie fahren immer in Booten herum, knüpfen Knoten und ziehen sich sogar Netze an. Geht und stehlt ihnen ein paar Seile! Ich brauche dringend welche für meinen Plan. Unbedingt!", sourceObjective = "Sammelt 8 Kvaldirseile.", progress = "Das Seil bindet die Bestandteile des Plans zusammen!", completion = "Das ist spitze! Ich liebe es. Es sollte perf… iiihh! Ist das etwa aus Haaren geflochten?\n\nEgal. Fast fertig. Dieses Ding ist im Seilumdrehen bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25898] = { id = 25898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre und Privileg", description = "Fertig! Ich bin mir ganz sicher, dass es funktionieren wird. Und nicht ein Schnorrer in Sicht, der wieder ein Loch hineinstoßen könnte! Welch günstiger Zufall.\n\nJorlan ist bereits nach oben geschwommen, um ihn zu packen. Ist hochgeschwommen und wartet jetzt dort. Er meinte aber, er würde Euch die Ehre überlassen. So ist Jorlan eben.\n\nSchwimmt zum Ballon an der Oberfläche, nehmt die Leuchtpistole aus der Kiste und haltet am Horizont nach Schiffen der Allianz Ausschau. Wenn Ihr welche seht, schießt das Leuchtfeuer in ihre Richtung. Das war es auch schon!\n\nAuftauchen, Schwimmen, Signalfeuer, Rettung! Der letzte Teil gefällt mir am besten.", sourceObjective = "Schwimmt zur Oberfläche, holt die Leuchtpistole und feuert ein Rettungsleuchtfeuer in Richtung der Allianzschiffe.", progress = "Das sind keine Handelsschiffe, das sind Kriegsschiffe. Dennoch haben wir unglaubliches Glück. Schießt das Leuchtfeuer ab und betet, dass sie es sehen.", completion = "Perfekt! Ob im Kampf oder nicht, das können sie nicht übersehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25899] = { id = 25899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch", description = "Die flammende Armee, die oben auf dem Hügel so viel Verwüstung angerichtet hat, hat sich in den Osten zurückgezogen. Nur die sengenden Fürsten sind noch zugange. Wenn wir ihre Reihen durchbrechen könnten, um uns mit Hauptmann Eisenstamms Truppen zusammenzutun, könnte ihre gesamte Offensive scheitern.\n\n{class}, ich bin nicht in der körperlichen Verfassung, noch weiter zu kämpfen, aber Ihr seht aus, als könntet Ihr ihnen noch die ein oder andere Blessur zufügen. Tötet diese sengenden Fürsten und formiert Euch mit Hauptmann Eisenstamm neu!", sourceObjective = "Tötet 10 sengende Zwielichtfürsten.", completion = "Wie viele habt Ihr getötet? Sieh mal an. Ein beeindruckendes Schauspiel. Ich schätze, meine Männer haben jetzt keine Ausreden mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[25900] = { id = 25900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontaktaufnahme", description = "Ich kann mir kaum vorstellen, dass Nespirah freiwillig zulässt, dass diese Naga in ihrer Schale ihr Lager aufschlagen. So wie ich das sehe, ist eines von zwei Dingen geschehen: Entweder haben sie sie überzeugt, sich ihrer Sache anzuschließen, oder sie haben sie so geschwächt, dass sie sich nicht wehren kann. Beide Möglichkeiten sind nicht gut.\n\nHier in diesem Raum sollte ich direkt mit Nespirah kommunizieren können. Finden wir es also selbst heraus. Sprecht mit mir, wenn Ihr bereit seid, {class}.", sourceObjective = "Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.", progress = "Nespirah braucht unsere Hilfe. Zumindest das spüre ich ganz deutlich.", completion = "Das ist nicht so gut gelaufen. Aus irgendeinem Grund antwortet das Geschöpf mir nicht.\n\n<Duarn ist sichtlich frustriert.>\n\nWenn Erunak uns nur nicht verlassen hätte! Er wüsste sicher, was zu tun ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[25901] = { id = 25901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederverwertung auf dem Hyjal", description = "Verstärkung! Ich dachte, wir müssen hier bis zum bitteren Ende kämpfen.\n\nEs sind nur noch wenige Wächter des Hyjal übrig. Zudem gehen uns langsam aber sicher die Vorräte aus. Auf dem Schlachtfeld um unsere letzte Bastion herum sollte eine Unmenge noch funktionstüchtiger Pfeile herumliegen.\n\nIch weiß, dass es für jemanden mit Euren Fähigkeiten fast schon lächerlich einfach ist, aber könntet Ihr unsere gebrauchte Munition aufsammeln? Nur so können wir unsere Vorräte aufstocken.", sourceObjective = "Sammelt 15 Pfeile des Aufsehers.", progress = "Pfeile des Aufsehers werden aus lebender Eiche geschnitzt und in den Mondbrunnen gesegnet. Ihre Pfeilspitzen bestehen aus Obsidian, das mit Runen verziert ist, die den Segen der Natur beschwören.\n\nSie sind nicht gerade billig.", completion = "Wunderbar! Immer noch scharf. Die Befiederung ist ein wenig blutig, aber sie fliegen noch gerade.\n\nDanke, {name}. Jetzt können wir den Hyjal weiter verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25904] = { id = 25904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hammer und der Schlüssel", description = "Meine Nemesis. Ist noch am Leben.\nDie Diener des Feuers noch auf dem Vormarsch.\nWir müssen ihnen folgen. In ihren Bau.\n\nDie Oger kennen den Weg.\nTötet die Feldhauptmänner.\n\nBergt die Glyphe des Öffnens.\n\nSo soll es sein.", sourceObjective = "Tötet einen Zwielichtfeldhauptmann und besorgt Euch die Glyphe des Öffnens.", progress = "Die Glyphe. Zeigt sie mir.", completion = "Diese Macht ist uralt.\nPrimitiv.\nEinfach.\n\nWir werden sie gegen sie einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25905] = { id = 25905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widder auf der Flucht", description = "Die Widder, die wir hier auf dem Gehöft Bernruh züchten und ausbilden, werden von den Gebirgsjägern von Dun Morogh als Reittiere verwendet. Ja, es sind ein paar hier, aber nicht genug, um meine Familie und all die Tiere zu schützen.\n\nEinige mutige Frostmähnenräuber stehlen in letzter Zeit unsere Widder im Schutz der Nacht und bringen sie nach Süden in die Tundridhügel. Würdet Ihr uns helfen, sie zurückzuholen? Geht nah an sie heran und stoßt einen schrillen Pfiff aus, um ihre Aufmerksamkeit zu erregen. Den Rest erledigt ihre Ausbildung.", sourceObjective = "Benutzt /pfeifen, um 6 gestohlene Widder aus den Tundridhügeln zurückzuholen.", completion = "Die Widder, die Ihr gerettet habt, sind in ihren Stall zurückgekehrt. Meine Familienmitglieder werden sie ab jetzt Tag und Nacht bewachen. Diese Trolle werden uns nicht noch einmal übertölpeln!", sourceObjectiveStatus = "unverified-source-field" }
quests[25906] = { id = 25906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das dritte Flammentor", description = "Prägt Euch die Glyphe ein.\nNehmt sie mit Euch.\nZeichnet sie auf den Boden vor dem Flammentor.\nÖstlich von hier.\nBetretet die Feuerlande.\n\nIch kann nicht mit Euch kommen.\nAber meine Kinder erwarten Euch.\n\nSucht Garunda Bergkuppe im Reich der Flammen.", sourceObjective = "Reist durch das Flammentor in der Verbrannten Ebene und sucht nach Garunda Bergkuppe.", completion = "Der Schildkrötengott hat Euch geschickt? Gepriesen sei sein heiliger Panzer! Ich dachte, ich wäre hier unten für immer gefangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25907] = { id = 25907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sklavenarbeit", description = "Ich werde ein wenig Zeit benötigen, um diese Barriere zu durchbrechen und mit Nespirah zu kommunizieren. In der Zwischenzeit könnt Ihr einige der Männer retten, die die Naga in den Gruben unter uns versklavt haben.\n\n<Duarn holt ein langes Seil aus seinen Roben hervor.>\n\nDas wird Euch sicher gute Dienste leisten.", sourceObjective = "Benutzt Duarns Seil, um 8 versklavte Perlenminenarbeiter zu retten.", completion = "Ausgezeichnete Arbeit, {name}… Obwohl ich fürchte, dass ich nicht annähernd so produktiv war wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[25908] = { id = 25908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bestraft sie", description = "Ich kann vielleicht nicht direkt mit Nespirah kommunizieren, aber ich kann zumindest indirekt etwas spüren. Zum Beispiel fühle ich deutlich, dass Nespirah alles andere als glücklich über die Anwesenheit der Naga hier ist.\n\nAls wir in Nespirahs Körper eingedrungen sind, sah ich Dutzende von Schildwachen und Verzauberinnen, die im zentralen Raum patrouillieren. Vielleicht könnt Ihr das Leid der Ahnin lindern, indem Ihr ihre Zahlen verringert.", sourceObjective = "Tötet 7 Schildwachen des Idra'kess und 7 Verzauberinnen des Idra'kess.", completion = "Könnt Ihr es fühlen? Wenn Ihr nur einen Tropfen Schamanenblut in Euch tragt, müsst Ihr das Gefühl der Erleichterung in der Luft spüren.\n\nNespirah ist erfreut. Vielleicht spricht sie jetzt endlich mit uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[25909] = { id = 25909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fang den Krebs", description = "Jede Faser meines Körpers sagt mir, dass Nespirah versucht, mit mir zu sprechen, aber ich kann sie nicht hören. Vielleicht haben die Naga etwas mit ihrer Stimme angestellt.\n\n<Duran grübelt einen Moment vor sich hin.>\n\nNespirahs Stimme wird vielleicht unterdrückt... das bedeutet,... dass wir eine Stimme für sie finden müssen!\n\nIch hab's! Idra'kess' Naga richten Tiefensucherkrebse als Schlachtgefährten ab. Benutzt dieses Netz, um einen Krebs zu fangen und bringt ihn mir. Wahrscheinlich findet Ihr sie am äußeren Rand der Kammer herumkrabbeln.", sourceObjective = "Benutzt Duarns Netz, um einen Tiefensucherkrebs in Nespirah zu fangen.", progress = "Ich hoffe, dass das funktioniert. Meine Fähigkeiten als Schamane sind begrenzt. Ich fürchte, dass diese Aufgabe vielleicht zu schwer für uns ist.", completion = "<Duarn sieht den Krebs an und unterdrückt ein Stirnrunzeln.>\n\nEr sieht nicht besonders beeindruckend aus, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[25910] = { id = 25910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit für Gnade ist vorbei", description = "Diese Höhle ist der reinste Höllenschlund, {name}. Sie ist voller abscheulicher Schrecken aus der Tiefe.\n\nIch möchte nicht, dass diese… Kreaturen… durch das Portal in die Außenwelt gelangen. Tötet sie alle!", sourceObjective = "Tötet 10 geschmolzene Peiniger und 4 Meister der Schattenflamme.", completion = "Also ist es vollbracht.\n\nDas Wissen, dass der Schattenhammerkult gemeinsame Sache mit solch abstoßenden und bösartigen Wesen macht… bringt mein Blut zum Kochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25911] = { id = 25911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommene Nachrichten", description = "Sie schicken bestimmt ein Ruderboot. Das kann ein bisschen dauern. Ich bleibe hier, um mich mit ihnen in Verbindung zu setzen.\n\nIhr müsst sofort zur Höhle zurückkehren und Bescheid geben, dass Rettung auf dem Weg ist. Wir können nur hoffen, dass die Naga sie noch nicht gefunden haben.\n\nGeht. Schwimmt schnell, {name}.", sourceObjective = "Kehrt zu Kapitän Taylor am Stillen Strand zurück.", completion = "Das sind die besten Nachrichten seit einer Ewigkeit. Wir werden die Überlebenden so schnell wie möglich an die Oberfläche bringen. Vielleicht können wir vergessen, dass dieser Alptraum überhaupt stattgefunden hat.\n\nDanke, {name}. Ich weiß nicht, wie ich Euch für all das belohnen kann, das Ihr in diesem Meer getan habt, aber ich werde mir etwas einfallen lassen.\n\nIhr solltet Euch mit uns an den Schiffen treffen, wenn Ihr Euch gebührend von den Naga verabschiedet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25912] = { id = 25912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gute alte Zeit", description = "Die Welt gerät aus den Fugen, {name}. Vertraute Feinde versuchen uns an einer Seite zu zerstören, während uralte Kräfte uns von der anderen bedrängen.\n\n<Urahnin Sareth'na seufzt.>\n\nIch habe bessere Zeiten erlebt - hellere Tage, und ich sehne mich nach ihnen...\n\nHinter dem Steinkrallengipfel stehen die Ruinen unseres alten Außenpostens - die Dunkelheit hat ihn überrannt. Solltet Ihr Euch in dieser Gegend aufhalten, könntet Ihr dann nach meinem Zeichenbuch suchen? Es steckt voller glücklicher Erinnerungen. Ich würde Euch gut für seine Rückgabe belohnen.", sourceObjective = "Findet das Zeichenbuch der Urahnin Sareth'na.", progress = "Habt Ihr mein Zeichenbuch gefunden?", completion = "Ihr habt es gefunden! Möge Elune Euch segnen, Kind! Vielleicht verleiht mir dieses Buch die Kraft weiterzumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25913] = { id = 25913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Ruhe", description = "Als die Horde ins Steinkrallengebirge einmarschierte, fiel mir auf, dass einige der Schildwachen krank wurden. Kurz darauf verhielten sie sich seltsam. Als der erste Tentakel aus dem Boden schoss, griffen die kranken Schildwachen uns an. Wir verloren den Außenposten kurz danach...\n\nDie Schildwachen im Gipfel sind nur noch Hüllen. In ihnen steckt etwas Böses. Bettet die Schildwachen zur letzten Ruhe und bringt ihre Gleven an Euch. Mit jeder zurückgebrachten Gleve kann eine gefallene Schwester identifiziert werden.", sourceObjective = "Bergt 8 Schildwachengleven.", progress = "Bergt die Schildwachengleven, {name}. Jede Gleve lässt sich einer Schildwache zuordnen.", completion = "Danke, {name}. Auf jede der Gleven ist der Name ihrer Besitzerin eingestanzt. Jetzt können wir ihre Familien benachrichtigen und ihren Seelen Frieden geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25914] = { id = 25914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Tiefe!", description = "Ranken schießen aus dem Boden und terrorisieren den Steinkrallengipfel. Meine Schildwachen werden ihrer nicht Herr.\n\nIch vermute, dass es im Herzen des Steinkrallengipfels eine Macht gibt, die diese Ranken kontrolliert. Wenn wir diese Macht aufhalten, werden die Ranken vielleicht in die Tiefen zurückkehren, aus denen sie gekommen sind.", sourceObjective = "Tötet Aph'lass und 10 einfallende Tentakel.", completion = "Der Tod des Boten Aph'lass hat leider nicht zu einem Ende der Rankenangriffe geführt. Ihr habt getan, was Ihr konntet, {name}. Dafür danke ich Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25915] = { id = 25915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollas Stärke", description = "Der dunkle Usurpator Nemesis floh hierher, als die Feuer des Hyjal verglommen. Wir sind noch nicht stark genug, um Nemesis zu besiegen, {name}, aber wir können vielleicht seine eigene Stärke gegen ihn verwenden.\n\nIch werde einen Abkömmling Tortollas mit Euch entsenden, eines der Kinder, das Ihr aus der Verderbnis des Zwielichts errettet habt.\n\nSucht in den Tiefen dieser Höhle nach einem Nemesiskristall und erlaubt der jungen Schildkröte, ihn zu untersuchen.\n\nFalls Ihr Euren Begleiter verliert, meldet Euch bei mir!", sourceObjective = "Begleitet einen Abkömmling von Tortolla zu einem Nemesiskristall. Falls Ihr Euren Begleiter verliert, meldet Euch bei Garunda Bergkuppe.", completion = "Ah, ja, ja… Die geheime Stärke von Nemesis, zugänglich hier in diesen Höhlen.\n\nWir wissen alles, was wir wissen müssen, {name}. Jetzt ist es Zeit, der Angelegenheit ein Ende zu setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25916] = { id = 25916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchbruch", description = "Ein ausgebildeter Schamane kann mit den vier Elementen der Erde, des Feuers, der Luft und des Wassers kommunizieren. Das ist kein Geheimnis.\n\nWas jedoch viele nicht wissen ist, dass es noch ein fünftes Element gibt. Dieses Element ist nicht so eindeutig definiert wie die anderen vier, aber es hat etwas mit der... Gemeinsamkeit zwischen allen lebenden Wesen zu tun.\n\nIch bin der Meinung, dass der Krebs als Wesen des Meeres eng genug mit Nespirah verbunden ist. Mit ein wenig Überredungskunst der Elemente können wir ihn vielleicht dazu bringen, als Nespirahs Sprachrohr zu dienen.", sourceObjective = "Beobachtet Erdheiler Duarn, während er versucht, mit Nespirah zu sprechen.", completion = "Ich bin davon ausgegangen, dass die Naga nur wegen der Perlen hier sind. Nein, das ergibt deutlich mehr Sinn. Wenn sie Nespirahs Macht unter ihrer Kontrolle hätten, könnten die Naga katastrophale Schäden anrichten!\n\nWir müssen etwas unternehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25917] = { id = 25917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir sind nicht allein", description = "<Duarn schließt die Augen, hält einen Moment inne und nickt.>\n\nNespirah hat mir gerade berichtet, dass wir nicht die Einzigen sind, die in dieser Schale kämpfen. Eine kleine Gruppe von Allianzsklaven ist entkommen und wehrt gerade die Naga auf der anderen Seite der Schale ab, oben auf dem Vorsprung über Nespirahs Herz.\n\nGeht und findet sie, {name}. Schaut, wie Ihr sie unterstützen könnt. Mit ihrer Hilfe können wir Nespirah vielleicht aus ihrer Starre erwecken.\n\nIhr findet mich hier, falls Ihr etwas braucht.", sourceObjective = "Findet die Überlebenden der Allianz in Nespirah in Vashj'ir.", completion = "{name}… Seid Ihr das?", sourceObjectiveStatus = "unverified-source-field" }
quests[25918] = { id = 25918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnungslos ausrüstungslos", description = "Ich habe wirklich keine Ahnung, wie wir so lange hier überleben konnten. Die Naga haben mir meine Rüstung und meine Waffen genommen. Alles, was sie mir gelassen haben, sind Lumpen und eine Spitzhacke… und DIE ist schon vor einer halben Ewigkeit zerbrochen.\n\nWenn wir eine Chance haben wollen, das Blatt zu unseren Gunsten zu wenden, brauche ich etwas, mit dem ich kämpfen kann. Meinen Kameraden geht es genauso, aber sie sind sicher zu stolz, um es zuzugeben.\n\nIch habe in den Lagerbereichen der Naga Waffenregale gesehen. Ich bin zwar im Umgang mit einem Dreizack nicht sonderlich geübt, aber alles ist besser, als mit bloßen Händen zu kämpfen.", sourceObjective = "Besorgt 4 entwendete Stangenwaffen aus den Waffenregalen in Nespirah.", progress = "Als ich jung war, wurde ich ein wenig im Speerkampf ausgebildet.\n\nWas hat man mir da noch mal beigebracht? Ach ja, \"Piekse sie mit dem spitzen Ende\". Oder so ähnlich...", completion = "<Admiral Dvorek bewundert geistesabwesend die Stangenwaffen, die Ihr ihm gegeben habt.>\n\nOh, tut mir leid. Ich habe mir nur gerade vorgestellt, wie sie wohl aussehen, wenn kleine Nagafetzen an ihren Spitzen hängen. Vielen Dank, {name}. Wir werden sie sinnvoll einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25919] = { id = 25919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voller Körpereinsatz", description = "<Kapitän Taylor lauscht aufmerksam, als Ihr das Gespräch zwischen Duarn und Nespirah wiedergebt.>\n\nIch verstehe. Also möchte das Wesen, dass wir ihm helfen, es zu wecken?\n\nWenn man bedenkt, dass Hunderte von Sklaven seine Perlen abbauen, muss es aber ganz schön fest schlafen. Vielleicht habt Ihr ja mehr Glück.\n\nMein Vorschlag? Sucht am Fleisch des Wesens nach Schwachstellen. Vielleicht finden Eure Waffen ja eine empfindliche Stelle. Dann wird es sicher zur Besinnung kommen.", sourceObjective = "Greift 7 Abszesse von Nespirah an den Wänden von Nespirahs Körperkammer an.", completion = "Hoffentlich haben wir damit einen Fortschritt erzielt. Ich bin mir nicht ganz sicher, woher wir wissen sollen, ob das Wesen erwacht ist, aber mein Gefühl sagt mir, dass wir es kaum übersehen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[25920] = { id = 25920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer noch wertvoll", description = "Auch wenn ich nur wenig Zeit in den Perlenminen verbracht habe, bin ich doch neugierig, was die Naga vorhaben. Ja, ich weiß, dass die Naga Nespirah als Kriegsmaschine nutzen wollen, aber wenn das der Fall ist, warum verwenden sie dann Sklavenarbeiter, um ihre Perlen abzubauen?\n\nWenn wir es je schaffen, den Rumpf dieses Tiers zu verlassen, würde ich diese Gegenstände gerne untersuchen. Die Perlen, die wir in den Minen gefunden haben, waren zu groß, um sie zu tragen. Ich habe jedoch Kriegsherren und Propheten gesehen, die kleinere bei sich hatten.", sourceObjective = "Besorgt 5 mysteriöse Perlen von Kriegsherren des Idra'kess und Prophetinnen des Idra'kess in Nespirah.", progress = "Die Naga müssen etwas Bestimmtes mit diesen Perlen vorhaben. Wenn ich Zeit hätte, sie zu untersuchen, könnte ich sicher herausfinden, was.", completion = "Ausgezeichnete Arbeit!\n\n<Valoren verstaut die Perlen unter ihrer Rüstung.>\n\nUnd jetzt müssen Kapitän Taylor und Ihr mich nur noch heil hier hinausbringen. Den Rest der Untersuchungen schaffe ich dann alleine.", sourceObjectiveStatus = "unverified-source-field" }
quests[25921] = { id = 25921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufseher Idra'kess", description = "Meine Männer lassen nach, {name}. Ich fürchte, wir können diesen Naga nicht mehr lange standhalten. Mit diesen Waffen des Idra'kess und Nespirahs Perlen sollten wir bereit sein, von hier zu flüchten.\n\nFolgt der Wand in Richtung Südosten und haltet nach einer Rampe Ausschau, die in die obere Kammer führt. Ich schätze, dass ihr Anführer sich dort aufhält. Vielleicht ist dort auch der Schlüssel zu Nespirahs Erweckung versteckt. Wenn wir Glück haben sogar beides.\n\nWenn Ihr Euch stark genug fühlt, geht in die Spitze und sucht nach Antworten.", sourceObjective = "Geht zur Spitze Nespirahs und tötet Aufseher Idra'kess.", completion = "Ihr müsst mich nicht auf den neusten Stand bringen. Nespirah hat mir zeitgleich von Euren Abenteuern erzählt und Kapitän Taylor hat mir den Rest berichtet.\n\n<Duarn schließt die Augen und nickt.>\n\nNespirah sagt, dass sie dankbar ist und eine kleine Überraschung für die Naga vorbereitet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[25922] = { id = 25922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erweckung der Bestie", description = "Dank Euch und dem Kapitän hat Nespirah wieder die volle Kontrolle über ihren Körper… aber der Großteil der Naga weiß das noch nicht. Sobald wir geflüchtet sind, wird sie ihre biologischen Verteidigungsmechanismen aktivieren und die Naga von innen heraus vernichten.\n\nMacht Euch bereit... Ich sage Nespirah, dass sie die Verteidigung einleiten soll.", sourceObjective = "Sprecht mit Erdheiler Duarn in Nespirah, um ihre biologische Verteidigung zu aktivieren und flieht dann aus Nespirahs Körper.", completion = "Wie es scheint, verdanke ich Euch mein Leben, schon wieder. Dem Licht sei Dank, dass Ihr mich gefunden habt, bevor Ihr und der Schamane diese biologische Verteidigung aktiviert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25923] = { id = 25923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet Nemesis", description = "Euer Schildkrötenfreund kann diese neu gefundene Macht nutzen, um Euch beide für einen kurzen Augenblick unverwundbar zu machen. Ihr könnt Euch also in Euren \"Panzer\" verkriechen, um Nemesis' schlimmsten Zorn zu entgehen. Ruft dazu einfach dieses Totem herbei.\n\nDas ist alles, was ich für Euch tun kann. Ihr und ein Abkömmling von Tortolla müsst gemeinsam Nemesis besiegen, ein für alle Mal. Vernichtet den Usurpator!\n\nFalls Ihr Euren Schildkrötenfreund verliert, kehrt zu mir zurück.", sourceObjective = "Benutzt das Totem von Tortolla, um einem Abkömmling von Tortolla dabei zu helfen, Nemesis zu besiegen. Falls Ihr Euren Schildkrötenfreund verliert, sprecht mit Garunda Bergkuppe.", completion = "Der Usurpator ist nicht mehr!\n\nDer Schattenhammer hat davon geträumt, sich sein eigenes Pantheon von Göttern zu schaffen, die über Land, Meer und Luft herrschen. Doch mit Eurer Hilfe wurden sie alle vernichtet. Wir müssen sofort Tortolla davon berichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[25924] = { id = 25924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Pflicht ruft", description = "Hört zu, {race}!\n\nAn der Küste der Östlichen Königreiche ist eine neue Landmasse aufgetaucht! Eine wichtige Schlacht um die Kontrolle dieser Insel ist bereits im vollen Gange.\n\nWenn wir hier gewinnen, ist Sturmwind komplett unverteidigt!\n\nJetzt ist die Zeit, um zuzuschlagen!\n\nMeldet Euch sofort an den Docks, damit man Euch zur Schlacht bringt.\n\nAll unsere Kriegsschiffe befinden sich bereits im Kampf, also werdet Ihr ein Söldnerboot nehmen, das vom Kriegshäuptling selbst angeheuert wurde.", sourceObjective = "Fahrt mit dem Söldnerboot zur Schlacht.", completion = "Ich wette, dass Ihr eine andere Art von Schlacht erwartet habt. Aber es ist dennoch eine Schlacht, Ihr werdet schon sehen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25925] = { id = 25925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thal'darahs Rache", description = "Wir müssen versuchen, Kontakt zum Weitblicktal im Süden herzustellen. Unsere darnassischen Glevenwerfer stehen Euch zur Verfügung, {name}. Schlagt mit ihnen eine Schneise in die anrückenden Hordenstreitkräfte und räumt einen Weg ins Weitblicktal frei.\n\nHoffentlich ist es noch nicht zu spät, um das Tal zu retten. Sollte das Weitblicktal unversehrt sein, dann sucht dort nach Hierophant Malyk und informiert ihn über unsere Lage.", sourceObjective = "Tötet 20 Soldaten der Horde und zerstört 3 Verwüster von Krom'gar im Kriegsnarbental.", completion = "Wir haben die Explosion der Bombe beobachtet. Was für eine furchtbare Zerstörung... Das Weitblicktal ist unversehrt, was immer das auch nutzen mag. Allerdings wissen wir nicht, wohin wir fliehen sollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25926] = { id = 25926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Modernder Hass", description = "Die Morastbestien im Westen sind nicht meine Brüder... sie sind Symptome der gestörten Erde, eine modernde, Gestalt gewordene Verderbtheit.\n\nIhr würdet es nicht verstehen... sie nehmen die Gestalt meines Volkes an, sind jedoch mit verrottenden Sporen durchsetzt. Sie vertreiben das blühende Leben aus dem Sumpf. Sie nehmen alles und lassen nur Verderbtheit zurück. Nichts bleibt zurück! Nichts!\n\nTröstet mich, {race}. Tötet die Morastbestien und reinigt das Land. Vielleicht bringt mir das Frieden.", sourceObjective = "Tötet 10 modernde Morastbestien.", completion = "Ahhh... ja. Der Sumpf leidet weniger als zuvor.\n\nEs gibt jedoch noch mehr Bedrohungen. Sie lauern. Ich kann sie sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25927] = { id = 25927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennende Bedrohung", description = "Die Flammen bedrohen mich schon seit langer Zeit... zu langer Zeit... aber es sind keine kleinen mehr, nicht mehr nur noch Funken...\n\nDie Felder brennen! Die Hügel und Hochlande schreien, {race}, sie schreien. Die Elementare, die hierher gebracht wurden, lassen nur Tod zurück.\n\nDas darf nicht so weitergehen. Haltet sie auf. HALTET SIE AUF! Vernichtet die Flammenboten...", sourceObjective = "Tötet 8 zügellose Feuerelementare.", completion = "Ja... die Flammen vergehen. Nun herrscht Friede. Das Land findet Frieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[25928] = { id = 25928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tortollas Triumph", description = "Ich werde die Abkömmlinge von Tortolla hier heraus begleiten und dieses verfluchte Portal versiegeln.\n\nIch überlasse es Euch, Tortolla von unserem Sieg zu berichten. Tretet einfach wieder durch das Flammentor. Der Ahn wird begeistert sein!", sourceObjective = "Geht erneut durch das Flammentor und kehrt zu Tortolla auf der Verbrannten Ebene auf dem Hyjal zurück.", completion = "Ihr wart in den Feuerlanden?\n\nNemesis ist tot?\n\nAlso ist es vorbei.\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[25929] = { id = 25929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seetauglich", description = "Grüße, {class}. Ich bin Erunak, einer der Überlebenden dieses Unglücks.\n\nIch fürchte, die Mühen haben für Euch gerade erst begonnen. Die Naga durchstreifen die Gewässer und greifen alles an, was noch am Leben ist.\n\nIhr seid an die hiesigen Bedingungen noch nicht ausreichend angepasst, um zu überleben, aber das kann ich ändern.\n\nDirekt außerhalb dieses Schiffes lebt eine besondere Art von Seestern. Bringt mir einige davon und ein Tritonshorn. Ich werde eine Verzauberung vorbereiten, die Euch dabei helfen wird, Euch an die neue Umgebung zu gewöhnen.", sourceObjective = "Sammelt 3 Salzwasserseesterne und ein Tritonshorn am Meeresgrund im Verhängnis der Legion.", progress = "Konntet Ihr alle Gegenstände finden, die ich brauche, {race}?", completion = "Bitteschön, {class}. Damit solltet Ihr Euch im Meer fast mühelos bewegen können.\n\nDoch jetzt müssen wir uns an die Arbeit machen. Wir haben viel zu tun, aber nur wenig Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25930] = { id = 25930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talstürmer", description = "Man hat mir erzählt, dass das Verbrannte Tal vor dem großen Umbruch eine Mulde war, ohne Zugang zum Meer. Doch wenn man nun nach Süden blickt, wird deutlich, dass das Verbrannte Tal längst kein Tal mehr ist, sondern ein Gebiet mit großer vulkanischer Aktivität.\n\nSalsbury hat ein Gerät konstruiert, mit dem wir den Vulkan erklimmen können. Benutzt es, um zum Gipfel zu gelangen. Findet heraus, was dort vorgeht.\n\nIch werde mit dem Gnomcordergerät, das Salsbury mir freundlicherweise geschenkt hat, in Kontakt bleiben.", sourceObjective = "Erklimmt mit Salsburys Raketenpack den Vulkan im Verbrannten Tal.", sourceObjectiveStatus = "unverified-source-field" }
quests[25931] = { id = 25931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brut von Seldarria", description = "<Der Gnomcorder summt.>\n\nSeid sehr vorsichtig, {name}. Weckt bloß nicht den schwarzen Drachen auf.\n\nSeht Euch um. Wenn dies ein Nest ist, dann sollte es in der Nähe schwarze Dracheneier geben. Sucht das Gebiet nach Eiern ab und zerstört alle, die Ihr seht.\n\nKehrt zu mir zurück, wenn Ihr Seldarrias Eier gefunden und zerstört habt.\n\nMöge Goldrinn über Euch wachen.", sourceObjective = "Zerstört 5 Eier von Seldarria.", completion = "Ein durchschlagender Erfolg! Es ist vielleicht nur ein kleiner Sieg über die Brut von Todesschwinge, aber wenigstens ein Sieg!", sourceObjectiveStatus = "unverified-source-field" }
quests[25932] = { id = 25932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede Nacht ein Überfall", description = "Die Berichte, die ich Hauptmann Tharran schicke, spiegeln das Ausmaß des Ärgers, den uns die Frostmähnen bereiten, nicht richtig wider. Euer Angriff auf das Dorf hat etwas Druck von uns genommen. Die Überfälle finden immer noch häufig statt, aber es gibt nicht mehr so viele Trolle wie früher.\n\nTrotzdem sind meine Männer erschöpft. Die Moral sinkt. Würdet Ihr uns im Kampf gegen die Frostmähnenräuber unterstützen? Sie können jederzeit auftauchen.", sourceObjective = "Helft Unteroffizier Flinthammer und seinen Gebirgsjägern, das Gehöft Bernruh gegen die Frostmähnenräuber zu verteidigen.", completion = "Dank Eurer Hilfe ist es uns gelungen, die Räuber deutlich zu schwächen. Solche Verluste haben sie seit Beginn der Überfälle nicht mehr erlitten. Wir müssen diesen Vorteil nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25933] = { id = 25933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für den Steinbruch", description = "Ich möchte Euch noch einmal für Eure Hilfe danken, {name}.\n\nMein Cousin hat früher in den Minen unter dem Steinbruch Gol'Bolar gearbeitet, aber seit die Troggs dort eingedrungen sind und die Kontrolle übernommen haben, geht das nicht mehr. Der Steinbruch und sein Lager liegen südöstlich des Gehöfts. Würdet Ihr Euch dort bei dem Großknecht melden und herausfinden, ob man etwas unternehmen kann?", sourceObjective = "Sprecht mit Großknecht Steinbraue im Steinbruch Gol'Bolar.", completion = "Unteroffizier Flinthammer? Der Name sagt mir nichts, aber einer der Minenarbeiter heißt Flinthammer. Er gehört zu den Glücklichen, die aus der Mine fliehen konnten, aber die meisten anderen sind dort unten eingeschlossen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25934] = { id = 25934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weltneuheit: Gnomgen", description = "Guten Tag, Bürger, ich möchte mich Euch vorstellen. Ich bin Salsbury, bald der welterste Gnomgen. Malyk hat mir versichert, dass er mir nach Beendigung meiner Arbeit das Geschenk des Worgen machen wird.\n\nSo, da wir uns jetzt kennen, möchte ich eine Bitte äußern!\n\nSüdlich von hier, im Verbrannten Tal, treiben neu erschaffene Feuerelementare ihr Unwesen. Ich brauche dringend ein seltenes flammendes Herz des Feuers von einem der Unholde. Beschafft es für mich, dann komme ich dem Leben eines Gnomgen einen Schritt näher!", sourceObjective = "Beschafft 1 flammendes Herz des Feuers.", progress = "Habt Ihr das flammende Herz des Feuers bekommen?", completion = "Hervorragend. Damit kann ich meine letzte Aufgabe beenden und hoffentlich die Wolfsform bekommen!\n\n<Salsbury heult.>", sourceObjectiveStatus = "unverified-source-field" }
quests[25935] = { id = 25935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungrige Welpen", description = "Ah, ein Neuankömmling! Gut, dass Ihr hier seid <Junge/Schwester>! Die Welpen sind hungrig, aber uns ist die Nahrung ausgegangen.\n\nZum Glück lieben sie Drachenfleisch, was es in rauen Mengen im Verbrannten Teil südlich von hier gibt.\n\nSeid ein <guter Junge/gutes Mädchen> und besorgt mir ein paar Pfund Schwarzdrachenwelpenfilet.", sourceObjective = "Beschafft 6 Schwarzdrachenwelpenfilets.", progress = "Beeilt Euch, {name}, die Welpen sind hungrig!", completion = "Hervorragend. Die Hunde werden gut zu fressen bekommen und unseren Außenposten wochenlang verteidigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25936] = { id = 25936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie ich Euch, so Ihr ihnen", description = "Jetzt seid Ihr in der Lage, Euch in diesem Reich freier und ohne Angst vor Ertrinken zu bewegen.\n\nUnd jetzt beginnt unsere Arbeit.\n\nZunächst gibt es viele Verbündete von Euch in der Nähe, die in diesem Augenblick im Wasser um ihr Leben ringen. Ich habe Euch gerettet und nun müsst Ihr sie retten.\n\nIch habe die Muschel verzaubert, die Ihr mir gebracht habt. Benutzt sie, um Eure Freunde zu retten.\n\nSchnell!", sourceObjective = "Benutzt das verzauberte Tritonshorn, um 6 ertrinkende Soldaten zu retten.", progress = "Konntet Ihr die Krieger retten, {race}?\n\nOhne ihre Hilfe sind wir verloren…", completion = "Während Ihr fort wart, konnte ich einige der gefallenen Krieger wieder zum Leben erwecken.\n\nWenn wir hier überleben wollen, brauchen wir jede helfende Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[25937] = { id = 25937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unermessliche Reichtümer", description = "In dem Steinbruch wurde nicht nur geschürft. Ich leitete ein Ausgrabungsteam der Forscherliga. Wir suchten nach wertvollen alten Artefakten.\n\nMir gelang die Flucht, aber meine Kollegen hielten sich tiefer in der Mine auf und überlebten den ersten Angriff der Troggs nicht.\n\nSie waren sehr stolz auf ihre Arbeit und riskierten ihr Leben, um mehr über unsere Geschichte herauszufinden. Wenn Ihr in die Minen geht, dann nehmt diese Spitzhacke mit. Vielleicht findet Ihr ja etwas in den Stollen, die von den Ausgräbern begonnen wurden.", sourceObjective = "Bergt 8 gefrorene Artefakte aus der Mine des Steinbruchs Gol'Bolar.", progress = "Habt Ihr dort unten Artefakte gefunden?", completion = "Ich danke Euch für die Bergung dieser Artefakte. Ich werde dafür sorgen, dass sie im Museum von Eisenschmiede ausgestellt werden, zusammen mit der Geschichte derer, die bei ihrer Bergung ums Leben kamen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25938] = { id = 25938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe für Desolace", description = "Ich habe eine verstörende Nachricht aus Nijelspitze in Desolace erhalten. Der große Umbruch hat anscheinend neue Probleme mit sich gebracht, auf die sie nicht vorbereitet waren. Mehr weiß ich nicht.\n\nMeldet Euch bei Offizierin Jankie in Desolace. Sie wird Euch den Weg nach Nijelspitze weisen.\n\nViel Glück, {name}.", sourceObjective = "Meldet Euch bei Offizierin Jankie in Tethris Aran in Desolace.", completion = "Halt, Fremder!", sourceObjectiveStatus = "unverified-source-field" }
quests[25939] = { id = 25939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerteufel", description = "Die Elementare, die auf dem Hügel der Düsterschmiede randalieren, stecken das Land unter sich in Brand. In einem Sumpf wie diesem findet das Feuer im tiefen Moos und Torf ausreichend Nahrung.\n\nLöscht die Feuer, bevor sie sich ausbreiten. Nehmt diese Blume... sie wurde mit dem Regen der Natur gesegnet und wird Euch ermöglichen, die Feuer zu löschen.\n\nIhre Blüten könnten sich außerdem als nützlich gegen die Elementare erweisen.", sourceObjective = "Löscht 7 Moorfeuer mit der gesegneten Flutlilie.", completion = "Ihr habt nicht nur das Land vor weiterem Leid bewahrt, sondern uns auch geholfen, den Sumpfwächter zu besänftigen.\n\nHabt Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25940] = { id = 25940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letztes Gefecht am Rauschenden Hain", description = "Möglicherweise habe wir jetzt eine Chance, die Flammen dank Eurer Arbeit in dem Inferno zu besiegen.\n\nDennoch sind weitere Wildtiere bedroht. Bewahrer Taldros rannte Richtung Norden durch die Flammen zum Rauschenden Hain.\n\nSeht, ob Ihr ihm helfen könnt!", sourceObjective = "Meldet Euch bei Bewahrer Taldros im Rauschenden Hain auf dem Hyjal.", completion = "Die Flammen verschlingen den Wald!", sourceObjectiveStatus = "unverified-source-field" }
quests[25941] = { id = 25941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rast für die Erschöpften", description = "Ihr habt Eure Aufgabe gut gemacht, {race}, aber es gibt noch viel mehr zu tun und ich bin langsam erschöpft.\n\nIch habe sehr viel Energie darauf verwendet, ein Notsignal an die Anführer des Irdenen Rings zu senden und sie um Hilfe zu bitten.\n\nWenn ich uns hier noch weiter von Nutzen sein möchte, muss ich mich ausruhen.\n\nSprecht mit dem Anführer der Männer, die Ihr gerettet habt und tut was Ihr könnt, um ihnen bei den Schlachtvorbereitungen zu helfen.\n\nDie Naga durchkämmen das Wasser nach uns. Es ist nur eine Frage der Zeit, bis sie zurückkehren. Und dann werden sie ganz sicher noch zahlreicher sein.", sourceObjective = "Sprecht mit Legionär Nazgrim.", completion = "Ich verstehe, {race}.\n\nIch weiß, wie dringend es ist, aber diese Männer sind nicht in der Lage zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25942] = { id = 25942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschafft uns Zeit", description = "Viele gute Krieger mussten heute ihr Leben lassen.\n\nWenn das, was der Schamane sagt, stimmt, dann haben wir keine Zeit zu verlieren. Die Naga durchkämmen die Gewässer auf der Suche nach Überlebenden.\n\nWir sind noch nicht bereit, um zu kämpfen. Ihr müsst uns Zeit für die Vorbereitung verschaffen. Findet die Naga, die uns jagen und verlangsamt ihre Fortschritte.", sourceObjective = "Tötet 8 Räuber des Zin'jatar im Verhängnis der Legion.", progress = "Habt Ihr diesem schuppigen Abschaum einen Grund zum Nachdenken gegeben, {class}?", completion = "Hoffen wir einfach, dass Eure Anstrengungen ausreichen, um uns die nötige Zeit zu verschaffen…", sourceObjectiveStatus = "unverified-source-field" }
quests[25943] = { id = 25943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege gehen durch den Magen", description = "Wenn ich diese Orcs für die Schlacht bereit machen möchte, brauche ich Eure Hilfe.\n\nJeder anständige Anführer weiß: Leerer Bauch reist und kämpft nicht gern. Kein Mampf, kein Kampf.\n\nDiese Krieger sind von den kürzlichen Strapazen vollkommen erschöpft. Sie brauchen etwas Nahrhaftes für den Fall, dass die Naga angreifen.\n\nWo wir gerade von leeren Mägen sprechen, da draußen auf dem Meeresboden habe ich einige Krebse gesehen...", sourceObjective = "Sammelt 8 Stück saftiges Krebsfleisch von Spaltscherenhuschern.", progress = "Habt Ihr Nahrung für die Truppen, {race}?", completion = "Ein leckerer Happen.\n\nBald sind wir wieder kampfbereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25944] = { id = 25944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Horde alte Kleider", description = "In unserem Kampf gegen das Ertrinken waren meine Orcs und ich gezwungen, unsere Waffen und einen Großteil unserer Rüstungen zurückzulassen.\n\nErunak sagt, dass er bald einen großangelegten Angriff der Naga erwartet und ich glaube ihm.\n\nWenn wir siegen wollen, müsst Ihr uns dabei helfen, unsere verlorene Ausrüstung zurückzuholen.\n\nEs sollte alles auf dem Meeresboden in der Nähe unserer Schiffswracks hier und im Norden liegen.\n\nSchnell, {race}. Der Feind könnte jeden Moment eintreffen.", sourceObjective = "Sammelt 5 Äxte von Orgrimmar, 5 Brustplatten von Orgrimmar und 5 Helme von Orgrimmar am Meeresboden oder von Strauchdieben der Gilblin im Verhängnis der Legion.", progress = "Konntet Ihr unsere Ausrüstung zusammensammeln, {race}?", completion = "Das habt Ihr gut gemacht, {race}.\n\nUnsere Überlebenschancen steigen stetig.", sourceObjectiveStatus = "unverified-source-field" }
quests[25945] = { id = 25945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir haben hier nur eine Aufgabe, vielleicht auch zwei...", description = "Ihr seid jetzt in Höllschreis Armee, {name}, und in Höllschreis Armee treten wir anderen in den Hintern und sind verdammt nachtragend. Die Zeiten, in denen Leute auf den Straßen Orgrimmars verhungerten, während wir Verträge mit den Elfen schlossen, sind vorbei. Wir holen uns jetzt, was wir brauchen. Kalimdor gehört der Horde!\n\nDie Allianz versucht bei jeder Gelegenheit, unsere Expansion aufzuhalten. Diesen Schweinslutschern gehört bereits ein Großteil der Östlichen Königreiche, aber das reicht ihnen nicht!\n\nOberanführer Krom'gar will mehr Truppen ins Steinkrallengebirge verlegen. Schließt Euch der Karawane westlich von hier an. Geht!", sourceObjective = "Reist mit dem Wagen von Krom'gar zum Bruch im Steinkrallengebirge.", completion = "Solange Ihr im Steinkrallengebirge seid und als ein Soldat Krom'gars kämpft, werdet Ihr Uniform tragen! Ist das klar? HÖRT Ihr mich, Grunzer? Wenn ich Euch ohne Höllschreis geliebten Waffenrock sehe, werde ich Euch so heftig in den Hintern treten, dass Ihr Schnürsenkel ausspuckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25946] = { id = 25946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ScHELMenstück", description = "<Dieser Helm und das passende Zubehör sind mit dem Siegel von Sturmwind gekennzeichnet. Er stammt ohne Zweifel von einem Allianzschiff, dass ein ähnliches Schicksal wie Euer Schiff erlitten hat.>\n\n<Wenn Ihr den Helm genauer betrachtet, fällt Euch auf, dass er viel zu gut verarbeitet und stabil ist, um zu einer normalen Tauchausrüstung zu gehören. Vielleicht weiß Nazgrim ja, was es damit auf sich hat...>", sourceObjective = "Bringt die Kampfschwimmerausrüstung der Allianz zu Legionär Nazgrim in der \"Ewiger Kreislauf\".\n\nBereitgestellter Gegenstand:", completion = "Blut und Donner!\n\nDas ändert alles, {class}!", sourceObjectiveStatus = "unverified-source-field" }
quests[25947] = { id = 25947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer es findet, darf es behalten", description = "Ich erkenne diesen Helm, {race}. Es war klug von Euch, ihn mir zu bringen.\n\nDie Allianz hat eine Spezialeinheit, die für Erkundungen und Kampfeinsätze unter Wasser ausgebildet und ausgerüstet wurde.\n\nWie es scheint, haben sie in dieser Gegend weitaus mehr vor, als sich gegen unseren Angriff zu verteidigen.\n\nEs muss da unten noch mehr davon geben. Wenn Ihr sie findet, könnte sich das Blatt für unseren Vorposten schnell wenden.", sourceObjective = "Sammelt 5 Teile einer Kampfschwimmerausrüstung von Sturmwind.", progress = "Konntet Ihr weitere Teile der Allianzausrüstung finden, {name}?", completion = "Gut gemacht!\n\nJetzt sind wir so bereit wie nie, uns den Naga entgegenzustellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[25948] = { id = 25948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug gewartet!", description = "Es ist an der Zeit, {class}.\n\nWir sind so bereit wie es nur geht!\n\nIch werde zu den Truppen sprechen und dann schwimmen wir ins Meer, dem Schicksal entgegen.", sourceObjective = "Sprecht mit Legionär Nazgrim an Bord der \"Ewiger Kreislauf\".", completion = "Keine Zeit für Ansprachen.\n\nAuch gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[25949] = { id = 25949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut und Donner!", description = "Die Zeit ist gekommen, um uns zur Wehr zu setzen, {race}.\n\nWir werden dieses Schiff bis zum letzten Atemzug verteidigen und dafür sorgen, dass dieser Nagaabschaum es sich zweimal überlegt, bevor er sich ihm erneut nähert!\n\nFür die Horde!", sourceObjective = "Helft Legionär Nazgrim dabei, die \"Ewiger Kreislauf\" zu verteidigen.", completion = "Der Irdene Ring hat meinen Notruf erhalten und Hilfe geschickt. Genau im rechten Moment, wie es scheint.\n\nHoffentlich können sie bald noch mehr senden. Wir sind nur eine Handvoll gegen viele.", sourceObjectiveStatus = "unverified-source-field" }
quests[25950] = { id = 25950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Sira'kess", description = "Ihr seid also <der/die> berühmte {name}, von <dem/der> alle reden? Schön, Euch kennenzulernen, Schätzelchen. Kommt, lasst mich mal ein Auge riskieren.\n\nGenug Geplauder, kommen wir zur Sache, ja? Ich will, dass Ihr für mich nach Nordwesten zu der Frontlinie der Sira'kess schwimmt und den Naga ordentlich einen vor den Latz knallt.\n\nNix Wildes. Die sind nur auf Streit aus und den sollen sie kriegen!", sourceObjective = "Tötet 10 Naga der Sira'kess.", completion = "Nicht schlecht, Herr Specht, {name}! Das wird den Schlangen zeigen, wo der Hammer hängt und wer hier der Boss ist!\n\nUnd jetzt zu dem versprochenen Umtrunk - lieber einen Branntwein aus Zuckerrohr oder einen guten Traubensaft?", sourceObjectiveStatus = "unverified-source-field" }
quests[25951] = { id = 25951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlussurteil", description = "Geht zur Brücke im Osten, schnell. Lady Naz'jar und der Tiefenlord sollten sich dort mit den verbleibenden Streitmächten aufhalten.\n\nFolgt wie immer den Anweisungen unserer Lady. Haltet die Brücke, bis wir das Ritual beenden können.\n\nSobald unsere Verbündeten eintreffen, sind die Kvaldir dem Untergang geweiht.", sourceObjective = "Haltet die Brücke auf der Terrasse von Quel'Dormir, bis Lady Sira'kess' Verbündete eintreffen.\n\nDiese Aufgabe ist Teil der Vision der Kriegsmaid der Naz'jar. Wenn Ihr zur Vision zurückkehren müsst, benutzt die Klinge der Kriegsmaid der Naz'jar an einem Zeitfokus.", progress = "Bleibt an unserer Seite, Kriegsmaid. Am heutigen Tage werden wir nicht fallen.", completion = "Ich könnte mir keine fähigere Kriegsmaid wünschen als Euch. Ihr habt Euch heute große Ehre verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[25952] = { id = 25952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überraschungsangriff", description = "Unsere Flucht aus der Muschel blieb sicher nicht unbemerkt, aber entweder wurden die Naga in den Ruinen nicht informiert oder sie sehen in uns keine Bedrohung. Ich habe nicht vor, diese Gelegenheit ungenutzt zu lassen. Wir werden jetzt gleich zuschlagen.\n\nIhr müsst Euch für mich in den unteren Bereich der Ruinen im Westen schleichen und so viele ihrer Patrouillen ausschalten, wie Ihr nur könnt. Wir können nicht riskieren, dass diese Patrouillen herausfinden, dass wir diese Höhle besetzt haben. Stellt sicher, dass keiner entkommt.", sourceObjective = "Tötet 10 Patrouillen der Azsh'ir.", completion = "Ausgezeichnete Arbeit, {class}.\n\nIch werde ein paar unserer eigenen Patrouillen losschicken um sicherzustellen, dass keine weiteren Naga in Sichtweite dieser Höhle gelangen. Wir sollten den Bereich noch in dieser Stunde gesichert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25953] = { id = 25953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schnelles Handeln", description = "Ich habe mir die Freiheit genommen, schon vorab die Lage auszuspähen. Die Naga wissen vielleicht nicht, wo wir sind, aber sie sind dennoch auf Eindringlinge vorbereitet.\n\nAbgesehen von ihren Patrouillen haben sie magische Überwachungsgeräte aufgestellt, die sie vor ungebetenen Gästen warnen. Zum Glück scheinen sie Quantität der Qualität vorzuziehen. Daher habt Ihr Zeit, sie zu zerstören, bevor jemand auf ihren Alarm reagieren kann.\n\nIch vertraue darauf, dass Ihr das erledigt, bevor unsere Soldaten eintreffen.", sourceObjective = "Zerstört 8 Überwacher der Azsh'ir.", completion = "Gut gemacht, {name}. Und genau rechtzeitig. Der Hauptmann hat gerade ein paar weitere Männer ausgesandt. Starke Kämpfer, zweifelsohne, aber ich bezweifle, dass sie so aufmerksam und geschickt sind wie Ihr.\n\nWir können uns glücklich schätzen, dass Ihr hier wart, als es bergab ging. Ich vermute stark, dass Ihr auch in Zukunft eine große Rolle spielen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[25954] = { id = 25954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach der Vergangenheit", description = "Hört mal... {name}, richtig? Ich brauche Eure Hilfe. Ich weiß schon, fast alle in dieser Höhle denken, dass wir uns im Augenblick um nichts als unser eigenes Überleben kümmern sollten, aber ich bin nicht bereit, meine Ahnen so einfach außer Acht zu lassen.\n\nZu der Zeit als Azshara regierte, war dies eine königliche Stadt der Elfen. Tief in dieser Stadt liegen die Schlüssel zu lange verschollenem Wissen und Artefakten von unermesslichem historischen Wert. Bitte, haltet doch nach interessanten Gegenständen Ausschau, wenn Ihr ohnehin schon in der Stadt seid.", sourceObjective = "Untersucht die 4 unversehrten Statuen in den Gärten von Vashj'ir.", completion = "Vielen Dank, dass Ihr diese Sache ernst genommen habt.\n\nDies ist einer der ersten unstreitigen Belege für andere Mitglieder der Familie Vashj. Sehr interessant. Und ich habe bis jetzt noch nie von den beiden Personen gehört, die Ihr erwähnt habt.\n\nSo viel von unserer Geschichte ging während der Großen Zerschlagung verloren. Es ist ganz schön aufregend, eine Gelegenheit zu bekommen, einen Teil davon wieder aufzudecken.", sourceObjectiveStatus = "unverified-source-field" }
quests[25955] = { id = 25955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besserer Standort", description = "Diese Höhle ist unsere einzige Zuflucht. Es ist keine Hilfe unterwegs. Was immer geschieht, diese Höhle muss geschützt bleiben, sonst werden wir alle hier unten sterben.\n\nWir brauchen einen Vorposten, von dem aus wir die Angriffe starten können. Etwas, das wir verteidigen können.\n\nIm östlichen Teil der Ruinen auf der untersten Ebene solltet Ihr die nördlichen Gärten, die Passage unter der Hauptstruktur im Westen der Gärten und die Gebäudegruppe in der südöstlichen Ecke der Ruinen unter den Brücken erkunden.\n\nBringt mir alle Informationen, die Ihr finden könnt.", sourceObjective = "Späht den nördlichen Teil der Gärten von Quel'Dormir, den Tunnel unter den Ruinen im Westen der Gärten und die Gebäude im Süden der Gärten aus. Bleibt auf der untersten Ebene der Ruinen.", completion = "Das sind hilfreiche Informationen. Ihr habt scharfe Augen, {class}.\n\nEs klingt so, als ob das Gebäude nördlich der Gärten einen guten Vorposten abgeben könnte. Ich werde sofort ein paar Männer losschicken, die die Verteidigungsanlagen vorbereiten. Wir werden uns so schnell wie möglich da drüben neu aufstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25956] = { id = 25956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Schlachtfeld", description = "<Überall um Euch herum liegen Relikte der wilden Schlacht. Die Nagaskelette überraschen Euch nicht, aber die Waffen und Überreste ihrer offensichtlichen Gegner dafür viel mehr.>\n\n<Inmitten der Knochen entdeckt Ihr ein auffälliges Stück Metall, das aus einem der Schädel herausragt. Es ist schwer zu sagen, zu welcher Art Waffe das Metall einst gehört haben mag, aber es steht weit genug hervor, dass Ihr es als Beweis mitnehmen könnt.>\n\n<Irgendjemand in der Höhle ist an dieser Erkenntnis sicher interessiert.>", sourceObjective = "Bringt das Bruchstück zurück zur Ruhestatt der Legion.", progress = "Ja, {class}?", completion = "Wirklich interessant.\n\nDie Überreste, die Ihr beschreibt, klingen stark nach den Meervrykul, auf die wir in Nordend getroffen sind. Ich bezweifle stark, dass sie bereit sind, ein Bündnis mit uns einzugehen. Egal, wie gut die Gründe sein mögen. Dennoch kann diese Information uns bestimmt in der Zukunft helfen.\n\nWenn die Zeit es zulässt, werde ich weiter darüber nachdenken. Bis dahin vielen Dank, dass Ihr mich darauf aufmerksam gemacht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25957] = { id = 25957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Die Invasion von Vashj'ir", description = "Das Bruchstück, das Ihr gefunden habt, scheint von Nagahand geschaffen zu sein. Ich hatte gehofft, ein starkes Fokusobjekt wie dieses für einen Zauber zu finden, an dem ich gerade arbeite. Mit diesem Zauber könnten wir einen Blick in die kürzliche Vergangenheit werfen.\n\nIch habe die Klinge verzaubert, aber Ihr müsst sie an einen Ort bringen, von dem wir wissen, dass ihr Besitzer sich dort aufgehalten hat. Ich möchte, dass Ihr zurück an die Stelle reist, wo Ihr die Klinge gefunden habt und sie dort benutzt.\n\nVielleicht können wir so mehr über die Pläne der Naga hier erfahren. Oder noch besser: Vielleicht finden wir einen ihrer Schwachpunkte, sodass wir eine bessere Chance haben, sie zu besiegen.", sourceObjective = "Benutzt die Klinge der Kriegsmaid der Naz'jar auf dem Schlachtfeld am südöstlichen Ende der Ruinen.", completion = "Eine Kriegsmaid? Davon habe ich noch nie gehört.\n\nSo wie Ihr mir die Sache schildert, scheinen die Truppen der Naga weitaus zahlreicher zu sein, als der Hauptmann es sich in seinen kühnsten Träumen vorstellt. Vielleicht können wir mehr von der Klinge erfahren, wenn wir andere Orte finden, an denen diese Kriegsmaid zugegen war. Ich habe nur Angst um den Hauptmann und seine Soldaten. Wir müssen sie warnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25958] = { id = 25958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick nach vorne", description = "Der Hauptmann hat die Informationen, die Ihr für ihn gesammelt habt, genutzt, um einen Vorposten unter der Terrasse im Westen einzurichten. Er trifft dort Vorbereitungen für eine Art Angriff auf die Naga.\n\nIhr solltet sofort zu ihm gehen und ihn über das Ausmaß dessen, was Ihr beobachtet habt, unterrichten. Unsere Streitmacht ist klein. Ich mache mir Sorgen um unsere Soldaten, wenn wir uns in einen waghalsigen Angriff stürzen.\n\nNehmt mein Seepferdchen. Es kennt den Weg.", sourceObjective = "Sprecht mit Hauptmann Übeldorn nördlich der Gärten von Quel'Dormir.\n\nBenutzt das Seepferdchen von Wellensprecherin Tulra, um den Vorposten schnell zu erreichen.", completion = "Schön Euch wiederzusehen, {class}. Ich dachte schon fast, wir hätten Euch bei dem törichten Botengang für die Wellensprecherin verloren.\n\nIst dabei wenigstens etwas herausgekommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[25959] = { id = 25959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deutliche Ziele", description = "Ich verstehe. Eure Nachrichten sind düster, aber ich bin nicht ganz unvorbereitet auf eine solche Lage. Ich wusste, dass unser Plan riskant ist, solange wir die genauen Zahlen der Naga nicht kennen, aber zu diesem Zweck haben wir ja diesen Vorposten eingerichtet.\n\nIch will Euch nicht belügen, {class}. Wenn wir die Naga nicht beschäftigt halten, werden sie uns angreifen. Wir haben weder die Anlagen noch die Männer, um eine geeignete Verteidigung zu errichten, daher kommt das für uns nicht in Frage.\n\nWir brauchen mehr Zeit. Könnt Ihr ihre Reihen im Süden, unter der Terrasse, ein wenig ausdünnen?", sourceObjective = "Tötet 10 Naga der Streitmächte, die sich unter der südlichen Terrasse auf der Grundebene zusammenziehen.", completion = "Auch im Süden scheinen sich mehr Naga zusammenzuziehen, als unsere Berichte angenommen haben. Wir müssen uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25960] = { id = 25960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht ganz unvorbereitet", description = "Ich habe Euer Gespräch mit dem Hauptmann gehört. Ich weiß, dass das, was wir tun, wahnsinnig klingt, aber wir haben einfach keine andere Wahl. Dort in der Höhle sind Leute, die sich auf uns verlassen.\n\nIch habe Aufklärer auf den verschiedenen Klippen in der Gegend aufstellen lassen. Bei den ganzen verstreuten Nagaspähern in der Gegend geht ihnen die Munition rasend schnell aus. Bringt ihnen mehr Armbrustbolzen, um uns etwas Zeit zu verschaffen.", sourceObjective = "Bringt 8 Schachteln mit Armbrustbolzen zu den Aufklärern der Horde auf den Felsvorsprüngen um das nördliche Ende der Gärten von Quel'Dormir.", completion = "Ihr seid wahrscheinlich der zuverlässigste {race}, den ich je getroffen habe. Ich wünschte, meine Männer wären nur halb so gründlich wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[25962] = { id = 25962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausreichende Inspiration", description = "Ich war schon überall. Habe alle möglichen Dinge in die Luft gejagt. Ich dachte, ich hätte vielleicht Probleme damit, den neusten Entwicklungen zu folgen. Ihr wisst schon, wegen dem Wasser und so, aber es ist alles nur eine Frage der Inspiration.\n\nIch habe etwas gefunden, das explosiv genug ist, um Bomben daraus zu bauen. Unter der Terrasse im Südwesten hängen ein paar Tangblasen herab. Normalerweise speichert Tang Gas, das ihn zum schweben bringt, doch dieses schwere Gas ist ganz anders. Es bringt ihn dazu, hängen zu bleiben. Außerdem eignet es sich perfekt für Explosionen.\n\nKönnt Ihr mir etwas davon sammeln?", sourceObjective = "Sammelt 8 aufgedunsene Tangblasen, die unterhalb der südlichen Terrasse hängen.", progress = "Tick, tack, tick, tack. Immer in Eile. Keine Zeit für neue Errungenschaften. Was würde ich nur dafür geben, wieder ein Labor zu haben!", completion = "Ihr seid wirklich mutig! Ich habe gesehen, wie Ihr alle möglichen Arten von Murlocs, Naga und spitzzähnigen Fischen bekämpft habt, aber das war nichts im Vergleich hierzu! Wie Ihr Euch diese Tangblasen einfach so unter den Arm klemmt ist eine ganz neue Ebene der Furchtlosigkeit. BUMM! Ihr könntet jede Sekunde in die Luft gehen.\n\nIhr seid ein {race} nach meinem Geschmack.", sourceObjectiveStatus = "unverified-source-field" }
quests[25963] = { id = 25963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzangriff", description = "Wir haben alles, was wir für den Angriff brauchen.\n\nWenn das, was Ihr sagt, wahr ist, solltet Ihr Euch während des Angriffs lieber fest an Euer Reittier klammern. Es ist sehr unwahrscheinlich, dass jemand von uns, der auf das offene Meer gerät, den Naga davonschwimmen kann.\n\nTötet so viele wie möglich. Wir werden den Angriff führen und treffen uns dann oben auf der südlichen zerbrochenen Terrasse, sobald wir die Sprengsätze aufgebraucht haben. Hoffentlich sind dann nur noch so wenige übrig, dass wir sie auf die altmodische Art erledigen können.", sourceObjective = "Sprecht mit Fiasco Siedefeix, um Euch dem Überfall anzuschließen. Benutzt dann Euren improvisierten Sprengstoff, um 100 Soldaten der Azsh'ir, 20 Wellenkreischer der Azsh'ir und 12 Archaeen der Azsh'ir zu töten.", completion = "Ihr habt Euch da oben großartig geschlagen, Soldat! Ihr habt ihre Reihen zerschmettert, aber es waren viel mehr als geplant und die meisten unserer Truppen sind da draußen in den Massen der Naga untergegangen.\n\nWir müssen diese Position so lange wie möglich halten, um ihnen Zeit zu erkaufen. Hoffentlich schaffen es einige von ihnen noch zum Treffpunkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25964] = { id = 25964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallen, aber nicht vergessen", description = "Das war ein Desaster! Die meisten unserer Männer sind Speeren zum Opfer gefallen, noch bevor sie überhaupt in der Nähe des Treffpunkts waren!\n\nWir werden diese Position sicher nicht mehr lange halten können, bevor die Naga uns überrennen. Wir müssen uns in den Südwesten begeben und so viele der Männer retten, wie wir nur können. Geht und tut alles, was in Eurer Macht steht.\n\nLange halten sie nicht mehr durch. Bitte, beeilt Euch!", sourceObjective = "Rettet 6 verletzte freiwillige Angreifer.", completion = "Danke. Wirklich.\n\nWir müssen diese Männer so schnell wie möglich von hier wegbringen. Ich bin mir sicher, wir begegnen uns schon bald am Vorposten.", sourceObjectiveStatus = "unverified-source-field" }
quests[25965] = { id = 25965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einschätzung des Erfolgs", description = "Boshafte Rüpel… Sie haben mit diesen Speeren einen ganz schönen Schaden angerichtet.\n\n<Der Hauptmann zuckt ein bisschen, als er sich die Wunde an der Seite hält.>\n\nWir werden hier so lange wie möglich durchhalten, damit alle Männer es schaffen. Ich brauche jemanden, der ausspioniert, wie viele es noch sind. Ich möchte wissen, wie viel Schaden wir ihnen zugefügt haben.\n\nEine ihrer größten Gruppen befand sich im nordwestlichen Teil dieser runden Terrasse und die andere ein wenig weiter im Norden, in dem kleinen Tunnel, ebenfalls auf der mittleren Ebene der Ruinen.\n\nInterressiert an ein wenig Arbeit als Kundschafter?", sourceObjective = "Späht den Rand der runden Terrasse im Nordwesten und den Tunnel unter der Haupttreppe im Norden aus. Beides befindet sich auf der Terrasse von Nar'shola, in der mittleren Ebene der Ruinen.", progress = "Wisst Ihr schon etwas Neues… zu ihren Zahlen?", completion = "Immer noch so viele? Sie müssen hier etwas sehr Wichtiges vorhaben, wenn sie so zahlreich auftauchen.\n\nIch will ehrlich zu Euch sein, {name}, denn das bin ich Euch schuldig: Ich weiß nicht, wie viel Hoffnung besteht. Wir werden uns in Kürze zurückziehen, aber wir werden uns nicht verteidigen können, falls sie zurückschlagen. Wir haben keinen Ort, an den wir flüchten können... Und uns gehen die Optionen aus.\n\nEs tut mir leid, ich sollte meine Gedanken für mich behalten. Tut mir einen Gefallen und erwähnt den Truppen gegenüber nichts davon. Ich werde mir etwas einfallen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25966] = { id = 25966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Visionen der Vergangenheit: Das Massaker von Biel'aran", description = "Ja, ich weiß, es ist in Zeiten wie diesen viel verlangt, aber Ihr müsst Euch einen Moment lang von dieser Niederlage losreißen.\n\nIch werde mich um diese Soldaten kümmern. Ihr müsst jedoch den Ort im Westen finden, an dem die Schlacht mit dem General der Kvaldir ausgetragen wurde, von der Ihr mir erzählt habt. Von dort aus solltet Ihr mehr über die Erlebnisse der Kriegsmaid erfahren können. Ich habe das untrügliche Gefühl, dass der Schlüssel zum Sieg über die Naga in dieser Kriegsmaid liegt.\n\nBitte, beeilt Euch. Ich tue alles, was ich kann, um Euch Zeit zu verschaffen.", sourceObjective = "Werdet Zeuge des weiteren Verlaufs der Geschichte der Kriegsmaid, indem Ihr ihre gebrochene Klinge am Sterbeort des Generals der Kvaldir benutzt.", completion = "Ihr seid fertig! Gerade rechtzeitig. Ich glaube nicht, dass wir ihnen noch lange hätten standhalten können.\n\nEin Artefakt? Ist das vielleicht etwas, was wir gegen die Naga einsetzen können? Ich schätze, dann müssten wir es erstmal finden.\n\nDoch möglicherweise müssen wir uns erst dringenderen Angelegenheiten widmen, bis wir die Gelegenheit haben, dies weiter zu verfolgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[25967] = { id = 25967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltlos", description = "Ihr müsst mich später auf den neusten Stand bringen. Im Augenblick müssen wir hier verschwinden, bevor weitere Naga vorrücken. Begebt Euch zum Vorposten auf der Ebene unter uns.\n\nNehmt mein Seepferdchen. Wir treffen uns dort in Kürze.", sourceObjective = "Benutzt das Seepferdchen von Wellensprecherin Tulra, um zu Hauptmann Übeldorn nördlich der Gärten von Quel'Dormir zurückzukehren.", completion = "Ihr habt es geschafft! Nach dem Angriff auf den Vorposten dachte ich, wir wären die einzigen Überlebenden. Schön, Euch in einem Stück zu sehen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[25968] = { id = 25968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verzweifelter Plan", description = "Toldrek und Fiasco sind aufgebrochen, um Hilfe zu holen. Die Handelsrouten sind nicht weit entfernt, daher besteht die Chance, dass sie Erfolg haben. Ich wage es jedoch nicht, den anderen zu viel Hoffnung zu machen.\n\nOffen gestanden haben wir keine andere Wahl. Wir werden hier nicht viel länger aushalten. Früher oder später werden die Naga uns finden und... nun... Ihr habt selbst gesehen, wie viele es sind.\n\nIhr solltet die beiden auf dem Biel'arangrat im Südosten suchen. Ich kümmere mich solange so gut es geht um die Sicherheit der anderen hier.", sourceObjective = "Trefft Euch mit Fiasco Siedefeix auf dem Biel'arangrat.", completion = "Schaut Euch an, Ihr seid ein echter Held des Meeres! Der Ärger kommt. Ihr kommt. Und rettet den Tag. Ihr müsst stolz auf Euch sein!\n\nWir haben einen brillanten Plan. Er ist herrlich einfach, abgesehen von den Bewohnern in der Gegend hier. Und jetzt, da Ihr hier seid, wird er noch einfacher!", sourceObjectiveStatus = "unverified-source-field" }
quests[25969] = { id = 25969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feindliche Gewässer", description = "Fiasco kam mit einer Art Ballon hierher, den er von einem unserer Schiffe gerettet hat. Er hat versucht, damit nach oben zu schweben, aber diese Schlickhautschnorrer kamen aus dem Nichts und haben das Ding umschwärmt.\n\nJetzt hat er eine Idee für einen weiteren Ballon, aber wir müssen sicherstellen, dass es nicht wieder genauso abläuft. Ihr müsst diese Gilblins töten. Oder zumindest so viele, dass sie etwas mehr Angst vor uns haben.", sourceObjective = "Tötet 10 Schlickhautschnorrer.", completion = "Je weniger Gilblins, desto besser.\n\nIch bin froh, dass sie so primitiv sind. Ich hätte keine Lust, mich mit einem Volk von schwimmenden Technikliebhabern auseinanderzusetzten. Überhaupt keine Lust.", sourceObjectiveStatus = "unverified-source-field" }
quests[25970] = { id = 25970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer vorbereitet", description = "Es ist nicht weit bis zur Oberfläche. Eigentlich alles kein Problem. Doch es ist nicht leicht, Ausrüstung nach da oben zu bringen. Sie ist einfach zu schwer.\n\nAlle Schiffe in der Flotte der Horde sind mit einer Überlebensausrüstung ausgestattet. Ich hatte einen Ballon aus so einer Überlebensausrüstung, aber er musste sich leider den Widrigkeiten geschlagen geben. Ich brauche noch eine Überlebensausrüstung.\n\nSüdöstlich von hier liegt ein Schiff. Wollen wir hoffen, dass die Überlebenden dumm genug waren, die Überlebensausrüstung nicht mitzunehmen. Mehr zum Überleben für uns!", sourceObjective = "Besorgt eine Überlebensausrüstung der Horde.", progress = "Eine ganze Kiste voller aufregender Dinge! Genau das brauche ich. Mehr Aufregung in meinem Leben.\n\nKeine Sorge, ich teile mit Euch.", completion = "Mal sehen, mal sehen… Leuchtpistole… Ballon… kein Seil. Nie ist ein Seil dabei. Furchtbar unpraktisch, wenn Ihr mich fragt. Seil sollte zum Pflichtinhalt gehören.", sourceObjectiveStatus = "unverified-source-field" }
quests[25971] = { id = 25971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seilakrobatik", description = "In Überlebensausrüstungen sind nie Seile enthalten. Das ergibt doch keinen Sinn! Seile und Bomben, das ist alles, was sie enthalten sollten. Der Rest des Krams ist einfach nur Platzverschwendung.\n\nBis auf den Ballon vielleicht. Der kommt uns jetzt gerade gelegen.\n\nIch wette, diese Kvaldir haben Seile. Sie fahren immer in Booten herum, knüpfen Knoten und ziehen sich sogar Netze an. Geht und stehlt ihnen ein paar Seile! Ich brauche dringend welche für meinen Plan. Seile sind nicht optional!", sourceObjective = "Sammelt 8 Kvaldirseile.", progress = "Das Seil bindet die Bestandteile des Plans zusammen!", completion = "Das ist spitze! Ich liebe es. Es sollte perf… iiihh! Ist das etwa aus Haaren geflochten?\n\nEgal. Fast fertig. Dieses Ding ist im Seilumdrehen bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[25972] = { id = 25972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre und Privileg", description = "Fertig! Ich bin mir ganz sicher, dass es funktionieren wird. Und nicht ein Schnorrer in Sicht, der wieder ein Loch hineinstoßen könnte! Gut gemacht.\n\nToldrek ist bereits nach oben geschwommen, um ihn zu packen. Er macht sich Sorgen um die Strömung und all so was. Er meinte aber, er würde Euch die Ehre überlassen. Netter Kerl - Keine Ahnung, wie er am Leben bleibt.\n\nSchwimmt zum Ballon an der Oberfläche, nehmt die Leuchtpistole aus der Kiste und haltet am Horizont nach Schiffen der Horde Ausschau. Wenn Ihr welche seht, schießt das Leuchtfeuer in ihre Richtung. Das war es auch schon!\n\nAuftauchen, Schwimmen, Signalfeuer, Rettung! Der letzte Teil gefällt mir am besten.", sourceObjective = "Schwimmt zur Oberfläche, holt die Leuchtpistole und feuert ein Rettungsleuchtfeuer in Richtung der Hordenschiffe.", progress = "Das sind keine Handelsschiffe, das sind Kriegsschiffe. Dennoch haben wir unglaubliches Glück. Schießt das Leuchtfeuer ab und betet, dass sie es sehen.", completion = "Perfekt! Ob im Kampf oder nicht, das können sie nicht übersehen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[25973] = { id = 25973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommene Nachrichten", description = "Sie schicken bestimmt ein Ruderboot. Das kann ein bisschen dauern. Ich bleibe hier, um mich mit ihnen in Verbindung zu setzen.\n\nIhr müsst sofort zur Höhle zurückkehren und Bescheid geben, dass Rettung auf dem Weg ist. Wir können nur hoffen, dass die Naga sie noch nicht gefunden haben.\n\nGeht. Schwimmt schnell, {name}.", sourceObjective = "Kehrt zu Legionär Nazgrim an der Ruhestatt der Legion zurück.", completion = "Das sind die besten Nachrichten seit einer Ewigkeit. Wir werden die Überlebenden so schnell wie möglich an die Oberfläche bringen. Vielleicht können wir vergessen, dass dieser Alptraum überhaupt stattgefunden hat.\n\nDanke, {name}. Ihr habt hier unten Euren Wert mehr als deutlich bewiesen. In der Horde ist ein Ehrenplatz für Euch sicher.\n\nIhr solltet Euch mit uns an den Schiffen treffen, wenn Ihr Euch gebührend von den Naga verabschiedet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[25974] = { id = 25974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod den Sira'kess", description = "Ihr seid also <dieser/diese> {name}, von <dem/der> alle sprechen? Schön, Euch endlich zu treffen.\n\nNun, genug der Worte. Lasst uns zur Sache kommen. Ihr müsst für mich nach Nordwesten zur Frontlinie der Sira'kess schwimmen und schnell diese Naga erledigen.\n\nNichts Aufregendes. Sie sind auf einen Kampf aus und wir werden ihnen einen bieten. Mit 'wir' meine ich natürlich Euch.", sourceObjective = "Tötet 10 Naga der Sira'kess.", completion = "Sehr gut, {name}! Das wird diesen Naga zeigen, wer hier die Hosen anhat!\n\nAlso, zu unserem Schlückchen. Was mögt Ihr lieber? Rum oder Wein?", sourceObjectiveStatus = "unverified-source-field" }
